	["Buscar en el diario"] = "도감 검색",
	["Buscar equipo para mi nivel"] = "내 레벨에 맞는 장비 찾기",
	["Buscar guías por nombre o zona"] = "이름이나 지역으로 가이드 검색",
	["Buscar otra vez"] = "다시 찾기",
	["Buscar por nombre, zona o quién lo mandó"] = "이름, 지역, 보낸 사람으로 검색",
	["Buscar: pasto, niebla, sombras..."] = "검색: 풀, 안개, 그림자...",
	["Buzones, entrenadores, banco, subasta, reparar..."] = "우체통, 전문가, 은행, 경매장, 수리...",
	["Buzón"] = "우체통",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "이름으로 검색하세요. 가방에 있으면 달성됩니다.",
	["CPS"] = "HPS",
	["Cabeza"] = "머리",
	["Cada 2 niveles"] = "2레벨마다",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "위상마다 용군단을 이끌어요: 알렉스트라자는 붉은용, 이세라는 녹색용, 노즈도르무는 청동용, 말리고스는 푸른용, 넬타리온은 검은용.",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Alfa가 바꾼 설정은 모두 이전 값으로 돌아갑니다. 필터는 바뀌지 않습니다.",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "각 알림과 이유는 %d번까지 글자와 함께 나오고, 그 뒤에는 아이콘만 남습니다.",
	["Cada bloqueo te da ira: nunca te falta."] = "막을 때마다 분노를 얻어 부족할 일이 없습니다.",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "가방마다 이름과 칸 수가 있는 블록으로 나눕니다.",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "각 행동 단축 버튼에 스타일의 테두리와 배경, 사각 아이콘, 단축키와 개수에 Alfa 글꼴.",
	["Cada casilla en su lugar, como en tus bolsas."] = "모든 칸을 가방에 있는 그대로 보여 줍니다.",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "직업마다 25, 45, 60레벨에 유산 도전을 줘요. 다른 직업을 키워도 계정에 점수가 쌓여요.",
	["Cada cofre o tesoro conocido."] = "알려진 모든 상자와 보물입니다.",
	["Cada crítico hace sangrar."] = "치명타마다 출혈을 일으킵니다.",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "매주 일요일 가시덤불 골짜기에서: 특별한 물고기 떼에서 얼룩무늬 별미고기 40마리를 가장 먼저 가져오는 사람이 우승해요. 상품으로 바꿀 수 있는 희귀한 물고기도 나와요.",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "모든 던전과 공격대 입구를 레벨 범위와 함께 표시합니다. 클릭: 해당 페이지, Shift+클릭: 화살표가 안내합니다.",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "각 대사는 최대 세 번까지 나옵니다. 이걸 누르면 처음부터 다시 나옵니다.",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "치명타가 터질 때마다 적이 출혈 상태가 됩니다. 손쉽게 얻는 추가 피해입니다.",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "약초마다 자라는 곳이 있어요. 물가에, 산에, 나무 아래에.",
	["Cada lugar conocido donde aparece un enemigo raro."] = "희귀 몹이 나타나는 알려진 모든 위치입니다.",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "썬더 블러프의 고원은 저마다 쓰임이 있어요. 장로와 드루이드의 고원, 정령의 고원, 사냥꾼의 고원.",
	["Cada misión que terminas te hace más fuerte."] = "퀘스트를 하나 끝낼 때마다 더 강해져요.",
	["Cada nivel"] = "레벨마다",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "환영 설정의 각 단계를 끝까지 스크롤할 수 있어, 닫았다가 다시 열 필요가 없습니다.",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "프리셋마다 이미 아는 주문으로 클릭을 채웁니다. 나중에 치유 페이지에서 원하는 대로 바꾸세요.",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "도전 하나에 1점입니다. Forever 출시 시점의 도전 수: %d. 캐릭터마다 최대 사용 가능: %d.",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "새 버전마다 늑대 인트로와 이런 업데이트 노트로 맞이합니다.",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "케언 블러드후프는 썬더 블러프에서 다스리지만, 그림토템의 마가사는 겉보기만큼 그를 좋아하지 않아요.",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "케언 블러드후프는 하이잘 산에서 스랄과 함께 군단에 맞서 싸웠어요.",
	["Caja para escribir con el estilo"] = "스타일을 입힌 입력창",
	["Calculando"] = "계산 중",
	["Calculando la vuelta más corta…"] = "가장 짧은 순환 경로를 계산하는 중…",
	["Calidad"] = "품질",
	["Calidad de la niebla"] = "안개 품질",
	["Calidad de las sombras"] = "그림자 품질",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "춤추기, 웃기, 박수 등 감정 표현의 음성을 끕니다.",
	["Calla los ruidos de las mascotas, como el bostezo de los gatos de cazador."] = "사냥꾼 고양이가 하품하는 소리 같은 소환수 소리를 끕니다.",
	["Cambia a «Todo» para ver su botín completo."] = "모든 전리품을 보려면 «전체»로 바꾸세요.",
	["Cambia al mapa de Alfa en esta zona: todo el mundo en un solo mapa, con zoom y tus marcadores."] = "이 지역의 Alfa 지도로 바꿉니다. 온 세상을 확대할 수 있는 한 지도에 마커와 함께 보여 줍니다.",
	["Cambia el modo limpio del mapa"] = "지도 깔끔 모드 전환",
	["Cambia lo que quieras: se guarda al momento."] = "원하는 대로 바꾸세요. 바로 저장됩니다.",
	["Cambiar"] = "변경",
	["Cambiar de forma te quita lentitudes y raíces: úsalo para escapar."] = "변신하면 감속과 이동 불가 효과가 풀립니다. 도망칠 때 쓰세요.",
	["Cambiar el tamaño"] = "크기 조절",
	["Cambiar esta meta"] = "이 목표 변경",
	["Cambiar guía"] = "가이드 변경",
	["Cambiar la meta"] = "목표 변경",
	["Cambiar nombre..."] = "이름 바꾸기...",
	["Cambiar o borrar"] = "변경 또는 삭제",
	["Cambias de actitud según la pelea sin perder ira."] = "전투 상황에 따라 분노를 잃지 않고 태세를 바꿉니다.",
	["Cambias de actitud sin perder ira."] = "분노를 잃지 않고 태세를 바꿉니다.",
	["Cambias de actitud sin perder ira: puedes pasar a defensiva cuando se complica."] = "분노를 잃지 않고 태세를 바꿉니다. 상황이 어려워지면 방어 태세로 바꿀 수 있습니다.",
	["Cambiaste %d ajustes aquí. Volver a ponerlos al entrar está apagado (Avanzado)."] = "여기서 설정 %d개를 바꿨습니다. 접속할 때 다시 적용하기는 꺼져 있습니다(고급).",
	["Camina por el agua: espérenlo en tierra y atráiganlo con un ataque a distancia."] = "물속을 걸어 다닙니다. 땅에서 기다렸다가 원거리 공격으로 끌어오세요.",
	["Caminar"] = "걷기",
	["Camisa"] = "속옷",
	["Campana"] = "종",
	["Campo de visión"] = "시야각",
	["Canal oculto: %s (%s, número %s, intentos %d)"] = "숨은 채널: %s(%s, 번호 %s, 시도 %d회)",
	["Cancelar"] = "취소",
	["Cantidad: %d"] = "수량: %d",
	["Capas de Alfa: elige qué se ve en el mapa"] = "Alfa 레이어: 지도에 표시할 것 선택",
