	["Clic: elegir qué hace. Clic derecho: dejarla sin acción."] = "클릭: 할 일 고르기. 오른쪽 클릭: 비워 두기.",
	["Clic: la flecha te lleva"] = "클릭: 화살표가 안내합니다",
	["Clic: la flecha te lleva al más cercano, por tiempo de camino."] = "클릭: 이동 시간 기준으로 가장 가까운 곳으로 화살표가 안내합니다.",
	["Clic: la flecha te lleva aquí."] = "클릭: 화살표가 이곳으로 안내합니다.",
	["Clic: la flecha te lleva. Clic derecho: ya no mostrarla."] = "클릭: 화살표가 안내합니다. 오른쪽 클릭: 더 이상 표시 안 함.",
	["Clic: la lista de pasos. Rueda: mirar otros pasos sin cambiar nada."] = "클릭: 단계 목록. 휠: 아무것도 바꾸지 않고 다른 단계 보기.",
	["Clic: ocultarlo en el modelo."] = "클릭: 모델에서 숨기기.",
	["Clic: opciones  ·  Mayús+clic: seguir"] = "클릭: 옵션  ·  Shift+클릭: 따라가기",
	["Clic: ponerlo en tu caña. Clic derecho: usarlo siempre que tu tecla ponga cebo."] = "클릭: 낚싯대에 달기. 오른쪽 클릭: 키가 미끼를 달 때 항상 이것 사용.",
