	["Combustión: tus hechizos de fuego hacen más críticos un rato."] = "발화: 잠시 화염 주문의 치명타가 늘어납니다.",
	["Combínala con Encantamiento para desencantar lo que coses y no uses."] = "마법부여와 함께 배우면 만든 옷 중 안 쓰는 걸 마력 추출할 수 있어요.",
	["Combínala con Herboristería: así recoges tú lo que necesitas."] = "약초 채집과 함께 배우세요. 필요한 걸 직접 모을 수 있어요.",
	["Combínala con Minería: casi todo lo que fabricas lleva metal."] = "채광과 함께 배우세요. 만드는 거의 모든 것에 금속이 들어가요.",
	["Combínalo con Sastrería: la tela te da objetos verdes para desencantar."] = "재봉술과 함께 배우세요. 천으로 만든 녹색 아이템을 마력 추출할 수 있어요.",
	["Come y bebe entre peleas: recuperas vida y maná mucho más rápido."] = "전투 사이에 먹고 마셔요. 생명력과 마나가 훨씬 빨리 회복돼요.",
