	["Descontenta"] = "불만족",
	["Descubriste a %s"] = "%s 발견",
	["Descubriste a %s (%s)."] = "%s 발견(%s).",
	["Desde Auberdine sale un barco al muelle de Rut'theran, al pie de Teldrassil."] = "아우버다인에서 텔드랏실 아래 루테란 부두로 가는 배가 떠나요.",
	["Desde cero"] = "처음부터",
	["Desde cuántas habilidades"] = "기술 개수 기준",
	["Desde el nivel 10"] = "10레벨부터",
	["Desde el nivel 20"] = "20레벨부터",
	["Desde nivel %d"] = "%d레벨부터",
	["Desde siempre"] = "전체 기간",
	["Desde tu última visita también hubo cambios en %s: los ves en «Ver todo lo nuevo»."] = "지난 방문 이후 %s에도 변경 사항이 있었습니다. «새 소식 모두 보기»에서 확인하세요.",
	["Desencanta los objetos verdes y azules que no uses para sacar polvos, esencias y fragmentos."] = "안 쓰는 녹색, 파란색 아이템을 마력 추출해서 가루, 정수, 조각을 얻으세요.",
	["Desencantar ≈ %s"] = "마력 추출 ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "마력 추출: 아이템당 ≈ %s%s. 마법부여 %d 필요.",
	["Deseo de muerte: mucho más daño un rato; úsalo en peleas largas."] = "죽음의 소원: 잠시 피해가 크게 늘어납니다. 긴 전투에서 쓰세요.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "몬스터가 출혈 중일 때 분쇄의 피해가 늘어납니다. 깊은 상처에 필요합니다.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "분쇄의 피해가 늘어납니다. 깊은 상처에 필요합니다.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "분쇄로 제압 기회가 늘어납니다: 회피할 수 없는 공격이 더 많아집니다.",
	["Deshacer"] = "되돌리기",
	["Deshacer preajuste"] = "프리셋 되돌리기",
	["Desmarca las metas hechas de este personaje (las que ya se cumplen se vuelven a marcar solas)."] = "이 캐릭터의 완료한 목표 표시를 지웁니다(이미 달성된 것은 자동으로 다시 표시됩니다).",
	["Desmarcar"] = "표시 해제",
	["Desollar es de las formas más fáciles de hacer oro mientras subes de nivel."] = "무두질은 레벨업하면서 골드를 버는 가장 쉬운 방법 중 하나예요.",
	["Desollar y Peletería van de la mano: tú consigues el cuero y tú lo trabajas."] = "무두질과 가죽세공은 짝꿍이에요. 가죽을 직접 얻어서 직접 다뤄요.",
	["Despojar más rápido"] = "더 빠른 전리품 획득",
	["Después"] = "나중에",
	["Después de"] = "다음 이후",
	["Después de cada golpe, regresa a tu lugar rápido."] = "밀쳐질 때마다 빨리 제자리로 돌아오세요.",
	["Después de estos siguen %d más."] = "그다음 %d개가 더 있습니다.",
	["Después de otra"] = "다른 퀘스트 다음",
	["Después de tu segunda pelea, aquí ves la de antes."] = "두 번째 전투가 끝나면 여기에서 이전 전투를 볼 수 있습니다.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "치명타 뒤에 공격이 빨라집니다: 더 많은 공격, 더 많은 분노.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "처치한 뒤 제단의 화로에 불을 붙이면 적이 몰려옵니다. 미리 준비하세요.",
	["Después del combate"] = "전투 후",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "첫 우두머리를 처치하면 내 진영의 포로가 문을 열어 줍니다. 말을 걸어 보세요.",
	["Después sigue"] = "다음 단계",
	["Después: %d %% del nivel %d"] = "이후: %d %% (%d레벨)",
	["Después: nivel %d"] = "이후: %d레벨",
	["Destino"] = "목적지",
	["Destrucción"] = "파괴",
	["Destrucción para subir"] = "레벨업용 파괴",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "처치한 것의 가죽을 벗겨 내 가죽 방어구를 만들고, 남는 것은 팝니다.",
	["Desuello"] = "무두질",
	["Desvanecer objetos lejanos"] = "먼 사물 흐리게",
	["Desvías golpes con tu arma."] = "무기로 공격을 받아 냅니다.",
	["Detalle al pasar el ratón"] = "마우스를 올리면 상세 정보",
	["Detalle de la guía"] = "가이드 상세",
	["Detalle de los edificios"] = "건물 세부 묘사",
	["Detalle de los objetos"] = "사물 세부 묘사",
	["Detalle del agua"] = "물 세부 묘사",
	["Detalle del terreno"] = "지형 세부 묘사",
	["Detalle fino"] = "미세 묘사",
	["Detalle fino de cada zona"] = "지역 세부 묘사",
	["Detener"] = "중지",
	["Detener (%d/%d)"] = "중지 (%d/%d)",
	["Detrás de «%s» hay más de lo que parece. ¿Te la cuento?"] = "«%s» 뒤에는 보이는 것보다 많은 게 있어요. 들려줄까요?",
	["Devolver los avisos a su lugar"] = "알림 위치 초기화",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "Alfa가 건드린 설정을 모두 이전 값으로 되돌리고 더 이상 유지하지 않습니다.",
	["Devuelve los valores que tenías antes del último preajuste."] = "마지막 프리셋 전의 값으로 되돌립니다.",
	["Diario"] = "일지",
	["Diario de mazmorras"] = "던전 도감",
	["Diario de pesca"] = "낚시 도감",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "포함된 세부 텍스처로 각 지역의 전체 그림을 지역 모양에 맞게 잘라 그립니다. 텍스처가 없어도 지도는 다 나오지만, 지역 사이가 더 흐릿하게 이어집니다.",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "목표까지의 경로를 그립니다: 걸어갈 곳, 날아갈 곳, 배를 탈 곳.",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "어떤 퀘스트를 잃게 되는지 대화창에 알리고 수락은 직접 하게 둡니다.",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "그늘숲은 카라잔과 너무 가까워서 어두워졌다고 해요. 그 뒤로 늘 어스름 속에 있어요.",
	["Dicen que en Thelsamar venden morcilla. ¡Es casi una salchicha! Solo digo."] = "텔사마에서 순대를 판대요. 거의 소시지잖아요! 그냥 그렇다고요.",
	["Diestro"] = "능숙",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "만 년 전, 일리단은 하이잘 꼭대기에 새 영원의 샘을 만들었고, 그 위에 놀드랏실을 심었어요.",
	["Dinero de toda la cuenta"] = "계정 전체 골드",
	["Dinero de tus personajes"] = "내 캐릭터들의 골드",
	["Disciplina"] = "수양",
	["Disciplina para subir"] = "레벨업용 수양",
	["Dispara desde lejos: alguien debe ir por él."] = "멀리서 활을 쏩니다. 누군가 가서 끌고 와야 합니다.",
	["Disparo apuntado: tu disparo más fuerte."] = "조준 사격: 가장 강한 사격.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "신비한 사격: 즉시 시전. 준비되면 쓰세요.",
	["Disponible a nivel %d"] = "%d레벨에 가능",
	["Distancia"] = "원거리",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "도시, 탑, 동굴이 세부 묘사를 유지하는 거리.",
	["Distancia a la que el suelo conserva su forma completa."] = "땅이 완전한 모양을 유지하는 거리.",
	["Distancia de las placas"] = "이름표 거리",
	["Distancia de visión"] = "시야 거리",
	["Distancia del pasto"] = "풀 거리",
	["Distancia y velocidad"] = "거리와 속도",
	["Doble clic derecho"] = "오른쪽 더블 클릭",
	["Doble clic derecho para lanzar"] = "오른쪽 더블 클릭으로 던지기",
	["Doble clic mientras pescas vuelve a lanzar"] = "낚시 중 더블 클릭하면 다시 던지기",
	["Dolanaar es la aldea élfica en el camino a Darnassus; su posada huele a bosque."] = "돌라나르는 다르나서스로 가는 길의 엘프 마을이에요. 여관에서 숲 냄새가 나요.",
	["Domingo de concurso"] = "대회 일요일",
	["Dominio de bestias"] = "야수",
	["Dominio de bestias para subir"] = "레벨업용 야수",
	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "영원의 샘이 있던 곳에서는 이제 대해 한가운데 끝없는 소용돌이, 혼돈의 소용돌이가 돌고 있어요.",
	["Donde lo sacas: %s."] = "낚는 곳: %s.",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "여러 지역에서 이어갈 수 있으면 묻지 않고 추천 지역을 고릅니다.",
	["Dormir"] = "잠자기",
	["Dos armas"] = "쌍수 무기",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "무기 두 개와 넘치는 분노. 장비가 좋으면 분노 전문이 무기 전문보다 세게 때리고, 피의 갈증은 40레벨에 얻습니다. 20레벨부터 한손 무기 두 개가 필요합니다.",
	["Dos clics y Alfa te lleva"] = "두 번 클릭하면 Alfa가 안내합니다",
	["Dos manos"] = "양손",
	["Dos monstruos a la vez dejan de ser un problema."] = "몬스터 두 마리를 동시에 상대해도 문제없습니다.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "채집 전문 기술 두 개: 시간을 낭비하지 않고 꾸준히 골드를 벌어, 가장 필요할 때 도움이 됩니다.",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "서리늑대 부족의 늙은 눈먼 주술사 드렉타르가 스랄에게 정령과 대화하는 법을 가르쳤어요. 늑대들의 현자죠!",
	["Drenar alma al rematar te da uno."] = "영혼 흡수로 마무리하면 하나 얻습니다.",
	["Druida"] = "드루이드",
	["Duelos"] = "결투",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "플레이어 한 명을 재우고 암흑 주문을 씁니다. 차단하세요.",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "둔 알가즈는 저습지와 모단 호수를 잇는 드워프 터널이에요.",
	["Duplicar"] = "복제",
	["Durabilidad"] = "내구도",
	["Duración"] = "표시 시간",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "전투 중에 돌 수호자를 깨웁니다. 누군가 맡거나 빨리 처치하세요.",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "수 세기 동안 파수병이 숲을 지키는 사이 드루이드들은 에메랄드의 꿈에서 잠들어 있었어요.",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "듀로탄과 서리늑대 부족은 만노로스의 피를 마시길 거부했어요. 굴단은 그걸 끝내 용서하지 않았어요.",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "듀로타는 스랄의 아버지이자 서리늑대 부족의 족장 듀로탄의 이름을 땄어요. 스랄은 오크의 땅에 그 이름을 붙여 아버지를 기렸어요.",
	["Dónde"] = "어디서",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "낚시를 배우는 곳과 숙련 단계. 낚시 가이드를 열면 채워집니다.",
	["Dónde empieza el paisaje lejano simplificado."] = "단순화된 원경이 시작되는 곳.",
	["Dónde entregar"] = "제출할 곳",
	["Dónde está"] = "위치",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "각각의 위치, 파는 것, 떨어뜨리는 것, 퀘스트.",
	["Dónde mandarlo"] = "보낼 곳",
	["Dónde sale"] = "얻는 곳",
	["Dónde se entrega"] = "제출할 곳",
	["Dónde se ven"] = "표시 위치",
	["Editar"] = "편집",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "데피아즈단의 우두머리 에드윈 밴클리프는 석공 장인이었어요. 귀족들이 스톰윈드 재건 대금을 주지 않자 복수를 맹세했어요.",
	["Efecto activo"] = "활성 효과",
	["Efecto del vacío"] = "황천 효과",
	["Efectos de pantalla del juego"] = "게임 화면 효과",
	["Ej.: Comprar bolsas de 10 casillas"] = "예: 10칸 가방 구매",
	["Ejecutar cuesta menos ira: rematas antes."] = "마무리 일격의 분노 소모가 줄어 더 빨리 끝냅니다.",
	["Ejecutar más barato para rematar jefes."] = "우두머리를 끝내기 위한 더 저렴한 마무리 일격.",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "은빛 여명회는 붉은십자군 같은 광신 없이 스컬지와 싸우고, 얼라이언스와 호드를 똑같이 받아들여요.",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "해안 앞 섬에 있는 페더문 요새는 엘프 파수병의 전초기지예요.",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "그늘숲과 붉은마루 산맥도 왕국의 땅인데, 병사가 모자라서 도움을 청하고 있어요.",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "모자케 야영지는 페랄라스에 있는 호드의 보금자리예요.",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "그림자송곳니 성채는 달라란의 마법사 아루갈의 것이었어요. 스컬지와 싸우려고 늑대인간을 불러냈다가 결국 미쳐 버렸어요.",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "달의 숲은 드루이드의 성소예요. 세나리온 의회가 그곳에 모여요.",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Codex가 출처를 모릅니다. 이미 가지고 있다면 탈것 도감에서 볼 수 있습니다.",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "크로스로드는 불모의 땅 한가운데, 큰길들이 만나는 곳에 있는 호드 전초기지예요. 그래서 이름이 그래요.",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "저주받은 자의 교단은 켈투자드가 세웠어요. 로데론 농민들에게 영원하고 더 공정한 삶을 약속했죠.",
	["El Discord de La Jauría"] = "La Jauría Discord",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "세나리온 요새는 실리더스에서 퀴라지와 맞선 세나리온 의회의 기지예요.",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "대땜장이 겔빈 멕카토크가 노움의 지도자예요.",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "세나리우스의 아들 수호자 레물로스가 성소에서 달의 숲을 지켜요.",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "가시덩굴 우리와 가시덩굴 구릉은 불모의 땅과 버섯구름 봉우리 사이에 있는 가시멧돼지 소굴이에요.",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "유산은 첫 점수를 얻으면(대부분 25레벨 달성 시) 열리며, Y 키나 메뉴 버튼으로 엽니다.",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "검은 연꽃은 아주 높은 레벨 지역에서만 자라고, 너무 귀해서 한 재산이에요.",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "검은 연꽃은 정말 귀해요. 여명의 설원, 불타는 평원, 동부 역병지대, 실리더스에서 자라요.",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "황혼의 망치는 실리더스에 야영지를 두고 정령의 군주들을 소환하려 해요.",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "검은바위 산 깊은 곳의 화산 심장부는 불의 군주 라그나로스의 집이에요.",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "죽음의 고개에는 마을이 하나도 없어요. 오우거와 짐승, 그리고 카라잔의 그림자뿐이에요.",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "죽음의 고개는 그늘숲과 슬픔의 늪을 이어요.",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "클래식에서 어둠의 문은 꺼져 있어요. 불타는 성전에서 아웃랜드로 다시 열려요.",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "어둠의 문은 메디브와 굴단이 각자 자기 쪽에서 함께 열었어요.",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "북쪽의 탄돌 교각은 카즈 모단과 아라시를 이어요. 검은무쇠 드워프가 반쯤 부숴 놨어요.",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "메네실 항구는 로데론 왕가의 성을 땄어요. 테라모어와 아우버다인으로 가는 배가 여기서 떠나요.",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "토막나무 주둔지는 잿빛 골짜기를 벌목하는 호드 야영지예요.",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "태양바위 은신처는 이 산맥에 있는 타우렌의 보금자리예요.",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "피난처 주둔지는 아라시 고원의 얼라이언스 야영지예요. 폐허와 트롤, 오우거 사이에 있어요.",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "마샬의 피난처는 분화구의 유일한 야영지라 모두가 함께 써요.",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "스톰윈드의 SI:7과 라벤홀트는 모든 도적이 아는 이름이에요.",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "공동묘지는 숲속의 포세이큰 전초기지예요. 거기서 늑대인간과 달라란 마법사들을 감시해요.",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "알터랙의 몰락한 귀족들인 비밀결사단도 이 일대의 길과 농장을 습격해요.",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "에메랄드의 꿈이 악몽으로 변하고 있어요. 무언가가 꿈을 지키는 녹색용들을 타락시키고 있어요.",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "깊은굴 지하철은 땅속으로 아이언포지와 스톰윈드를 이어요. 노움들이 만들었어요.",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "얼어붙은 왕좌는 얼음왕관 꼭대기에서 넬쥴이 갇힌 얼음 갑옷이에요.",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "산맥 남쪽의 잿더미 골짜기는 불타 버려 화염 정령으로 가득해요.",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "모건의 망루는 평원의 얼라이언스 전초기지예요. 거기서 검은바위 산을 감시해요.",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "체력이 가장 든든한 친구입니다: 생명력이 많을수록 생명력 전환을 더 쓸 수 있습니다.",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "제이나의 아버지 데일린 프라우드무어 제독은 호드를 공격하다 테라모어에서 쓰러졌어요. 딸은 평화를 택했어요.",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "대드루이드 판드랄 스태그헬름은 다르나서스의 세나리온 영토에서 가르쳐요.",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "대드루이드 판드랄 스태그헬름은 엘프들이 하이잘 산에서 잃은 불멸을 되찾으려는 희망으로 텔드랏실을 심었어요.",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "대드루이드 하물 룬토템은 타우렌 드루이드를 가르쳐요. 세나리온 의회에 들어간 첫 타우렌 중 하나였어요.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "주장비는 가장 느리고 강한 무기, 보조장비는 가장 빠른 무기로 하세요.",
	["El aro y la cabecera del minimapa con tu estilo."] = "미니맵 테두리와 상단을 내 스타일로.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "은행이 가득 찼습니다. 칸을 더 사거나 더 큰 가방을 은행에 넣으세요.",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "고블린 배가 무법항과 톱니항을 잇고, 양 진영 모두 탈 수 있어요.",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "남작 리븐데어가 스컬지의 죽음의 기사로서 스트라솔름을 다스려요.",
	["El blanco de la interfaz y del cielo de día."] = "인터페이스와 낮 하늘의 흰색.",
	["El bonus de tu arma al máximo."] = "무기 보너스 최대.",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "미니맵 테두리(둥글거나 사각형, 위의 «사각형 미니맵»)와 지역·시간 바가 지도 창처럼 고른 스타일을 따릅니다. 끄면 원래대로 돌아갑니다.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "내가 해제할 수 있는 약화 효과(마법, 저주, 질병, 독)가 있으면 테두리가 그 색으로 바뀝니다.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "경매장 창 아래의 «Alfa로 스캔» 버튼입니다.",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "모니터가 낼 수 있는 최고 밝기. 상자나 사양표에 나와 있습니다.",
	["El brillo suave de luces y cielo en toda la pantalla."] = "화면 전체에 퍼지는 빛과 하늘의 은은한 광채.",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "부두술사 잘라잔이 부두 마법으로 검은창 부족에게서 메아리 섬을 빼앗았어요.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "엔진의 찾아보기가 꺼져 있습니다(설정 > 발견). Alfa가 가이드를 만들 수 있게 켜세요.",
	["El buscador no está disponible."] = "검색을 쓸 수 없습니다.",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "언더시티로 가는 길은 아서스가 아버지를 죽인 로데론 수도의 폐허를 지나가요.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "세계 지도와 미니맵에 목표까지의 길을 표시합니다. 걷는 곳은 선 또는 점, 비행·항해·탑승은 선으로 그리고, 이후 구간은 흐리게 그립니다.",
	["El camino en el mapa y el minimapa"] = "지도와 미니맵의 경로",
	["El camino hasta el destino dibujado en el mapa."] = "목적지까지 가는 길을 지도에 그립니다.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "가장 간단한 레벨업 방법: 큰 무기, 출혈을 일으키는 공격, 40레벨에 죽음의 일격. 잘 버티고 빨리 처치합니다.",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "산맥에서 불모의 땅으로 내려가는 길엔 거미가 가득해요. 으으!",
	["El chat"] = "대화창",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "대화창은 Alfa 글꼴(설정 > 외형)을 씁니다. 크기는 여전히 탭 메뉴에서 바꿉니다.",
	["El clan"] = "클랜",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "서리늑대 부족은 진짜 늑대를 타요. 그래서 제가 제일 좋아하는 부족이에요. 부정 안 할게요.",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "서리늑대 부족은 알터랙 계곡에서 유배 생활을 해요. 옛 족장의 아들 스랄이 던홀드를 탈출한 뒤 그곳에서 그들을 찾았어요.",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "일반 오른쪽 클릭은 여전히 게임 지도를 축소합니다.",
	["El clic izquierdo solo selecciona"] = "왼쪽 클릭은 대상 지정만",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "PvP의 정석: 죽음의 일격이 상대의 치유를 줄이고, 향상된 무력화로 상대를 묶고, 향상된 돌진으로 시작 분노를 얻습니다.",
	["El color de mi clase"] = "내 직업 색",
	["El comerciante no lo compra"] = "상인이 사지 않음",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "내용이 가운데 한 열로 표시되고, 해상도나 UI 배율을 바꾸면 자동으로 맞춰집니다.",
	["El corcho quedó lejos · relanza con %s"] = "찌가 멀리 떨어졌어요 · %s로 다시 던지기",
	["El corcho quedó lejos · vuelve a lanzar"] = "찌가 멀리 떨어졌어요 · 다시 던지세요",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "마우스를 올리면 나오는 플레이어 툴팁입니다. 방해되지 않도록 전투 중에는 나오지 않습니다.",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "스팀휘들 무역회사가 무법항, 톱니항, 가젯잔, 눈망루 마을을 운영해요. 그래서 그 항구들은 모두를 받아 줘요.",
	["El daño por segundo de tu arma a distancia."] = "원거리 무기의 초당 공격력입니다.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "무기의 초당 공격력: 전사가 레벨을 올릴 때 가장 중요합니다.",
	["El de tu juego"] = "게임 언어",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "데빌사우루스는 분화구 최고의 포식자예요. 땅을 울리는 발소리가 들리면 숨으세요.",
	["El destino de la flecha y sus zonas en el minimapa."] = "화살표의 목적지와 그 지역을 미니맵에 표시합니다.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "화살표의 목적지, 가는 길, 이 단계의 다른 목표를 지도에 표시합니다.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "엔진의 던전 도감이 꺼져 있습니다(설정 > 발견 > 던전).",
	["El diario de mazmorras está apagado"] = "던전 도감이 꺼져 있음",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "푸른 용 아주어고스는 아즈샤라를 떠돌며 폐허에 남은 고대 마법을 지켜요.",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "드루이드는 뭐든 해요. 파티에 필요한 대로 방어, 치유, 공격을 맡을 수 있어요.",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "황제 다그란 타우릿산이 검은바위 나락의 검은무쇠 도시를 다스려요.",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "적이 회피했습니다. 제압은 회피할 수 없고 강하게 들어갑니다.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "적이 회피했습니다. 이 근접 공격을 쓸 수 있습니다.",
	["El enemigo esquivó: este golpe está listo."] = "적이 회피했습니다. 이 공격을 쓸 수 있습니다.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "적이 바로 앞에 있습니다. 근접 공격하세요.",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "적이 주문을 시전 중입니다. 대지 충격으로 끊으세요.",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "적이 주문을 시전 중입니다. 기절시키면 끊깁니다.",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "적이 주문을 시전 중입니다. 방패로 끊으세요.",
	["El enemigo está lanzando un hechizo: córtalo."] = "적이 주문을 시전 중입니다. 끊으세요.",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "적이 주문을 시전 중입니다. 강타로 끊으세요.",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "적이 곧 쓰러집니다. 영혼 흡수로 영혼의 조각을 얻으세요.",
	["El entrenador de oficio más cercano"] = "가장 가까운 전문 기술 전문가",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "정신력이 마나를 빠르게 회복시켜 쉬는 시간이 아주 짧습니다.",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "지도 스타일(미니맵 같은 지형 또는 클래식 그림)과 월드 옵션.",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "고른 스타일은 대화창, 미니맵, 아래쪽 바, 지도에도 입힐 수 있습니다. 언제든 끌 수 있고 모두 원래대로 돌아갑니다.",
	["El final"] = "결말",
	["El final de cada misión"] = "각 퀘스트의 결말",
	["El final lo verás al entregarla."] = "결말은 퀘스트를 제출할 때 볼 수 있어요.",
	["El fondo se ve deformado a través del agua."] = "물 너머 바닥이 일그러져 보입니다.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "불길이 주변 모두에게 피해를 줍니다. 근접 플레이어의 생명력을 높게 유지하세요.",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "사령관 드라키사스가 검은바위 첨탑 꼭대기에서 검은날개 둥지 입구를 지켜요.",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "붉은십자군의 대성전사 사이단 다스로한은 사실 악마 발나자르예요. 스트라솔름에서 만날 수 있어요.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "던전에서 가장 큰 피해를 주는 전사입니다. 앞에 방어 전담이 있으면 두 무기가 쉬지 않고, 향상된 마무리 일격으로 우두머리를 끝냅니다.",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "그롬 헬스크림의 도끼에는 이름이 있고, 공기를 가를 때 울부짖는대요. 울부짖는 건 진지한 일이에요!",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "검은무쇠는 검은바위 나락의 검은 용광로에서만 제련할 수 있어요.",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "케언의 아들 베인이 멀고어의 블러드후프 마을을 돌봐요.",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "언어, 스타일, Alfa가 대신 해 주는 일, La Jauría. 항목마다 «변경»이 있습니다. /alfa bienvenida로도 열 수 있습니다.",
	["El izquierdo selecciona y el derecho abre el menú."] = "왼쪽 클릭은 대상 지정, 오른쪽 클릭은 메뉴 열기입니다.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "왼쪽 클릭은 대상 지정, 오른쪽 클릭은 메뉴 열기입니다. 나머지는 직접 고르세요.",
	["El izquierdo selecciona y el derecho abre el menú; tu clase no tiene buffs para otros."] = "왼쪽 클릭은 대상 지정, 오른쪽 클릭은 메뉴 열기입니다. 내 직업에는 다른 사람에게 거는 강화 효과가 없습니다.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "게임이 상황에 따라 이 중에서 고르며, 지금 쓸 기술을 아이콘이 보여 줍니다.",
	["El juego la hizo brillar: es buen momento para usarla."] = "게임이 빛나게 표시했습니다. 쓰기 좋은 때입니다.",
	["El juego manda la imagen en HDR."] = "게임이 HDR로 화면을 출력합니다.",
	["El juego no aceptó el lote."] = "게임이 요리 묶음을 받아들이지 않았습니다.",
	["El juego no aceptó esa tecla."] = "게임이 그 키를 받아들이지 않았습니다.",
	["El juego no aceptó la prueba."] = "게임이 테스트를 받아들이지 않았습니다.",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "여기서는 게임이 위치를 알려 주지 않습니다(예: 인스턴스 안).",
	["El juego no deja cambiar talentos ahora mismo"] = "지금은 게임이 특성 변경을 허용하지 않습니다",
	["El juego no deja cocinar desde aquí."] = "여기서는 게임이 요리를 허용하지 않습니다.",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "지금은 게임이 메시지를 막습니다(우두머리 전투나 경기 중). 끝나면 흔적이 다시 자동으로 보내집니다.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "게임이 체험판 계정의 애드온 메시지와 사용자 채널을 막습니다. 파티는 그래도 보입니다.",
	["El juego no dejó cambiar las demás."] = "게임이 나머지를 바꾸지 못하게 했습니다.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "지금은 게임이 마커 공유를 막았습니다. 잠시 후 다시 시도하세요.",
	["El juego no dejó comprar ese rango."] = "게임이 그 단계를 찍지 못하게 했습니다.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "게임이 Alfa의 숨은 채널 입장을 막았고, 길드가 없으면 다른 공유 방법이 없습니다. Alfa가 몇 분 뒤 다시 시도합니다. 파티는 그래도 보입니다.",
	["El juego no dice si la tienes"] = "보유 여부를 게임이 알려 주지 않음",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "게임이 아직 점수를 알려 주지 않았습니다. 첫 점수를 얻으면 보입니다.",
	["El juego no la ofrece ahora mismo."] = "지금은 게임에서 제공하지 않습니다.",
	["El juego no lo dice ahora."] = "지금은 게임이 알려 주지 않습니다.",
	["El juego no permite usar el medidor ahora."] = "지금은 게임에서 측정기를 쓸 수 없습니다.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "게임에 Blizzard 전투 보조가 없어서 Alfa가 %s 전용 우선순위로 추천합니다. 내 캐릭터의 자원, 효과, 게임이 쓸 수 있게 해 주는 기술만 읽습니다. 적이 셋 이상이면 광역 기술로 바꿉니다. 무엇을 누를지는 내가 정합니다.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "전투 중에는 게임이 정확한 수치를 숨깁니다. 바와 숫자는 보이고, 자세한 내용은 전투가 끝나면 볼 수 있습니다.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "게임이 변경 확인을 거부했습니다. 특성 트리가 원래대로 남도록 되돌렸습니다.",
	["El juego solo deja cambiarla fuera de combate."] = "게임에서 전투 중이 아닐 때만 바꿀 수 있습니다.",
	["El juego todavía no carga tu árbol"] = "게임이 아직 내 트리를 불러오지 않음",
	["El juego todavía no carga tu árbol."] = "게임이 아직 내 트리를 불러오지 않았습니다.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "게임이 아직 특성을 불러오지 않았습니다. 몇 초 기다리거나 특성 창(N 키)을 한 번 여세요.",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "게임이 아직 도전 목록을 주지 않았습니다. Y 키로 여세요.",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "게임에 아직 일부 아이템 정보가 없습니다. 곧 나타납니다.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "게임이 아직 수치나 이름을 숨기고 있습니다(전투 중이나 던전 안에서 그렇습니다). 나온 뒤에 다시 시도하세요.",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "로다메어 호수가 은빛소나무 숲과 힐스브래드 구릉지, 알터랙 산맥을 갈라놓아요.",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "모단 호수는 거대한 드워프 댐 덕분에 있어요. 댐이 무너지면 물이 아래 땅을 휩쓸 거예요.",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "달의 숲 호수의 이름은 달의 여신을 기려 엘룬아라예요.",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "얼어붙은 켈테릴 호수에는 명가의 유적이 있어요.",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "비행 조련사, 여관, 수리, 은행 등을 화살표로.",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "비행 조련사, 여관, 수리, 은행 등: 가장 가까운 곳을 화살표와 경로로.",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "비행 조련사, 여관, 수리, 은행... 가장 가까운 곳 (/alfa cerca ayuda).",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "마법사 로닌과 용 코리알스트라즈가 그림 바톨에서 알렉스트라자를 구하는 걸 도왔고, 그곳에서 악마의 영혼이 파괴됐어요.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "가장 큰 피해를 주는 마법사: 화염 주문과 불태우는 치명타.",
	["El mapa a tu gusto"] = "내 취향대로 지도",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "M으로 지도를 열어도 오류가 없고, 아이콘 위에서 시작해도 부드럽게 끌립니다.",
	["El mapa de Alfa"] = "Alfa 지도",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "Alfa 지도는 비행 지점, 던전, 배, 비행선, 차원문과 함께 실제 지형을 보여 줍니다.",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Alfa 지도, 게임 지도, 미니맵. 방해되는 것이 있으면 여기서 끄세요. Alfa의 다른 모듈도 이 목록에 레이어를 추가합니다.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "확대할 수 있는 세계 전체 지도, 마커, 지도에 그리는 모든 것을 한곳에서 조절.",
	["El mapa no se abre en combate."] = "전투 중에는 지도가 열리지 않습니다.",
	["El mar paga"] = "바다가 보답한다",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "경험치 바와 평판 바의 테두리. 채우기 색은 그대로입니다.",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "오른쪽 아래의 게임 메뉴와 가방 테두리.",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "원수 듀간은 골드샤이어를 지키며 엘윈 숲의 문제를 도와줄 사람을 늘 찾아요.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "지도와 미니맵의 표시 아래 메달: Alfa 메달 또는 메달 없이 기호만.",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "피해량 측정기가 전투 중에도 버티고, 로테이션 도우미는 더 이상 끊을 수 없는 것을 끊으라고 하지 않습니다.",
	["El medidor no está disponible"] = "측정기를 사용할 수 없음",
	["El mejor que tengas"] = "가진 것 중 최고",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "놈리건의 배신자 멕기니어 텔마플러그는 아직 도시 안에 숨어 있어요. 거기의 마지막 우두머리예요.",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "게임 지도의 돋보기 메뉴에도 Alfa 레이어가 모두 있습니다.",
	["El mineral se funde en barras en cualquier forja."] = "광석은 어느 용광로에서든 주괴로 제련해요.",
	["El minimapa"] = "미니맵",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "미니맵이 원형에서 얇은 테두리의 사각형으로 바뀝니다. 미니맵 회전과 함께 쓰는 것은 권장하지 않습니다.",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "같은 수정이 경로와 치유 도우미에도 적용됐습니다.",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "미스릴은 황야의 땅, 동부 내륙지, 타나리스에 많아요.",
	["El modelo no lleva nada aquí."] = "이 부위에는 아무것도 입고 있지 않습니다.",
	["El modo pesca se abre al salir de combate."] = "전투가 끝나면 낚시 모드가 열립니다.",
	["El modo prueba se usa fuera de combate."] = "테스트 모드는 전투 중이 아닐 때 쓸 수 있습니다.",
	["El motor no aceptó la guía."] = "엔진이 가이드를 받아들이지 않았습니다.",
	["El motor no puede armar guías ahora."] = "지금은 엔진이 가이드를 만들 수 없습니다.",
	["El mundo entero en un mapa"] = "온 세상을 한 지도에",
	["El mundo pierde el color mientras eres espíritu."] = "유령 상태일 때 세상이 색을 잃습니다.",
	["El más cercano cuando le toque, por tiempo de camino."] = "차례가 되면 이동 시간 기준으로 가장 가까운 곳.",
	["El más cercano, por tiempo de camino"] = "이동 시간 기준 가장 가까운 곳",
	["El más cercano: %s"] = "가장 가까운 곳: %s",
	["El módulo Curación no está cargado."] = "치유 모듈이 불러와지지 않았습니다.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Alfa 지도 위에 각 지역 이름을 표시합니다.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "각 장비 왼쪽 아래에 표시되는 숫자입니다.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "숫자는 찍는 순서입니다. 특성에 마우스를 올리면 효과를 볼 수 있습니다.",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "거꾸로 세는 숫자. 끄면 바만 표시됩니다.",
	["El objeto"] = "아이템",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "현재 단계에서 사용하는 아이템이나 수집하는 퀘스트 아이템이 가방에서 빛납니다. 이후 단계에 필요한 아이템에는 자물쇠가 표시되어 팔지 않게 됩니다.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "숫자보다 순서가 중요합니다. 목록 앞쪽 능력치가 붙은 장비를 찾으세요.",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "먼 풍경이 짙은 안개 속에 사라지지 않습니다.",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "먼 풍경이 짙은 안개 속에 사라지지 않습니다. 가끔 불러온 영역이 끝나는 곳이 보입니다.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Alfa 데이터 팩(Alfa_Codex)이 꺼져 있습니다. 애드온 목록에서 켜고 다시 불러오세요.",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "어린 왕 안두인 린은 백성을 구한 영웅 안두인 로타를 기려 이름을 지었어요.",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "첫 클릭은 게임의 요리 창을 열고, 다음 클릭은 묶음을 요리합니다. 불 옆에 있어야 합니다.",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "호드의 첫 대족장은 검은손이었어요. 그 아들 렌드 블랙핸드는 지금 검은바위 첨탑에서 네파리안을 섬겨요.",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "첫 유산 점수는 보통 25레벨에 얻고, 그와 함께 유산이 열려요.",
	["El próximo: %s"] = "다음: %s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "레벨업이 가장 쉬운 도적: 정면에서 때리고, 회피를 많이 하고, 다른 도적보다 잘 버팁니다.",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "전문 단계는 가시덤불 골짜기 무법항의 낚시꾼이 파는 책으로 배웁니다.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "각 지역의 레벨 범위를 내 레벨에 따른 색으로 표시합니다.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "추적기가 다음 단계를 알려 주고 화살표가 안내합니다.",
	["El registro de daño del juego está apagado"] = "게임의 피해 기록이 꺼져 있음",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "게임의 피해 기록이 꺼져 있습니다. 켜면 파티 순위를 볼 수 있습니다.",
	["El registro del Legado"] = "유산 보상 트랙",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "인간 왕국 알터랙은 2차 대전쟁 때 얼라이언스를 배신했어요. 에이든 페레놀드 왕이 호드와 손잡았죠. 그래서 왕국이 사라졌어요.",
	["El reino limita los mensajes de addon salientes: %s"] = "서버가 애드온 메시지 전송을 제한합니다: %s",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "레인 린 왕은 1차 대전쟁 때 호드의 첩자 가로나의 손에 죽었어요.",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "마그니 브론즈비어드 왕이 아이언포지를 다스려요. 동생은 무라딘과 탐험가 브란이에요.",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "소라딘 왕이 아라소르에서 인간 부족들을 하나로 모았고, 하이 엘프가 마법을 가르쳐 함께 아마니 트롤을 물리쳤어요.",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "바리안 린 왕은 1차 대전쟁에서 죽은 레인 왕의 아들이에요.",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "바리안 왕이 평화 회담에 가던 길에 사라졌어요. 그동안 어린 아들 안두인이 왕위에 있고, 대영주 볼바르 폴드라곤이 섭정을 맡고 있어요.",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "주술사의 치유 전문: 연쇄 치유와 파티 전체를 돕는 토템.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "드루이드의 치유 전문: 어떤 파티든 치유하고 잘 살아남지만, 혼자서는 처치가 느립니다.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "성기사의 치유 전문: 강한 치유와 높은 방어도로 파티에 딱 맞습니다.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "순수한 치유 전문: 큰 치유와 파티 전체 치유.",
	["El servicio"] = "서비스",
	["El sistema de equipo de Alfa no está disponible."] = "Alfa 장비 기능을 사용할 수 없습니다.",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "여기 햇볕은 무자비해요. 황야의 땅은 코요테, 대머리수리, 바실리스크의 땅이에요.",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "땅과 벽이 멀리 있거나 비스듬해도 선명하게 보입니다.",
	["El talento que toca"] = "다음 특성",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "정석 방어 전담: 방패 막기가 많고, 복수와 방패 밀쳐내기로 위협 수준을 쌓으며, 모든 게 잘못될 때를 위한 최후의 저항이 있습니다.",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "가장 죽이기 어려운 방어 전담: 방어 특성 전부, 향상된 방패의 벽, 빠른 최후의 저항. 방어 전담을 시작하기에 딱 좋습니다.",
	["El terreno real en el mapa"] = "지도에 실제 지형 표시",
	["El texto es demasiado largo."] = "텍스트가 너무 깁니다.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "텍스트가 잘렸거나 바뀌었습니다. 다시 복사하세요.",
	["El tipo de nodos que une la ruta."] = "경로로 연결할 채집 지점의 종류입니다.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "배경 색조입니다. 흑연은 Alfa 기본, 밤은 가장 어둡고, 슬레이트는 중립적인 회색입니다.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "파티나 공격대의 DPS 순위를 작은 창에 현재 전투와 이전 전투로 보여 줍니다.",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "토륨은 운고로 분화구와 여명의 설원에 많아요.",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "일부 지역과 암흑 주문의 화면 장막.",
	["El vendedor más cercano"] = "가장 가까운 상인",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "스랄의 진짜 이름은 부모님이 지어 준 고엘이에요.",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "늙은 은둔자 애버크롬비는 친절해 보여요... 누구를 되살리려는지 알기 전까진요.",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "일꾼들의 «작작»은 «알았어» 같은 뜻이에요. 작작, 대장!",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Alfa 경로 트리, 새로 열리는 퀘스트, 아이템 목록.",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "큰 아이콘은 지금 누르면 좋은 기술, 작은 아이콘은 다음 기술입니다. 깜빡이면 게임이 그 기술을 활성화한 것이고, 어두운 덮개는 재사용 대기시간입니다. 결정은 직접 합니다. Alfa는 절대 대신 누르지 않습니다.",
	["El último punto: paras un poco más."] = "마지막 포인트: 무기 막기가 조금 늘어납니다.",
	["Elegida por ti en los ajustes."] = "설정에서 직접 고름.",
	["Elegida por tus talentos."] = "특성에 따라 고름.",
	["Elegido"] = "선택됨",
	["Elegido por ti"] = "직접 고름",
	["Elegir capas"] = "레이어 선택",
	["Elegir la siguiente guía"] = "다음 가이드 선택",
	["Elegir lo que pide tu paso"] = "단계가 요구하는 것 선택",
	["Elegir mi camino"] = "내 길 고르기",
	["Elegir mi primera guía"] = "첫 가이드 선택",
	["Elegir mi tecla"] = "내 키 고르기",
	["Elegir otra guía"] = "다른 가이드 선택",
	["Elegir para copiar"] = "복사할 부분 선택",
	["Elegir qué sigue"] = "다음 할 일 고르기",
	["Elegir todo"] = "모두 선택",
	["Elegir una guía"] = "가이드 선택",
	["Elegir una guía por ti"] = "가이드 대신 고르기",
	["Elegiste: %s"] = "선택: %s",
	["Elemental"] = "정기",
	["Elemental para subir"] = "레벨업용 정기",
	["Elfos de la noche"] = "나이트 엘프",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "아래에서 무엇을 얼마나 요리할지 고르세요. 대기열은 묶음마다 클릭을 기다립니다.",
	["Elige algo de la lista"] = "목록에서 하나를 고르세요",
	["Elige el objeto"] = "아이템 고르기",
	["Elige el objeto en la Enciclopedia."] = "백과사전에서 아이템을 고르세요.",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "가이드가 지정한 선택지를 고르거나 필요한 상점이나 수련 창을 엽니다.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "보관할 것을 고르세요. 이미 은행에 있는 것, 재료, 분류 하나, 또는 장비가 아닌 모든 것. 전투 중이 아닐 때 한 번에 옮깁니다.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "무엇을 할지 고르면 Alfa가 한 단계씩 안내합니다.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "지도에 표시할 것을 고르세요. 가이드, 퀘스트, 희귀, 이동, 지역, 다른 모듈이 추가한 것.",
	["Elige sola la única opción de los PNJ sin misiones."] = "퀘스트가 없는 NPC의 유일한 선택지를 자동으로 고릅니다.",
	["Elige solo misiones que ya puedes tomar."] = "지금 받을 수 있는 퀘스트만 고릅니다.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "길을 고르세요. 잘 모르겠으면 레벨업부터 시작하세요. Alfa가 무엇이 좋은지 알려 줍니다.",
	["Elige tu estilo"] = "스타일 고르기",
	["Elige tu tecla para pescar"] = "낚시 단축키 선택",
	["Elige tus clics"] = "클릭 고르기",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "클릭을 고르고, 프레임을 배치하고, 테스트하세요. 1분이면 됩니다.",
	["Elige tú la zona."] = "지역은 직접 고르세요.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "길을 고르세요. Alfa가 계획을 세우고 한 단계씩 안내합니다.",
	["Elige un marcador."] = "마커를 고르세요.",
	["Elige un servicio."] = "서비스를 고르세요.",
	["Elige una captura"] = "낚은 것 선택",
	["Elige una guía para empezar"] = "시작할 가이드를 고르세요",
	["Elige una mazmorra."] = "던전을 고르세요.",
	["Elige una misión"] = "퀘스트를 고르세요",
	["Elige una profesión"] = "전문 기술 선택",
	["Elige una profesión."] = "전문 기술을 고르세요.",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "하나를 고르면 이 창과 모든 Alfa 창, 화살표에서도 바로 볼 수 있습니다.",
	["Eliges una"] = "하나 선택",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "파티 전체를 재운 뒤 모그레인을 부활시킵니다. 정상이니 당황하지 마세요.",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "달의 여신 엘룬은 나이트 엘프의 신앙이에요. 사제는 엘룬의 자매들이고, 티란데가 대여사제예요.",
	["Embate con escudo: mucho daño y amenaza."] = "방패 밀쳐내기: 큰 피해와 위협 수준.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "격돌이 공격 주기를 초기화하지 않아, 공격 사이에 추가 공격이 들어갑니다.",
	["Embate sin perder tu ataque automático."] = "자동 공격 손실 없는 격돌.",
	["Embate sin perder tu ataque."] = "공격 손실 없는 격돌.",
	["Embate sin perder tu golpe automático."] = "자동 공격 손실 없는 격돌.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "공격 주기를 초기화하지 않는 격돌: 추가 공격 한 번.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "격돌: 자동 공격 사이에 넣는 강한 공격.",
	["Empezar"] = "시작",
	["Empezar de cero"] = "처음부터 시작",
	["Empezar de nuevo"] = "처음부터 다시",
	["Empezar otra"] = "새로 시작",
	["Empezar otra sesión"] = "새 세션 시작",
	["Empezó %s"] = "%s 시작",
	["Empezó %s."] = "%s 시작.",
	["Empieza al usar este objeto"] = "이 아이템을 사용하면 시작",
	["Empieza aquí"] = "여기서 시작",
	["Empieza con %s, que se consigue en la mazmorra."] = "시작 아이템: %s, 던전에서 얻습니다.",
	["Empieza con %s, que suelta %s."] = "시작 아이템: %s, 획득처: %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "멀리서 가장 느린 주문으로 시작하고 즉시 시전 주문으로 마무리하세요.",
	["Empieza dentro"] = "안에서 시작",
	["Empieza una misión"] = "퀘스트 시작",
	["Empiezas: nivel %d"] = "시작: %d레벨",
	["En %s"] = "위치: %s",
	["En 9 idiomas"] = "9개 언어",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "불타는 성전에서 카라잔이 공격대로 문을 열어요.",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "불타는 성전에서 청동용군단이 역사를 바꾸려는 용들에 맞서 시간의 동굴에서 도움을 청해요.",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "불타는 성전에서 시간의 동굴이 이 언덕으로 데려가 스랄이 던홀드를 탈출하는 걸 보여 줘요.",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "호숫가의 카엘 다로우에는 아직 옛 주민들의 유령이 떠돌아요.",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "아이언포지의 땜장이 마을에는 놈리건을 탈출한 노움들이 살아요.",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "어둠의 해안에서는 탐험가 연맹이 거대한 화석을 발굴해요.",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "어둠의 해안에는 달을 섬기는 반은 올빼미, 반은 곰인 달빛야수가 살아요.",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "잊혀진 땅에는 늙은 코도가 죽으러 가는 코도 무덤이 있어요.",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "듀로타에서 벌써 불타는 칼날을 만나요. 아직도 악마를 숭배하는 오크 흑마법사 교단이에요.",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "엘윈 숲에서 어떤 아주머니가 애완 고양이를 팔아요. 저는 고양이랑 잘 지내요... 거의 늘요!",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "언더시티에서는 애완 바퀴벌레를 팔아요. 취향은 저마다죠.",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "페랄라스에는 녹색용들이 에메랄드의 꿈으로 들어가는 거대한 나무 중 하나가 있어요.",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "Forever에서는 오닉시아, 하이잘 정상, Barrow Deeps를 쓰러뜨리면 유산 도전을 줘요.",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "Forever에서는 은행이 가방 칸을 하나씩 팔아요. 보물 둘 자리가 늘어요.",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "Forever에서는 명예 계급과 전장 평판도 유산 도전을 줘요.",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "Forever에서는 유산 도전이 계정 전체에 점수를 주고, 각 캐릭터가 자기 트리에 써요. Y 키로 여세요.",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "아이언포지 탐험가 연맹 홀에는 거대한 화석이 있는 박물관이 있어요. 브란 브론즈비어드가 가장 유명한 탐험가예요.",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "가젯잔의 요리사 더지는 클래식 최고의 요리법 중 하나를 가르쳐요. 키메로크 고기로 만들어요.",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "자에데나르에는 불타는 군단을 섬기는 흑마법사들, 어둠의 의회가 숨어 있어요.",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "귀족의 정원 축제 때는 시작 마을 곳곳에 알록달록한 달걀을 숨겨요. 안에는 사탕과 가끔 봄옷이 들어 있어요.",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "카라노스의 여관과 썬더브루 양조장은 몸을 녹이려면 꼭 들러야 하는 곳이에요... 안팎으로요.",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "앰버밀에는 달라란 마법사들이 피신해 있고, 포세이큰이 찾아오는 걸 전혀 좋아하지 않아요.",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "낙스라마스에서 위대한 알렉산드로스 모그레인이 스컬지의 4인의 기병대 중 하나로 다시 나타나요. 영웅에게 너무 슬픈 운명이에요.",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "황천의 요새에서는 혈마법사들이 이곳 짐승의 부위를 받고 한동안 강해지는 비약을 줘요.",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "오그리마의 지혜의 골짜기에는 스랄의 요새가 있고, 명예의 골짜기에는 전사와 사냥꾼이 모여요.",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "맹금의 봉우리는 그리핀 기수의 주인, 영주 팔스타드 와일드해머가 다스려요.",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "맹금의 봉우리에는 그리핀을 타고 나는 것으로 유명한 와일드해머 드워프가 살아요.",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "세라다인에는 에메랄드의 꿈으로 이어지는 거대한 나무 중 하나가 있고, 녹색용들이 지켜요.",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "타나리스에는 시간의 동굴이 있어요. 노즈도르무의 청동용군단이 그곳에서 역사를 지켜요.",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "티리스팔 숲에는 붉은십자군 수도원 입구가 있어요. 중간 레벨 모험가들이 가장 많이 찾는 곳 중 하나예요.",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "울다만에는 노르간논의 원반이 있어요. 티탄이 드워프의 돌 조상인 대지인을 어떻게 만들었는지 담긴 기록이에요.",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "잿빛 골짜기에서 호드가 숲을 베기 시작하자, 그롬 헬스크림이 반신 세나리우스를 죽였어요.",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "잿빛 골짜기에서 그롬은 다시 악마의 피를 마셨어요. 스랄이 그를 구했고, 그롬은 죽기 전에 속죄할 수 있었어요.",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "스톰윈드에는 드워프 구역, 마법사 구역, 나이트 엘프가 모이는 공원이 있어요.",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "워크래프트 III에서는 유닛을 여러 번 클릭하면 웃긴 말을 해요. 저는 대신 조언을 해 드리죠.",
	["En arco"] = "곡선",
	["En bancos de peces de: %s."] = "물고기 떼 위치: %s.",
	["En camino"] = "이동 중",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "0이면 숫자가 곧게 올라가고, 높일수록 옆으로 튀어 나갑니다.",
	["En combate"] = "전투 중",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "전투 중에는 게임이 정확한 수치를 숨깁니다. 바와 숫자는 그대로 보이고, 자세한 내용과 알리기는 전투가 끝난 뒤에 됩니다.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "전투 중에는 Alfa에서 게임 지도를 열 수 없습니다. Alfa 지도를 쓰세요.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "전투 중에는 월드의 캐릭터와 생물 툴팁이 나오지 않습니다(프레임의 툴팁은 나옵니다).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "전투 중에는 테스트할 수 없습니다. 전투를 끝내고 이 단계로 돌아오세요.",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "전투 중에는 검색할 수 없습니다. 전투가 끝나면 다시 해 보세요.",
	["En combate · la pesca espera"] = "전투 중 · 낚시는 잠시 대기",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "전투 중에는 Blizzard 전투 보조가 추천하는 기술과 그다음 %d개를 아이콘에 보여 줍니다. 무엇을 누를지는 내가 정합니다. Alfa는 절대 대신 누르지 않습니다.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "전투 중에는 Blizzard 전투 보조가 추천하는 기술을 아이콘에 보여 줍니다. 무엇을 누를지는 내가 정합니다. Alfa는 절대 대신 누르지 않습니다.",
	["En combate: espera a terminar"] = "전투 중: 끝날 때까지 기다리세요",
	["En curso"] = "진행 중",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "구 시가지에는 왕국을 위해 일하는 첩자와 도적인 SI:7이 있어요.",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "클래식에서는 스랄이 오그리마를, 케언이 썬더 블러프를, 실바나스가 언더시티를 다스리고, 볼진이 검은창 부족을 이끌어요.",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "클래식에서는 데스윙이 어디 있는지 아무도 몰라요. 모습을 드러내는 건 그 자식인 오닉시아와 네파리안이에요.",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "클래식에서는 화살이나 탄환이 필요해요. 화살통이나 탄환 주머니에 항상 넉넉히 챙기세요.",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "클래식에서는 가방에 무두질 칼이 있어야 해요.",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "클래식에서는 주 전문 기술을 두 개만 가질 수 있지만, 요리, 낚시, 응급치료는 따로 배워요.",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "클래식에서 사우스쇼어 대 타렌 밀농장은 세상에서 가장 유명한 진영 싸움이었어요.",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "클래식에서는 20레벨에 수도로 순간이동하는 법을, 40레벨에 다른 사람을 위한 차원문을 여는 법을 배워요.",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "클래식에서는 20레벨에 독 퀘스트를 하고, 그 뒤 상급자에게서 독을 강화해요.",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "클래식에서는 40레벨에 군마 퀘스트를, 60레벨에 군마의 에픽 연계 퀘스트를 해요.",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "클래식에서는 40레벨에 지옥마를 받고, 60레벨에 혈투의 전장 에픽 연계 퀘스트로 더 무시무시한 공포마를 얻어요.",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "클래식에서 안퀴라즈의 문을 열려면 서버 전체의 전쟁 준비가 필요했어요. 산더미 같은 재료와 아주 긴 연계 퀘스트요.",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "클래식에서는 어떤 물고기는 밤에만, 또는 낮에만 물어요.",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "클래식에서는 사제의 종족마다 고유 주문이 있어요. 상급자에게 내 주문이 뭔지 물어보세요.",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "클래식에서는 붕대를 감은 뒤 한동안 다른 붕대를 쓸 수 없어요.",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "클래식에서는 아주 긴 연계 퀘스트 끝에 흐르는 모래의 홀이 안퀴라즈의 문을 열었어요.",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "클래식에서 사냥꾼의 에픽 활은 달의 숲에서 시작하는 악마 상대 연계 퀘스트로 얻어요.",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "클래식에서 불모의 땅 대화창은 끝없는 수다로 유명했어요... 그리고 만크리크의 아내가 어디 있냐는 질문으로도요.",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "클래식에서는 최대 레벨이 60이고 거기까지 시간이 걸려요. 그래서 레벨마다 축하할 만해요.",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "클래식에서 명예 계급 14는 얼라이언스는 대원수, 호드는 대장군이에요.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "클래식에서는 다크문 축제가 가끔 멀고어의 블러드후프 마을 근처에 열려요.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "클래식에서는 다크문 축제가 가끔 골드샤이어 옆에 열려요.",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "클래식의 호드는 오크, 검은창 트롤, 타우렌, 포세이큰, 얼라이언스는 인간, 드워프, 노움, 나이트 엘프예요.",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "클래식에서는 낙스라마스가 열리기 전에 스컬지가 떠다니는 강령의 성채로 세상을 침공했어요.",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "클래식에서는 방어 태세를 10레벨 퀘스트로, 광폭 태세를 30레벨 퀘스트로 얻어요.",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "클래식에서는 아이언포지 경매장이 얼라이언스 전체에서 가장 붐벼요.",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "클래식에서는 곰 변신을 10레벨 퀘스트로, 바다표범 변신을 16레벨 퀘스트로 얻고, 그다음 표범 변신과 치타 변신이 와요.",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "클래식에서는 40레벨 탈것이 달리기보다 훨씬 빠르고, 60레벨 에픽 탈것은 더 빨라요.",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "클래식에서는 수도에서 천을 기부하고 평판을 받을 수 있어요.",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "클래식의 큰 공격대는 40인이고, 줄구룹과 안퀴라즈 폐허는 20인이에요.",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "클래식에서 포세이큰은 의지로 공포, 매혹, 수면을 떨쳐 내요.",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "클래식에서는 일요일 오후마다 무법항에서 낚시 대회를 열었어요. 특별한 물고기 40마리를 가장 먼저 제출한 사람이 우승했죠.",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "클래식에서는 드워프가 고유 기술로 보물을 찾을 수 있어요. 상자 찾기에 딱이에요!",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "클래식에서는 드워프가 돌로 변해 독과 출혈을 떨쳐 내고, 총을 잘 다뤄요.",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "클래식에서 노움은 전사, 도적, 마법사, 흑마법사가 될 수 있어요.",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "클래식에서 노움은 다른 종족보다 영리하고, 기계공학에 재능이 있으며, 묶는 효과에서 빠져나와요.",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "클래식에서 인간은 외교 덕분에 평판을 더 빨리 얻고, 은신한 적을 잘 알아봐요.",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "클래식에서는 수도의 무기 전문가가 새 무기 쓰는 법을 가르쳐 줘요.",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "클래식에서 오크는 기절에 더 잘 버티고, 소환수가 더 세게 때려요.",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "클래식에서 타우렌은 생명력이 더 많고, 주변 적을 기절시키는 발구르기가 있고, 약초를 잘 다뤄요.",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "클래식에서 트롤은 빨리 회복하고, 광폭해지고, 야수를 더 세게 때리고, 활과 투척 무기를 잘 다뤄요.",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "클래식에서는 많은 음식이 포만감 효과를 주고 한동안 능력치를 올려 줘요.",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "클래식에서는 225를 넘으려면 테라모어나 해머폴에서 부상자 분류 퀘스트를 해야 해요.",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "클래식에서 홀 연계 퀘스트를 끝내고 안퀴라즈의 징을 울린 사람은 특별한 칭호와 탈것을 얻었어요.",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "클래식에서는 나이트 엘프와 타우렌만 드루이드가 될 수 있어요.",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "클래식에서는 인간과 드워프만 성기사가 될 수 있어요.",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "클래식에서는 오크, 트롤, 타우렌만 주술사가 될 수 있어요.",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "클래식에서 윤회는 스스로 부활하게 해 주지만, 가방에 앵크가 있어야 해요.",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "세나리온 영토에서는 드루이드들이 동족에게 자연의 길을 가르쳐요.",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "달의 축제 때면 사람들이 조상을 기리러 달의 숲을 찾아와요.",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "달의 축제 때는 수도의 사절이 달의 숲으로 데려가 드루이드와 함께 축하하게 해 줘요.",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "한여름 불꽃축제 때는 많은 마을에 모닥불이 피어요. 내 진영의 불을 기리면 보상을 받고, 상대 진영의 불을 꺼도 받아요.",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "겨울맞이 축제 때는 눈덩이를 팔아요. 친구에게 던지세요, 제가 받을게요!",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "겨울맞이 축제 때 겨울 할아버지가 아이언포지와 오그리마에서 선물을 나눠 주고, 25일에는 나무 아래 꾸러미가 생겨요.",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "추수감사절에는 호드가 그롬 헬스크림을, 얼라이언스가 우서를 기념비에서 기려요.",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "화산 심장부에서는 심장부 사냥개를 무두질해 아주 특별한 가죽을 얻어요.",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "에메랄드 성역에서는 드루이드들이 병든 숲을 치유하려고 애써요.",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "알터랙 계곡에서는 드워프의 스톰파이크 경비대와 서리늑대 부족이 싸워요. 저는 누구 편인지 이미 알죠.",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "힘의 골짜기에는 은행과 경매장이 있어요. 호드 거래의 중심이에요.",
	["En el camino"] = "가는 길",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "그 시절 칼림도어 한가운데에는 순수한 마력의 호수, 영원의 샘이 있었어요. 호숫가에 살던 트롤들이 수 세기 동안 변해 나이트 엘프가 되었어요.",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "협곡 한가운데에는 거대한 용암 구덩이, 가마솥이 있고, 검은무쇠의 노예들이 그곳에서 일해요.",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "분화구 한가운데에는 화염 정령이 사는 화산이 연기를 내뿜어요.",
	["En el chat"] = "대화창에",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "달의 신전 한가운데에는 달샘이 있고, 여사제들이 그곳에서 엘룬에게 기도해요.",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "분화구에서는 링켄이라는 자가 기억을 잃고 검과 방패를 찾고 있어요. 뾰족 귀의 어느 영웅을 떠올리게 하죠.",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "황야의 땅 동쪽에는 검은용과 그 하수인들이 살아요. 혼자라면 멀찍이 지나가세요.",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "호수 동쪽에는 텔사마 드워프들을 괴롭히는 오우거가 살아요.",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "동쪽의 거대한 소금 평원에서는 고블린과 노움이 경주를 벌여요. 경쟁이 아주 치열해요.",
	["En el juego"] = "게임 내",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "레이크샤이어 호수에는 멀록이 있어요. 아제로스의 거의 모든 호수처럼요!",
	["En el mapa"] = "지도에",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "Alfa 지도에서 클릭: 화살표로 따라가거나 마커로 저장.",
	["En el mapa del mundo"] = "세계 지도에",
	["En el marco del objetivo"] = "대상 프레임에",
	["En el minimapa"] = "미니맵에",
	["En el mundo"] = "필드에서",
	["En el nivel 10 domas tu bestia."] = "10레벨에 야수를 길들입니다.",
	["En el nivel 20 aprendes venenos."] = "20레벨에 독을 배웁니다.",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "이 땅 북쪽에서는 붉은십자군이 성벽 둘린 마을을 차지하고 광신적으로 지켜요.",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "버섯구름 봉우리 서쪽에는 야생 와이번이 둥지를 틀어요.",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "달의 숲 드루이드 마을에서는 얼라이언스와 호드가 함께 지내요. 세나리온 의회는 모두를 맞이해요.",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "잊혀진 땅 남쪽에서는 악마와 사티로스가 집회를 열어요.",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "타나리스 남쪽에는 실리시드 벌집이 있어요. 실리더스에 있는 것들의 친척이에요.",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "남동쪽의 티르의 손은 붉은십자군에게 남은 가장 강한 도시예요.",
	["En espera"] = "대기 중",
	["En esta zona"] = "이 지역",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "이 언덕에는 던홀드가 있어요. 아에델라스 블랙무어가 스랄을 검투사로 키운 곳이에요.",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "2차 대전쟁 때 아제로스의 사자 안두인 로타가 이 땅에서 쓰러졌어요.",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "이 땅에는 최초의 위대한 인간 왕국 아라소르의 수도 스트롬이 있었어요.",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "아탈학카르 신전은 이 늪에 가라앉았어요. 학카르의 사제들을 막으려고 녹색용들이 가라앉혔어요.",
	["En grupo"] = "파티",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "파티에서는 거의 항상 적이 여럿이라 두 마리를 동시에 때립니다.",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "파티에서 방어 전담일 때: 정의의 격노로 위협 수준을 더 얻습니다.",
	["En grupo, cura al tanque antes que a nadie."] = "파티에서는 누구보다 먼저 방어 전담을 치유하세요.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "파티에서는 방어 전담을 먼저 치유하고, 직접 몬스터를 끌지 마세요.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "파티에서는 생명력이 많이 떨어지기 전에 치유하세요. 그게 더 저렴합니다.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "파티에서는 마나 토템과 치유 토템을 파티 가까이에 세우세요.",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "구루바시 투기장에는 가끔 모두가 차지하려고 싸우는 상자가 나타나요. 각자 알아서 살아남으세요!",
	["En la Enciclopedia"] = "백과사전에서",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "축제에서는 교환권을 상품으로 바꿔요. 교환권은 전문 기술로 만든 것이나 사냥하며 모은 것을 내면 받아요.",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "다크문 축제의 점술가 세이지는 몇 가지 질문을 하고, 한동안 능력치를 올려 주는 운세를 줘요.",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "그롬마쉬 요새에서 스랄은 찾아오는 누구든 맞이해요. 바로 근처에 티리온의 친구인 늙은 오크 에이트리그가 있어요.",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "흐르는 모래의 전쟁 때 대드루이드 판드랄은 아들 발스탄을 퀴라지에게 잃었어요.",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "2차 대전쟁 때 호드에는 아마니 트롤, 오우거, 노예가 된 붉은용들이 합류했어요.",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "어린이 주간에는 스톰윈드와 오그리마의 고아들이 산책을 부탁해요. 끝나면 애완동물을 줘요.",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "3차 대전쟁 때 오크, 인간, 엘프가 이곳에서 힘을 합쳐 아키몬드에 맞섰고, 놀드랏실이 자신의 힘을 희생해 그를 쓰러뜨렸어요.",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "다르나서스의 장인의 정원에 전문 기술 전문가들이 있어요.",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "가시덤불 골짜기에는 네싱워리 책의 낱장이 흩어져 있어요. 한 장(章)을 다 모아 그에게 가져가세요.",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "하이잘 전투에서 말퓨리온이 세나리우스의 뿔을 불자, 수천의 위습이 아키몬드를 둘러싸 그를 파괴했어요.",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "경매장에서는 팔기 전에 며칠 동안 가격을 지켜보세요. 시간대와 접속한 사람에 따라 바뀌어요.",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "하이잘 산 꼭대기에는 용들이 축복한 세계수 놀드랏실이 자라요.",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "듀로타 해안에서는 쿨 티라스 병사들이 티라가드 요새를 차지하고 있어요. 호드 땅에 박힌 가시예요.",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "타나리스 해안에는 남쪽바다 해적이 숨어 있어요.",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "늪 해안에는 나가가 있고, 기웃거리는 사람을 반기지 않아요.",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "동쪽 해안에는 호드와 친하고 진타알로 트롤과는 적인 트롤 부족이 살아요.",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "잿빛 골짜기 서쪽 해안의 검은심연의 나락은 원래 엘룬의 신전이었어요. 지금은 물에 잠겨 나가로 가득해요.",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "해안을 따라 반쯤 바다에 잠긴 고대 엘프 궁전의 폐허가 보여요.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "배가 있는 동굴에 해적이 많습니다. 모두 한꺼번에 부두로 내려가지 마세요.",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "아이언밴드 발굴현장에서는 트로그가 땅에서 나와 모든 걸 차지했어요.",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "살딘 농장의 늙은 암말 블랜치는 귀리가 필요해요. 서부 몰락지대에서 가장 다정한 퀘스트 중 하나예요.",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "오닉시아의 둥지 양옆에는 알이 가득한 둥지가 있어요. 누가 밟으면 새끼용이 나와요... 엄청 많이요.",
	["En la pelea, el juego te avisa"] = "전투 중에는 게임이 경고합니다",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "아이언포지 탐험가 연맹 홀에는 도서관, 지도, 거대한 화석이 있는 박물관이 있어요.",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "두 번째 단계에서는 이 적부터 처치하세요. 치유를 많이 합니다.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "경매장은 본 최저가에서 수수료(%d%%, 추정)를 뺀 값으로 계산합니다. 마력 추출은 클래식 게임의 표를 쓰며, 이것도 추정치입니다.",
	["En la subasta, unos %s."] = "경매장에서 약 %s.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "창과 여기에 표시됩니다. 순위에 없으면 내 줄이 맨 아래에 나옵니다.",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "통곡의 동굴에서 드루이드 나라렉스는 불모의 땅을 다시 푸르게 하는 꿈을 꾸었지만, 그 꿈은 악몽이 되었어요.",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "트롤 전쟁 때 하이 엘프가 아마니를 함께 물리치려고 인간 백 명에게 마법을 가르쳤어요. 그들이 인류 최초의 마법사였어요.",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "스톰윈드 지하감옥에서 죄수들이 폭동을 일으켜, 경비대가 수습을 도와 달라고 해요.",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "고원 하나 아래의 예언의 웅덩이에서는 포세이큰 마법사와 사제가 수련해요.",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "여명의 설원 동굴에는 털북숭이 심술쟁이 예티가 살아요.",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "페랄라스 동굴에는 예티가 살고, 고르둔니 오우거는 북쪽에 야영지를 두고 있어요.",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "던 모로의 눈 덮인 동굴에는 드워프를 눈곱만큼도 좋아하지 않는 얼음 트롤이 살아요.",
	["En las dos armas"] = "두 무기 모두",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "서쪽 농장에서는 스컬지의 가마솥이 계속 역병을 퍼뜨려요. 얼라이언스는 모험가를 보내 부수게 해요.",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "알터랙 도시의 폐허는 이제 오우거와, 옛 왕국의 몰락한 귀족 무리인 비밀결사단이 차지하고 있어요.",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "산맥 높은 곳에는 엘프 드루이드에게 신성한 봉우리가 있고, 거대한 새들이 둥지를 틀어요.",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "검은바위 산 꼭대기에서는 데스윙의 아들 네파리안이 다스려요.",
	["En los mapas"] = "지도에서",
	["En lugar de las del juego"] = "게임 가방 대신",
	["En marcha"] = "진행 중",
	["En marcha hacia %s"] = "이동 중: %s",
	["En mazmorra"] = "던전 안",
	["En mazmorras y bandas"] = "던전과 공격대에서",
	["En memoria"] = "추모",
	["En memoria de una gran perrita"] = "멋진 강아지를 기리며",
	["En mi zona"] = "내 지역",
	["En movimiento"] = "움직임",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "오크어로 «Lok'tar ogar»는 «승리 아니면 죽음»이라는 뜻이에요.",
	["En otra zona: %s"] = "다른 지역: %s",
	["En pantalla"] = "화면에",
	["En pausa"] = "일시 정지",
	["En pausa dentro de la instancia"] = "인스턴스 안이라 일시 중지",
	["En pausa por ahora"] = "잠시 일시 중지",
	["En pausa: hay otro addon de pesca activo"] = "일시 정지: 다른 낚시 애드온이 켜져 있음",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "2차 대전쟁이 한창일 때 굴단은 호드를 버리고 살게라스의 무덤을 찾아갔어요. 거기서 만난 악마들에게 갈가리 찢겼어요.",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "여관과 마을에서는 휴식 경험치가 쌓여, 다 쓸 때까지 적 처치 경험치를 두 배로 얻습니다. 여기서 접속을 종료해도 쌓입니다.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "여관과 도시에서는 휴식 경험치가 쌓입니다. 다 쓸 때까지 적마다 경험치를 두 배로 얻습니다.",
	["En qué orden aparecen."] = "표시되는 순서입니다.",
	["En qué se gastan"] = "사용처",
	["En silencio"] = "조용히",
	["En solitario es lento: usa la varita para rematar."] = "혼자서는 느립니다. 마무리는 마법봉으로 하세요.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "혼자일 때는 지속 치유를 걸어 두고 천벌로 싸우세요.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "혼자일 때는 충격 주문으로 싸우고 몬스터 사이사이에 자신을 치유하세요.",
	["En su ficha toca «Agregar a mi ruta»."] = "정보 화면에서 «내 경로에 추가»를 누르세요.",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "초창기에는 알터랙 계곡 전투가 몇 시간... 심지어 며칠씩 이어지기도 했어요!",
	["En tu arma"] = "무기에 있음",
	["En tu marco"] = "내 프레임에",
	["En tu plan"] = "계획에 있음",
	["En tu registro"] = "퀘스트 목록에 있음",
	["En tus bolsas"] = "가방에 있음",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "가방, 전리품, 대화창, 모든 링크에서 Alt+클릭하면 얻는 가이드를 열고, 가이드가 없으면 백과사전 정보를 엽니다.",
	["En tus bolsas: úsala para aprenderla"] = "가방에 있음: 사용해서 배우세요",
	["En un aviso"] = "알림으로",
	["En un aviso y en el chat"] = "알림과 대화창에",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "잿빛 골짜기의 협곡에서 그롬은 악마 군주 만노로스를 죽이고 오크들을 그 저주받은 피에서 해방했어요.",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "악령의 숲 한 골짜기에는 하늘에서 지옥불정령이 떨어졌고, 그 구덩이가 아직도 보여요.",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "경유지가 있는 비행에서 타이머 아래에 다음 경유지와 도착까지 남은 시간을 한 줄로 보여 줍니다. 비행 타이머가 켜져 있어야 합니다.",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "숲 남쪽 마을 주민들은 낮엔 평범해 보이지만... 밤엔 늑대인간으로 변해요.",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "고원 하나에서는 타우렌이 조상의 영혼을 기려요.",
	["En una instancia: la flecha vuelve al salir"] = "인스턴스 안: 나가면 화살표가 돌아옵니다",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "아즈샤라 앞바다 섬에는 물의 군주 공작 히드락시스가 살아요. 그 부하들이 화산 심장부의 룬을 끄도록 도와줘요.",
	["En una pestaña nueva"] = "새 탭에서",
	["En unos segundos aparece tu build."] = "몇 초 뒤에 내 빌드가 나타납니다.",
	["En uso"] = "사용 중",
	["En uso, a tu gusto"] = "사용 중, 내 설정",
	["En vivo"] = "실시간",
	["En vivo si estás con un banquero; si no, la última foto."] = "은행원 앞에 있으면 실시간, 아니면 마지막 기록.",
	["En vuelo: la flecha sigue al bajar"] = "비행 중: 내리면 화살표가 이어집니다",
	["En vuelo: la flecha sigue al bajar."] = "비행 중: 내리면 화살표가 이어서 안내합니다.",
	["Enanos"] = "드워프",
	["Encanta tu arma antes de pelear."] = "전투 전에 무기에 마법을 부여하세요.",
	["Encantada"] = "마법부여됨",
	["Encantamiento"] = "마법부여",
	["Encantar a otros es un servicio: anúnciate en el chat de comercio de la ciudad."] = "남에게 마법부여를 해 주는 건 서비스예요. 도시의 거래 채널에 알리세요.",
	["Encender el registro"] = "기록 켜기",
	["Encender la pesca"] = "낚시 켜기",
	["Encender las recomendadas"] = "추천 기능 켜기",
	["Encender una fogata"] = "모닥불 피우기",
	["Encenderla"] = "켜기",
	["Encenderlos"] = "켜기",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "켜짐: 필터가 빼도 계획에 넣습니다. 꺼짐: 빠집니다.",
	["Encendido"] = "켜짐",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "켜짐: 낚시 중 더블 클릭하면 다시 던지고, Shift, Ctrl, Alt와 함께 하면 낚아 올립니다. 꺼짐: 그 반대입니다.",
	["Enciclopedia"] = "백과사전",
	["Enciende las comodidades recomendadas"] = "추천 편의 기능을 켜세요",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "캐릭터나 생물에 마우스를 올렸을 때 나오는 툴팁에 아래 변경 사항을 적용합니다.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "미리보기 창(아이템을 Ctrl+클릭)에 아래 변경 사항을 적용합니다.",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "아래 변경 사항을 적용합니다. 각각 따로 끌 수 있습니다. 일부 애드온은 /reload 후에 버튼을 사각형에 맞춰 옮깁니다.",
	["Enciende primero la guía en el minimapa."] = "먼저 미니맵 가이드를 켜세요.",
	["Enciende primero los servicios."] = "먼저 시설을 켜세요.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "켜면 전투 중에 지금 쓸 기술과 다음 기술을 옮길 수 있는 작은 아이콘으로 보여 줍니다.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "아래 '프레임'에서 켜면 파티의 생명력을 보고 클릭 한 번으로 치유할 수 있습니다.",
	["Enciéndelos en la página Curación."] = "치유 페이지에서 켜세요.",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "켜면 파티 생명력을 보고 클릭 한 번으로 치유할 수 있습니다.",
	["Enemigo raro"] = "희귀 적",
	["Enemigos menores"] = "약한 적",
	["Enfoque interno: tu siguiente hechizo es gratis y más crítico."] = "내면의 집중: 다음 주문이 비용 없이 나가고 치명타 확률이 오릅니다.",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "몬스터를 뿌리로 묶고 시전 시간이 긴 주문을 쓰기 전에 거리를 벌리세요.",
	["Entendido"] = "알겠습니다",
	["Entereza"] = "인내",
	["Entorno"] = "환경",
	["Entra al juego con él una vez."] = "그 캐릭터로 한 번 접속하세요.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "퀘스트 목록을 비우고 들어가세요. 가진 퀘스트를 먼저 제출하세요.",
	["Entrada"] = "입구",
	["Entrada enemiga"] = "적 진영 입구",
	["Entradas de mazmorras"] = "던전 입구",
	["Entradas en el minimapa"] = "미니맵에 입구 표시",
	["Entradas y salidas"] = "입구와 출구",
	["Entraste a %s"] = "%s 입장",
	["Entraste a %s."] = "%s에 입장했습니다.",
	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "언더시티는 로데론 옛 수도 아래의 납골당과 지하 묘지예요.",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "언더시티에는 마법사, 도적, 전사, 약제사 구역이 있고, 가운데 고리에 은행과 경매장이 있어요.",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "언더시티와 그롬골 사이에도 비행선이 있어요. 대륙을 가로지르지 않고 남쪽으로 갈 수 있죠.",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "드루이드 중에는 곰이 되는 발톱의 드루이드와, 까마귀 모습이 되는 갈퀴발톱의 드루이드가 있어요.",
	["Entrega tus %d misiones listas"] = "완료한 퀘스트 %d개 제출",
	["Entregada"] = "제출함",
	["Entregar"] = "제출",
	["Entregar %s"] = "제출: %s",
	["Entregar las completadas"] = "완료한 퀘스트 제출",
	["Entregar las misiones de tu guía"] = "가이드 퀘스트 제출",
	["Entregar mis misiones"] = "내 퀘스트 제출",
	["Entregar misiones"] = "퀘스트 제출",
	["Entregar solas las misiones de la guía"] = "가이드 퀘스트 자동 제출",
	["Entregar todas"] = "모두 제출",
	["Entregarla"] = "제출하기",
	["Entregarlas ahora"] = "지금 제출",
	["Entrenador"] = "상급자",
	["Entrenador al día"] = "상급자에게 배울 것 없음",
	["Entrenador de %s"] = "전문가: %s",
	["Entrenador de tu clase"] = "내 직업 상급자",
	["Entrenador: %s, en %s."] = "상급자: %s(%s).",
	["Entrenador: %s."] = "상급자: %s.",
	["Entrenadores de profesión"] = "전문 기술 전문가",
	["Entrenar"] = "수련",
	["Entrenar la rápida"] = "빠른 타기 수련",
	["Entrégala a %s."] = "%s에게 제출하세요.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "독을 걸고 번개를 씁니다. 가능하면 독을 해제하세요.",
	["Equilibrada"] = "균형",
	["Equilibrado"] = "균형",
	["Equilibrado: se ve bien y corre bien en casi cualquier equipo."] = "균형: 거의 모든 PC에서 보기 좋고 잘 돌아갑니다.",
	["Equilibrio"] = "조화",
	["Equilibrio para subir"] = "레벨업용 조화",
	["Equipa tu caña de pescar"] = "낚싯대를 장착하세요",
	["Equipo"] = "장비",
	["Equipo %d %%"] = "장비 %d %%",
	["Equipo a punto de romperse."] = "장비가 곧 망가집니다.",
	["Equipo de pesca"] = "낚시 장비",
	["Equipo y cebos"] = "장비와 미끼",
	["Equipo y estadísticas"] = "장비와 능력치",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "장비, 소비용품, 퀘스트, 재료... 접을 수 있는 제목 아래에 나눕니다.",
	["Equitación"] = "타기",
	["Equitación de aprendiz (nivel 40)"] = "수습 타기 (40레벨)",
	["Equitación de oficial (la rápida, nivel 60)"] = "숙련 타기 (빠른 탈것, 60레벨)",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "이세라의 배우자 에라니쿠스는 악몽에 갇혔어요. 그의 그림자가 아탈학카르 신전을 떠돌아요.",
	["Eres de la manada"] = "무리의 일원입니다",
	["Eres nivel %d"] = "현재 레벨: %d",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "내 레벨은 %d이고 권장 레벨은 %d입니다. 그 레벨부터 이렇게 계산합니다.",
	["Eres nivel %d."] = "현재 레벨: %d.",
	["Error"] = "오류",
	["Errores de Lua de Alfa en esta sesión:"] = "이번 세션의 Alfa Lua 오류:",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "이번 세션의 Alfa Lua 오류: 없음",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "짧고 스톰윈드 안에 있습니다. 양옆 감방에 죄수들이 있으니 천천히 나아가세요.",
	["Es de la otra facción"] = "다른 진영 것입니다",
	["Es de una misión."] = "퀘스트 아이템입니다.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "얼라이언스 퀘스트에서 요구하는 우두머리입니다. 들어가기 전에 퀘스트를 확인하세요.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "첫 우두머리이며 쉽습니다. 죽으면 내 진영의 포로가 안뜰 문을 열어 줍니다.",
	["Es el primer reto: con él se abre el Legado."] = "첫 번째 도전입니다. 이것으로 유산이 열립니다.",
	["Es el punto %d de %d de tu build."] = "내 빌드의 %d/%d번째 포인트입니다.",
	["Es el que toca ahora."] = "지금 찍을 차례입니다.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "묘지의 마지막 우두머리입니다. 주변에 불길을 뿜습니다. 원거리라면 멀리 있으세요.",
	["Es el único lobo a la vista."] = "보이는 늑대는 이 사람뿐입니다.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "크고 길을 잃기 쉽습니다. 한 사람만 따라가고 혼자 뛰어가지 마세요.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "스니드의 기계입니다. 부수면 스니드가 나와서 싸웁니다.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "호드의 첫 던전입니다. 짧아서 파티 플레이를 배우기 좋습니다.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "얼라이언스의 첫 대형 던전입니다. 천천히 나아가며 한 번에 한 무리씩 끌어오세요.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "길고 입구가 두 개입니다. 많은 적이 돌로 되어 있고 세게 때립니다.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "길고 로봇이 많습니다. 일부는 폭탄을 놓거나 경보를 울려 적을 더 부릅니다.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "느립니다. 원거리라면 다가오는 동안 공격하세요.",
	["Es muy veloz: frénalo si tu clase puede."] = "매우 빠릅니다. 직업에 감속 기술이 있으면 쓰세요.",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "선택 사항입니다. 동의하면 Alfa를 쓰는 La Jauría의 늑대들이 파티원을 보듯 WoW 지도에서 내 캐릭터를 보고 화살표를 따라 내게 올 수 있으며, 나도 그들에게 갈 수 있습니다. Alfa는 게임 안에서 캐릭터가 있는 곳만 공유합니다: 지역, 지도 위 지점, 레벨, 직업. 실제 위치, 컴퓨터, 계정은 절대 공유하지 않습니다.",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "선택 사항입니다. Alfa를 쓰는 La Jauría 늑대들의 WoW 지도에 내 캐릭터가 나타나고, 내 지도에도 그들이 나타나 서로 찾고 화살표로 찾아갈 수 있습니다. 게임 안에서 캐릭터가 있는 곳(지역, 지도 위 지점, 레벨, 직업)만 공유하며, 실제 위치나 컴퓨터의 정보는 절대 공유하지 않고, 던전 안에서도 공유하지 않습니다. 파티는 항상 보입니다. La Jauría에서 언제든 바꿀 수 있습니다.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "%s레벨용이고 지금 %d레벨입니다. %d레벨 남았습니다.",
	["Es para otra raza."] = "다른 종족용입니다.",
	["Es raro del Cementerio y no siempre aparece."] = "묘지의 희귀 몹이며 항상 나오지는 않습니다.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "묘지의 희귀 몹이며 항상 나오지는 않습니다. 독을 겁니다. 해제하세요.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "묘지의 희귀 몹이며 항상 나오지는 않습니다. 주문 시전자를 침묵시킬 수 있습니다.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "희귀 몹이며 드물게 나타납니다. 주변에 불을 씁니다.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "숨겨진 동굴에 있는 희귀 몹입니다. 빠르게 때리는 박쥐입니다.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "희귀 몹이며 항상 나오지는 않습니다. 레벨에 비해 아주 세게 때리니 조심해서 끌어오세요.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "희귀 몹이며 항상 있지는 않습니다. 앞에 있는 모두를 세게 때립니다.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "희귀 몹입니다. 대지 토템을 세웁니다. 부수세요.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "희귀 몹이며 항상 있지는 않습니다. 플레이어를 재우고 주변에 마법 폭발을 일으킵니다.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "쉽습니다. 마지막 우두머리 전에 물을 마시기 좋은 때입니다.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "주문을 시전하는 적입니다. 직업에 차단 기술이 있으면 쓰세요(발차기, 방패 가격, 대지 충격...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "토템을 쓰는 주술사입니다. 토템은 쉽게 부서지니 부수세요.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "방패를 든 드워프입니다. 오래 버티지만 특별한 기술은 없습니다.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "광산의 강한 적입니다. 작은 우두머리처럼 상대하세요.",
	["Es un grupo: cada uno suelta su propio botín."] = "여러 명이 함께 나오는 우두머리입니다. 각자 전리품을 떨어뜨립니다.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "성스러운 빛으로 자신을 치유하는 성기사입니다. 치유를 차단하세요.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "독을 거는 빠른 사티로스입니다. 직업이 독을 해제할 수 있으면 쓰세요.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "번개를 쓰는 트로그입니다. 차단하세요.",
	["Es una mejora para ti"] = "내 장비보다 좋음",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "직업 탈것입니다. 언제 어떻게 얻는지 직업 상급자에게 물어보세요.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "방어도가 높은 거대 거북입니다. 느리지만 세게 때립니다.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "아주 단단한 거북이지만 때리기만 합니다. 특별한 기술은 없습니다.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "이 문자열에는 Alfa가 점수를 매기는 능력치가 없습니다.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "그 줄은 아직 열리지 않았습니다. 그 계열에 포인트가 더 필요합니다.",
	["Esa tecla ya tiene dueño"] = "이미 사용 중인 키",
	["Esbirros enemigos"] = "적의 부하",
	["Escala de estadísticas"] = "능력치 척도",
	["Escalas:"] = "경유지:",
	["Escaneando..."] = "스캔 중...",
	["Escanear ahora"] = "지금 스캔",
	["Escanear con Alfa"] = "Alfa로 스캔",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "전체 스캔 완료: 가격이 있는 아이템 %s개 (경매 %s건).",
	["Escarcha"] = "냉기",
	["Escarcha para subir"] = "레벨업용 냉기",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "낚시하는 동안 이름표와 NPC 이름을 숨겨서(적대적인 적은 이름이 그대로 보입니다) 찌를 보고 클릭하기 쉽게 합니다.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "내 숙련도보다 높은 숙련도가 필요한 것을 숨깁니다. 끄면 회색으로 흐리게 표시됩니다.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "%s 명령어를 입력하거나 미니맵의 늑대를 클릭하면 열립니다. 오늘 탭에서 시작하며 내 직업에 필요한 것을 보여 줍니다. %s 명령어로 가이드 창을 표시하거나 숨깁니다.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "%s 명령어를 입력하고 La Jauría Discord에서 알려 주세요.",
	["Escribe al menos dos letras."] = "두 글자 이상 입력하세요.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "위에 던전 이름을 입력해 찾으세요.",
	["Escribe cuánto oro (1 o más)."] = "골드 양을 입력하세요(1 이상).",
	["Escribe el número que quieras y presiona Enter."] = "원하는 숫자를 입력하고 Enter를 누르세요.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "상위 %d명을 파티나 공격대 대화창에 씁니다.",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "공유 퀘스트의 목표를 마치면 파티 대화에 씁니다. 누구의 대화창도 도배하지 않도록 기본적으로 꺼져 있습니다.",
	["Escribe tu nota."] = "메모를 입력하세요.",
	["Escribe un nivel (2 o más)."] = "레벨을 입력하세요(2 이상).",
	["Escribe un nombre corto para reconocerla."] = "알아보기 쉬운 짧은 이름을 입력하세요.",
	["Escribir a %s"] = "%s 님에게 메시지",
	["Escuchar"] = "듣기",
	["Escuchar el aullido"] = "울음소리 듣기",
	["Escudo"] = "방패",
	["Escudo de relámpagos"] = "번개 보호막",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "방패와 방어: 모든 몬스터를 붙잡아 파티가 피해를 입지 않게 합니다.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "방패와 성스러운 빛: 자기 마나를 스스로 회복하는 아주 튼튼한 방어 전담입니다.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "보호막과 예방 치유: 잘 버티고 파티를 지원합니다.",
	["Ese build es para otra clase."] = "다른 직업용 빌드입니다.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "그 특성은 먼저 다른 특성을 끝까지 찍어야 합니다(트리의 화살표).",
	["Ese texto es demasiado largo para un build."] = "빌드 텍스트로는 너무 깁니다.",
	["Ese texto es demasiado largo para una cadena de escala."] = "척도 문자열로 쓰기에는 텍스트가 너무 깁니다.",
	["Ese texto no es una ruta de Alfa."] = "Alfa 경로 텍스트가 아닙니다.",
	["Esmeralda"] = "에메랄드",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Alfa 빌드 문자열이 아닙니다. ALFA1;로 시작해야 합니다.",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "능력치 척도 문자열이 아닙니다. 척도 문자열은 ( Pawn: v1: \"이름\": ... 으로 시작합니다.",
	["Eso se puede al salir de combate."] = "전투가 끝나면 할 수 있어요.",
	["Espacio"] = "스페이스",
	["Espacio libre"] = "빈 칸",
	["Espacio y dinero"] = "공간과 돈",
	["Espada de dos manos"] = "양손 도검",
	["Espada de una mano"] = "한손 도검",
	["Espalda"] = "등",
	["Español, inglés y siete idiomas más, en toda la interfaz."] = "스페인어, 영어 외 7개 언어로 인터페이스 전체를 제공합니다.",
	["Espera %s"] = "%s 대기",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "방어 전담이 적을 확실히 붙잡을 때까지 기다린 뒤 세게 때리세요.",
	["Espera a que termine el combate."] = "전투가 끝나길 기다리는 중.",
	["Espera a salir de combate para probarla."] = "테스트하려면 전투가 끝날 때까지 기다리세요.",
	["Espera a salir de combate."] = "전투가 끝날 때까지 기다리세요.",
	["Espera a terminar de entrar al juego."] = "게임 접속이 끝날 때까지 기다리세요.",
	["Espera · nivel %d"] = "대기 · %d레벨",
	["Espera: %s."] = "대기: %s.",
	["Esperan: %s."] = "대기: %s.",
	["Esperando"] = "대기 중",
	["Espíritu"] = "정신력",
	["Esquiva"] = "회피",
	["Esquivar"] = "회피",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Alfa에 이 직업의 능력치 가중치가 없습니다.",
	["Esta clase no tiene pesos de estadísticas."] = "이 직업의 능력치 가중치가 없습니다.",
	["Esta explicación no saldrá más. En Combate puedes volver a encenderlas."] = "이 설명은 더 이상 나오지 않습니다. 전투에서 다시 켤 수 있습니다.",
	["Esta sesión"] = "이번 세션",
	["Esta sesión, por recurso"] = "이번 세션, 자원별",
	["Esta sesión: %d capturas de %d lanzamientos. Desde siempre: %d."] = "이번 세션: %d마리 낚음 / %d번 던짐. 전체: %d.",
	["Esta sesión: %s"] = "이번 세션: %s",
	["Esta subasta no permite el escaneo completo."] = "이 경매장은 전체 스캔을 허용하지 않습니다.",
	["Esta va de %s y %s… ¿Te la cuento?"] = "이건 %s와(과) %s 이야기예요… 들려줄까요?",
	["Esta va de %s y de lobos… me toca de cerca. ¿Te la cuento?"] = "이건 %s와(과) 늑대 이야기예요… 저와 가까운 이야기죠. 들려줄까요?",
	["Establos"] = "야수 관리인",
	["Estadísticas"] = "능력치",
	["Este aviso ya no mostrará texto: solo el ícono. En Combate puedes volver a encenderlos."] = "이 알림은 이제 글자 없이 아이콘만 나옵니다. 전투에서 다시 켤 수 있습니다.",
	["Este banco no vende más espacio."] = "이 은행은 더 이상 공간을 팔지 않습니다.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "이 빌드는 엄청나게 세게 때리지만 오래 버티지 못합니다. 들어갈 때를 잘 고르세요.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "이 클릭은 아무것도 하지 않습니다. 치유 페이지의 내 마우스에서 할 일을 고르세요.",
	["Este cliente no carga los mosaicos del minimapa: se ve el arte pintado."] = "이 클라이언트는 미니맵 조각을 불러오지 않아 그림 지도가 보입니다.",
	["Este cliente no da el arte del mapa"] = "이 클라이언트는 지도 그림을 제공하지 않음",
	["Este cliente no deja compartir"] = "이 클라이언트에서는 공유할 수 없음",
	["Este cliente no deja compartir marcadores."] = "이 클라이언트에서는 마커를 공유할 수 없습니다.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "이 클라이언트는 클릭 설정을 자동으로 복사할 수 없습니다. 블리자드 클릭 시전 창이 열렸으니 거기서 설정하세요.",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "이 클라이언트에는 이 설정 중 %d개가 없어 표시하지 않습니다.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "이 클라이언트에는 블리자드 클릭 시전이 없습니다. 내 클릭은 Alfa 프레임에서 작동합니다.",
	["Este cliente no tiene la ventana del Legado."] = "이 클라이언트에는 유산 창이 없습니다.",
	["Este paso"] = "이 단계",
	["Este paso no tiene punto en el mapa."] = "이 단계는 지도에 표시할 지점이 없습니다.",
	["Este paso une el Bosque del Ocaso con el Pantano de las Penas, y casi todos lo cruzan sin detenerse."] = "이 고개는 그늘숲과 슬픔의 늪을 잇고, 거의 모두가 멈추지 않고 지나가요.",
	["Este talento no está en tu build."] = "이 특성은 내 빌드에 없습니다.",
	["Este tramo quedó vacío."] = "이 구간이 비었습니다.",
	["Estilo"] = "스타일",
	["Estilo de las barras"] = "바 스타일",
	["Estilo del chat"] = "대화창 스타일",
	["Estilo del mapa"] = "지도 스타일",
	["Estilo del minimapa"] = "미니맵 스타일",
	["Estilo y sonido"] = "스타일과 소리",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "전투 중에는 바꿀 수 없습니다. 전투가 끝나면 다시 시도하세요.",
	["Esto no se puede vincular."] = "링크로 걸 수 없습니다.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "이 필터는 게임이 아니라 Alfa가 그립니다. 인터페이스 전체 뒤에 있어 가리지 않으며, 스크린샷용으로 인터페이스를 숨겨도(Alt+Z) 보입니다.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "묘지에 있습니다. 시간이 지나며 피해를 주는 암흑 고통을 겁니다.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "폭포 옆 물속에 있습니다. 싸우기 전에 땅으로 끌어내세요.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "무기고에 있습니다. 외치고 나면 도끼를 들고 회전하며 주변 모두를 때립니다. 떨어지세요.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "도서관에 있으며 사냥개를 데리고 옵니다. 사냥개부터 처치하거나 광역 공격을 쓰세요.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "대성당에 숨어 있습니다. 저주를 걸고 자신을 치유합니다. 차단하세요.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "가시덩굴 굴에 가시멧돼지가 가득합니다. 한 번에 조금씩 끌어오세요.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "일하는 고블린들에 둘러싸여 있습니다. 그 고블린부터 하나씩 끌어오세요.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "멀록들에 둘러싸여 있습니다. 우두머리보다 주변 멀록을 먼저 끌어오세요.",
	["Estás aquí"] = "현재 위치",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "은행원 앞에 있습니다. 창에서 클릭 한 번으로 원하는 것을 보관하세요.",
	["Estás dentro"] = "안에 있음",
	["Estás descansando"] = "휴식 중입니다",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "전투 중입니다. 특성은 전투 중이 아닐 때만 바꿀 수 있습니다. 전투를 끝내고 다시 시도하세요.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "전투 중입니다. 전투가 끝나면 장비를 찾으세요.",
	["Estás en combate: lo que cambies se aplica al salir."] = "전투 중입니다. 바꾼 내용은 전투가 끝나면 적용됩니다.",
	["Estás en combate: lo que cambies se aplica en cuanto termine."] = "전투 중입니다. 바꾼 것은 전투가 끝나는 즉시 적용됩니다.",
	["Estás en combate: se aplica en cuanto termine."] = "전투 중입니다. 전투가 끝나는 즉시 적용됩니다.",
	["Estás en combate: tus cambios se aplican en cuanto termine."] = "전투 중입니다. 변경 사항은 전투가 끝나는 즉시 적용됩니다.",
	["Estás en grupo y otro aguanta al enemigo: apuñálalo por la espalda."] = "파티 중이고 다른 사람이 적을 붙잡고 있습니다. 뒤에서 기습하세요.",
	["Estás en grupo y otro aguanta al enemigo: trízalo por la espalda."] = "파티 중이고 다른 사람이 적을 붙잡고 있습니다. 뒤에서 칼날 발톱을 쓰세요.",
	["Estás en la ciudad y hay habilidades por entrenar (%d). ¡Aprovecha!"] = "마을에 있고 배울 기술이 있어요(%d). 지금 배워요!",
	["Estás en sigilo: Premeditación te da puntos de combo."] = "은신 중: 계획으로 연계 점수를 얻습니다.",
	["Estás en sigilo: abre con Emboscada por la espalda."] = "은신 중: 뒤에서 매복으로 시작하세요.",
	["Estás en sigilo: aturde al enemigo al abrir."] = "은신 중: 시작할 때 적을 기절시키세요.",
	["Estás en una instancia: la flecha vuelve al salir."] = "인스턴스 안입니다. 나가면 화살표가 돌아옵니다.",
	["Estás mirando otro paso"] = "다른 단계를 보고 있습니다",
	["Evento"] = "이벤트",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "치명타와 강타를 막아 줍니다. 방어 전담에게 가장 중요한 능력치입니다.",
	["Evitar misiones de grupo"] = "파티 퀘스트 피하기",
	["Experiencia"] = "경험치",
	["Experiencia y reputación"] = "경험치와 평판",
	["Experto"] = "전문",
	["Explicaciones"] = "설명",
	["Explicar por qué"] = "이유 설명",
	["Explicar por qué, unas pocas veces"] = "이유 설명(몇 번만)",
	["Explorar todo el mapa del mundo con un personaje es un reto del Legado. ¡Excusa perfecta para pasear conmigo!"] = "한 캐릭터로 세계 지도 전체를 탐험하는 건 유산 도전이에요. 저랑 산책할 완벽한 핑계죠!",
	["Fallas menos golpes, sobre todo contra monstruos de nivel más alto que el tuyo."] = "특히 내 레벨보다 높은 몬스터를 상대로 덜 빗나갑니다.",
	["Fallas menos golpes."] = "덜 빗나갑니다.",
	["Fallas menos: con dos armas fallas mucho sin esto."] = "덜 빗나갑니다. 쌍수 무기는 이것이 없으면 자주 빗나갑니다.",
	["Fallida"] = "실패",
	["Falta algo."] = "빠진 것이 있습니다.",
	["Falta el final del texto: cópialo completo."] = "텍스트 끝부분이 없습니다. 전체를 복사하세요.",
	["Falta el paquete de datos de Alfa (Alfa_Codex): vuelve a instalar Alfa completo."] = "Alfa 데이터 팩(Alfa_Codex)이 없습니다. Alfa 전체를 다시 설치하세요.",
	["Falta en un arma"] = "한 무기에 없음",
	["Falta la carpeta Alfa_Codex: reinstala Alfa."] = "Alfa_Codex 폴더가 없습니다. Alfa를 다시 설치하세요.",
	["Falta la función del juego para enviar mensajes de addon. Tu grupo sí se ve."] = "애드온 메시지를 보내는 게임 기능이 없습니다. 파티는 그래도 보입니다.",
	["Faltan las texturas de detalle en la carpeta Media de Alfa_Mundo: el mapa se dibuja solo con el arte del juego."] = "Alfa_Mundo의 Media 폴더에 세부 텍스처가 없습니다. 지도는 게임 그림만으로 그려집니다.",
	["Faltan los datos de las mazmorras"] = "던전 데이터가 없음",
	["Faltan los datos del mundo"] = "월드 데이터 없음",
	["Faltan los datos del mundo de Alfa (la carpeta Alfa_Codex): instala todas las carpetas de Alfa."] = "Alfa 월드 데이터(Alfa_Codex 폴더)가 없습니다. Alfa 폴더를 모두 설치하세요.",
	["Faltan precios"] = "가격 없음",
	["Faltan precios de algunos materiales."] = "일부 재료의 가격이 없습니다.",
	["Faltan precios de sus materiales: escanea la subasta."] = "재료 가격이 없습니다. 경매장을 스캔하세요.",
	["Fantasma"] = "유령",
	["Farmea cerca de un vendedor o de una posada: menos viajes y más botín."] = "상인이나 여관 근처에서 파밍하세요. 왕복은 줄고 전리품은 늘어요.",
	["Feliz"] = "행복",
	["Feral"] = "야성",
	["Fija"] = "고정됨",
	["Fijar"] = "고정",
	["Fijar el brillo de la interfaz"] = "인터페이스 밝기 설정",
	["Fijar el brillo máximo"] = "최대 밝기 설정",
	["Fijar marcos"] = "프레임 고정",
	["Fijar tu hogar en la posada de tu guía"] = "가이드 여관을 귀환 장소로 설정",
	["Filones y depósitos de mineral."] = "광맥과 광물 매장지입니다.",
	["Filtrado de texturas"] = "텍스처 필터링",
	["Filtros"] = "필터",
	["Fin de tu ruta: arma la siguiente en la página Ruta de Alfa."] = "경로 끝: Alfa의 경로 페이지에서 다음 경로를 만드세요.",
	["Fin del camino"] = "길의 끝",
	["Fin del horizonte"] = "지평선 끝",
	["Final de %s"] = "%s 끝",
	["Firma de Alfa"] = "Alfa 시그니처",
	["Flecha de mejora"] = "향상 화살표",
	["Flecha puesta"] = "화살표 설정됨",
	["Flechas"] = "화살",
	["Flor de paz y Hojaplata son las primeras hierbas; las encuentras en las zonas de inicio."] = "평온초와 은엽수가 첫 약초예요. 시작 지역에서 찾을 수 있어요.",
	["Fondo, pestañas y caja de escribir con tu estilo."] = "배경, 탭, 입력창을 내 스타일로.",
	["Fondos transparentes para ver el mundo detrás y el color de acento que elijas."] = "뒤의 세상이 비치는 투명한 배경과 내가 고른 강조 색.",
	["Forjaz está tallada dentro de la montaña: los enanos Barbabronce la construyeron alrededor de la Gran Forja."] = "아이언포지는 산속을 깎아 만들었어요. 청동수염 드워프들이 거대한 용광로를 중심으로 지었어요.",
	["Forma"] = "변신",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "빨리 처치할 때는 표범 변신, 어려운 전투에는 곰 변신. 물을 마실 일이 거의 없습니다.",
	["Forma normal"] = "기본 모습",
	["Foto: %s"] = "기록: %s",
	["Fragmentos de alma"] = "영혼의 조각",
	["Frases que ya te dijo todas sus veces"] = "정해진 횟수를 다 말한 대사",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "도망치는 적을 느리게 하고, 불리한 전투에서 빠져나가게 해 줍니다.",
	["Frena a los que huyen y te salva de malas peleas."] = "도망치는 적을 느리게 하고 불리한 전투에서 구해 줍니다.",
	["Frena a todos los rivales cercanos."] = "주변의 모든 상대를 느리게 합니다.",
	["Frondavil era parte del bosque de Vallefresno hasta que los demonios y sus sátiros lo corrompieron."] = "악령의 숲은 악마와 사티로스가 타락시키기 전까지 잿빛 골짜기 숲의 일부였어요.",
	["Frío"] = "차가움",
	["Fuego"] = "화염",
	["Fuego estelar: tu hechizo más fuerte."] = "천벌: 가장 강한 주문.",
	["Fuego feérico: el enemigo recibe más daño."] = "요정의 불꽃: 적이 받는 피해가 늘어납니다.",
	["Fuego interno"] = "내면의 열정",
	["Fuego para subir"] = "레벨업용 화염",
	["Fuego rápido: disparas mucho más rápido un rato."] = "속사: 잠시 훨씬 빠르게 사격합니다.",
	["Fuego sagrado: abre la pelea con mucho daño."] = "신성한 불꽃: 큰 피해로 전투를 엽니다.",
	["Fuentes: Blizzard (news.blizzard.com), warcraft.wiki.gg (Legacy System), Icy Veins y Method. Lo que ves arriba con tus números sale del juego."] = "출처: Blizzard(news.blizzard.com), warcraft.wiki.gg(Legacy System), Icy Veins, Method. 위에 보이는 내 숫자는 게임에서 가져온 것입니다.",
	["Fuera de combate es el mejor momento"] = "전투 중이 아닐 때가 가장 좋습니다",
	["Fuera de combate; necesita las placas de enemigos encendidas."] = "전투 중이 아닐 때. 적 이름표가 켜져 있어야 합니다.",
	["Fuera de este plan: %s (%s)."] = "이 계획에서 제외: %s(%s).",
	["Fuera de tu plan de misiones"] = "퀘스트 계획 밖",
	["Fuera del plan"] = "계획 밖",
	["Fuerza"] = "힘",
	["Fuerza del HDR"] = "HDR 강도",
	["Fuerza del tinte"] = "색조 강도",
	["Funciona también fuera del modo pesca. Está en el menú de atajos del juego, en Alfa."] = "낚시 모드 밖에서도 작동합니다. 게임의 단축키 설정 메뉴, Alfa 항목에 있습니다.",
	["Furia"] = "분노",
	["Furia con dos armas"] = "쌍수 분노 전문",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "최대한의 피해를 노린 분노 전문: 적중 증가, 향상된 마무리 일격, 엄청난 치명타. 처치는 아주 빠르지만 약합니다.",
	["Furia contra jugadores"] = "PvP 분노 전문",
	["Furia desatada"] = "고삐 풀린 분노",
	["Furia para grupo"] = "파티용 분노 전문",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "PvP용 분노 전문: 엄청난 피해, 공포에 맞서는 향상된 광전사의 격노, 상대를 놓치지 않도록 더 자주 쓰는 가로막기.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "피의 분노로 어려운 전투를 시작할 때 분노를 더 얻습니다.",
	["Gadgetzan es la ciudad goblin del desierto: ahí todo se compra y todo se vende, hasta el agua."] = "가젯잔은 사막의 고블린 도시예요. 물까지, 거기선 모든 걸 사고팔아요.",
	["Gadgetzan tiene una de las casas de subastas neutrales, donde comercian Alianza y Horda."] = "가젯잔에는 얼라이언스와 호드가 거래하는 중립 경매장이 있어요.",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "경험치를 조금 얻으면 Alfa가 남은 시간을 계산합니다.",
	["Gana un poco de XP y Alfa lo calcula"] = "경험치를 조금 얻으면 Alfa가 계산합니다",
	["Ganado"] = "획득",
	["Ganado %s"] = "획득 %s",
	["Ganado: %s. Gastado: %s. Suma tus sesiones de hoy con este personaje."] = "획득: %s. 사용: %s. 이 캐릭터의 오늘 세션을 합친 값입니다.",
	["Ganados"] = "획득",
	["Ganas de más"] = "추가 수익",
	["Garra: suma puntos de combo."] = "할퀴기: 연계 점수를 쌓습니다.",
	["Gasta la ira sobrante en Golpe heroico; si llegas a 100 de ira, la estás desperdiciando."] = "남는 분노는 영웅의 일격에 쓰세요. 분노가 100이 되면 낭비하고 있는 것입니다.",
	["Gastado"] = "지출",
	["Gastados"] = "사용",
	["General, por categorías o por bolsa, y depósito rápido al banco."] = "전체 보기, 분류별, 가방별 보기와 빠른 은행 보관.",
	["Giro inteligente"] = "똑똑한 회전",
	["Gnomos"] = "노움",
	["Golpe"] = "적중",
	["Golpe con hechizos"] = "주문 적중",
	["Golpe crítico"] = "치명타",
	["Golpe fantasmal: daño y esquivas más, cada vez que esté listo."] = "유령의 일격: 피해와 회피 증가. 준비될 때마다 쓰세요.",
	["Golpe fuerte que además reduce las curas del rival."] = "상대가 받는 치유도 줄이는 강력한 공격입니다.",
	["Golpe heroico cuesta menos ira: lo usarás en cada pelea."] = "영웅의 일격의 분노 소모가 줄어 모든 전투에서 쓰게 됩니다.",
	["Golpe heroico más barato."] = "더 저렴한 영웅의 일격.",
	["Golpe heroico más barato: amenaza extra con la ira que sobra."] = "더 저렴한 영웅의 일격: 남는 분노로 위협 수준을 추가로 쌓습니다.",
	["Golpe heroico más barato: la ira sobrante se vuelve amenaza."] = "더 저렴한 영웅의 일격: 남는 분노가 위협 수준이 됩니다.",
	["Golpe heroico: tu golpe más fuerte mientras subes."] = "영웅의 일격: 레벨을 올리는 동안 가장 강한 공격.",
	["Golpe mental: mucho daño, cada vez que esté listo."] = "정신 분열: 큰 피해. 준비될 때마다 쓰세요.",
	["Golpe mortal: tu golpe más fuerte, cada vez que esté listo."] = "죽음의 일격: 가장 강한 공격. 준비될 때마다 쓰세요.",
	["Golpe siniestro: suma puntos de combo."] = "사악한 일격: 연계 점수를 쌓습니다.",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "주변을 때립니다. 파티 반대쪽으로 돌려세우세요.",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "주변 모두를 때리고 밀쳐 냅니다. 근접이라면 생명력을 잘 챙기세요.",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "앞에 있는 모두를 때립니다. 근접이라면 등 뒤에서 공격하세요.",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "앞에 있는 모두를 때립니다. 근접이라면 뒤에서 공격하세요.",
	["Golpea a varios enemigos a tu alrededor."] = "주위의 여러 적을 공격합니다.",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "식칼로 세게 때리고 출혈을 일으킵니다. 방어 전담의 생명력을 지켜보세요.",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "방어 전담을 때려 밀쳐 냅니다. 빨리 제자리로 돌아오세요.",
	["Golpea y frena a todos los enemigos que tienes cerca."] = "가까운 모든 적을 공격하고 느리게 합니다.",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "두 마리를 동시에 때립니다. 몬스터를 두 마리씩 끌 수 있습니다.",
	["Golpes de tu mascota"] = "소환수의 근접 공격",
	["Gracias por dejarme acompañarte."] = "함께하게 해 줘서 고마워요.",
	["Grafito"] = "흑연",
	["Grafito con esquinas cortadas y el verde de La Jauría. El de siempre."] = "모서리를 깎은 흑연색과 La Jauría의 초록색. 익숙한 기본 스타일.",
	["Gran aumento de daño para los jefes."] = "우두머리를 상대로 피해가 크게 늘어납니다.",
	["Gran aumento de daño y te libra del miedo."] = "피해가 크게 늘고 공포에서 풀려납니다.",
	["Gran aumento de daño."] = "피해가 크게 늘어납니다.",
	["Gran golpe de escudo con mucha amenaza."] = "위협 수준이 높은 강력한 방패 공격입니다.",
	["Grano"] = "그레인",
	["Grano de película"] = "필름 그레인",
	["Gratis"] = "무료",
	["Gratis tras vencer a un enemigo, y te cura."] = "적을 처치한 뒤 비용 없이 쓸 수 있고 생명력을 회복시킵니다.",
	["Grifos"] = "그리핀",
	["Grim Batol fue una ciudad enana. Después, los orcos Faucedraco la usaron para tener presa a Alexstrasza, la Reina Dragón."] = "그림 바톨은 드워프의 도시였어요. 나중에 용아귀 오크들이 용의 여왕 알렉스트라자를 그곳에 가두었어요.",
	["Grito de batalla"] = "전투의 외침",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "전사는 전투의 외침, 마법사는 신비한 지능과 갑옷 주문, 사제는 신의 권능: 인내와 내면의 열정 등 직업마다 알맞은 강화 효과를 알려 줍니다.",
	["Grom Grito Infernal fue el primer jefe orco en beber la sangre de Mannoroth, y así ató a su pueblo a los demonios."] = "그롬 헬스크림은 만노로스의 피를 마신 첫 오크 족장이었고, 그렇게 자기 종족을 악마에게 묶었어요.",
	["Grom Grito Infernal y Varian Wrynn son guerreros legendarios de la historia."] = "그롬 헬스크림과 바리안 린은 역사 속 전설적인 전사예요.",
	["Grom'gol es el campamento de la Horda en la Vega, con zepelines a Orgrimmar y a Entrañas."] = "그롬골은 가시덤불 골짜기의 호드 야영지로, 오그리마와 언더시티로 가는 비행선이 있어요.",
	["Grupo"] = "파티",
	["Grupo de %d"] = "%d인 파티",
	["Grupo de 5"] = "5인 파티",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "퀘스트 %d개는 남겨 두세요. 다음 가이드에서 제출합니다.",
	["Guarda Grito intimidador para cuando estés en peligro."] = "위험할 때를 위해 위협의 외침을 아껴 두세요.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "우두머리의 가장 위험한 순간을 위해 방패의 벽을 아껴 두세요.",
	["Guarda en el banco los materiales que todavía no usas, y deja las bolsas libres para el botín."] = "아직 안 쓰는 재료는 은행에 맡기고, 가방은 전리품을 위해 비워 두세요.",
	["Guarda o cambia tu mascota"] = "소환수 보관 또는 교체",
	["Guarda un poco de tela para vendas: Primeros auxilios también la usa."] = "붕대용으로 천을 조금 남겨 두세요. 응급치료도 천을 써요.",
	["Guardada el %s"] = "저장: %s",
	["Guardar"] = "보관",
	["Guardar %d"] = "보관 %d",
	["Guardar como marcador"] = "마커로 저장",
	["Guardar y seguir"] = "저장하고 따라가기",
	["Guardas ira al cambiar de actitud."] = "태세를 바꿔도 분노가 남습니다.",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "태세를 바꿔도 분노가 남아, 돌진, 제압, 복수를 거의 공짜로 쓸 수 있습니다.",
	["Guardaste %d objeto en el banco."] = "은행에 아이템 %d개를 보관했습니다.",
	["Guardaste %d objetos en el banco."] = "은행에 아이템 %d개를 보관했습니다.",
	["Guardianes enemigos"] = "적의 수호물",
	["Guerrero"] = "전사",
	["Guiarme"] = "안내 시작",
	["Gul'dan fue el primer brujo orco, y su historia no terminó nada bien. Tú úsalo con más cabeza."] = "굴단은 첫 오크 흑마법사였고, 그 이야기는 전혀 좋게 끝나지 않았어요. 그 힘은 더 현명하게 쓰세요.",
	["Gul'dan fundó el Consejo de la Sombra, un grupo de brujos que movía a la Horda desde las sombras."] = "굴단은 그림자 속에서 호드를 조종한 흑마법사 집단, 어둠의 의회를 세웠어요.",
	["Guía"] = "가이드",
	["Guía a tu manada"] = "무리를 이끄세요",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "가이드를 새 탭에서 열었습니다. 화살표를 따라가세요.",
	["Guía actual"] = "현재 가이드",
	["Guía de pesca"] = "낚시 가이드",
	["Guía para desbloquearla en marcha"] = "잠금 해제 가이드 진행 중",
	["Guía: %s"] = "가이드: %s",
	["Guíame"] = "안내 시작",
	["Guíame a Bahía del Botín"] = "무법항으로 안내",
	["Guíame a la misión"] = "퀘스트로 안내",
	["Guíame a la receta"] = "요리법으로 안내",
	["Guíame a una caña"] = "낚싯대 있는 곳으로 안내",
	["Guíame al pescador"] = "낚시꾼에게 안내",
	["Guíame aquí"] = "여기로 안내",
	["Guíame te lleva paso a paso."] = "«안내 시작»으로 한 단계씩 안내받습니다.",
	["Guías"] = "가이드",
	["Guías con %s"] = "%s 포함 가이드",
	["Guías de la comunidad"] = "커뮤니티 가이드",
	["Guías y planes"] = "가이드와 계획",
	["HDR (Windows)"] = "HDR (Windows)",
	["Habilidades más baratas."] = "기술 비용이 줄어듭니다.",
	["Habilidades más baratas: más golpes de amenaza."] = "기술 비용이 줄어 위협 공격을 더 쓸 수 있습니다.",
	["Habilidades nuevas por aprender: %d. Tu entrenador te espera."] = "배울 새 기술: %d. 상급자가 기다리고 있어요.",
	["Habilidades por entrenar"] = "수련할 기술",
	["Habilidades que vigila la ayuda de Blizzard"] = "Blizzard 전투 보조가 살피는 기술",
	["Habitual"] = "단골",
	["Habla con %s"] = "%s에게 말 걸기",
	["Habla con el maestro de vuelo de cada pueblo nuevo: así aprendes la ruta."] = "새 마을마다 비행 조련사와 대화하세요. 그래야 경로를 배워요.",
	["Habla con un banquero para comprarla."] = "구매하려면 은행원과 대화하세요.",
	["Hablar"] = "말하기",
	["Hace heridas que sangran: vigila la vida del tanque."] = "출혈 상처를 입힙니다. 방어 전담의 생명력을 지켜보세요.",
	["Hace mil años, en la Guerra de las Arenas Movedizas, los elfos y los dragones encerraron a los qiraji tras el Muro del Escarabajo."] = "천 년 전 흐르는 모래의 전쟁 때, 엘프와 용들이 퀴라지를 스카라베 성벽 뒤에 가두었어요.",
	["Hace más de diez mil años todas las tierras eran un solo continente: Kalimdor, que en élfico quiere decir «tierra de la eterna luz de las estrellas»."] = "만 년도 더 전에는 모든 땅이 하나의 대륙이었어요. 엘프어로 «영원한 별빛의 땅»이라는 뜻의 칼림도어예요.",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "적에게 출혈을 일으킵니다. 전투를 시작할 때 거세요.",
	["Hace sangrar mucho: vale la pena con enemigos que duran."] = "출혈이 큽니다. 오래 버티는 적에게 쓸 만합니다.",
	["Hace siglos, Aegwynn venció a un avatar de Sargeras y escondió su cuerpo en la Tumba de Sargeras, en las Islas Abruptas."] = "수 세기 전 에이그윈은 살게라스의 화신을 물리치고, 그 몸을 부서진 섬의 살게라스의 무덤에 숨겼어요.",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "경로를 만들려면 지역에 그 자원의 서로 다른 위치가 3곳 이상 필요합니다.",
	["Hacer mazmorras con tu grupo da botín, misiones y reputación: es farmeo con plática incluida."] = "파티와 던전을 돌면 전리품, 퀘스트, 평판을 얻어요. 수다가 덤으로 따라오는 파밍이죠.",
	["Hacer oro"] = "골드 벌기",
	["Haces de luz entre árboles, nubes y montañas."] = "나무, 구름, 산 사이로 비치는 빛줄기.",
	["Hacha de dos manos"] = "양손 도끼",
	["Hacha de una mano"] = "한손 도끼",
	["Hacia %s"] = "목적지: %s",
	["Hacia %s (niv. %s)"] = "목적지: %s (레벨 %s)",
	["Hacia abajo"] = "아래로",
	["Hacia arriba"] = "위로",
	["Hacia dónde se acomodan tus compañeros."] = "파티원이 배치되는 방향입니다.",
	["Hacia:"] = "목적지:",
	["Hacia: %s"] = "목적지: %s",
	["Halloween recuerda el día en que los Renegados se liberaron del Rey Exánime: por eso queman al Hombre de Mimbre."] = "할로윈 축제는 포세이큰이 리치 왕에게서 풀려난 날을 기념해요. 그래서 고리버들 인형을 태워요.",
	["Hamuul Tótem de Runa, el archidruida de Cima del Trueno, fue de los primeros tauren aceptados en el Círculo Cenarion."] = "썬더 블러프의 대드루이드 하물 룬토템은 세나리온 의회에 들어간 첫 타우렌 중 하나였어요.",
	["Hasta dónde llegan las montañas lejanas."] = "먼 산이 보이는 거리.",
	["Hasta dónde puedes alejar la cámara con la rueda. El juego puede limitarlo: Alfa muestra el valor que de verdad quedó."] = "휠로 카메라를 얼마나 멀리 뺄 수 있는지. 게임이 제한할 수 있으며, Alfa는 실제로 적용된 값을 보여 줍니다.",
	["Hasta dónde se dibuja el mundo. Es lo que más FPS cuesta."] = "세상을 그리는 거리. FPS를 가장 많이 잡아먹습니다.",
	["Hasta dónde se dibuja el pasto. Más lejos, menos «alfombra» que aparece al caminar."] = "풀을 그리는 거리. 멀수록 걸을 때 갑자기 나타나는 «풀 카펫»이 줄어듭니다.",
	["Hasta el alfa se cae. Lo importante es levantarse. ¡Vamos!"] = "알파도 넘어져요. 중요한 건 다시 일어서는 거예요. 가요!",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "20레벨까지는 양손 무기를 쓰고, 그다음 한손 무기 두 개로 바꾸세요.",
	["Hasta mi nivel"] = "내 레벨까지",
	["Hasta qué distancia se ven las placas de nombre. El juego puede limitarlo."] = "이름표가 보이는 거리. 게임이 제한할 수 있습니다.",
	["Hasta qué nivel"] = "목표 레벨",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "늑대로 변하는 적과 공포를 거는 적이 있습니다. 공포에 걸려도 당황하지 말고 기다리세요.",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "물이 많습니다. 물속에서 헤엄칠 때는 호흡 막대를 보고 숨을 쉬러 올라오세요.",
	["Hay muchas tribus trol: Amani, Gurubashi, Furiarena, Zandalar... y casi todas pelean entre sí."] = "트롤 부족은 많아요. 아마니, 구루바시, 성난모래, 잔달라... 그리고 거의 다 서로 싸워요.",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "언데드와 가시멧돼지가 많습니다. 파티에 질병을 해제할 수단이 있으면 챙기세요.",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "트로그와 불의 정령이 붙어 있습니다. 한 번에 한두 무리만 끌어오세요.",
	["Hay nueve clases en el Clásico, pero solo la Alianza tiene paladines y solo la Horda tiene chamanes."] = "클래식에는 직업이 아홉 개 있지만, 성기사는 얼라이언스에만, 주술사는 호드에만 있어요.",
	["Hay una guía de Alfa"] = "Alfa 가이드 있음",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "지도에서 원하는 곳을 오른쪽 클릭(또는 Shift+클릭)하세요. 이름, 아이콘, 색을 정하면 언제든 화살표가 안내합니다.",
	["Haz clic en un marco de ejemplo"] = "예시 프레임을 클릭하세요",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "클릭한 뒤 원하는 키를 누르세요(Esc는 취소). 오른쪽 클릭하면 지웁니다.",
	["Haz clic y pulsa la tecla, un botón del ratón o la rueda (con Mayús, Ctrl o Alt si quieres). Esc cancela; clic derecho la quita."] = "클릭한 뒤 키, 마우스 버튼, 휠을 누르세요(원하면 Shift, Ctrl, Alt와 함께). Esc는 취소, 오른쪽 클릭은 해제입니다.",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "단축키 없이 월드에서 오른쪽 더블 클릭으로 낚싯대를 던집니다. 전투 중이나 비행 중에는 작동하지 않습니다.",
	["Hecha"] = "완료",
	["Hecha %d veces"] = "%d회 완료",
	["Hechas"] = "완료",
	["Hechizo del preajuste"] = "프리셋 주문",
	["Hechizo desconocido"] = "알 수 없는 주문",
	["Hechizo elegido por ti"] = "직접 고른 주문",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "치유 클릭에 쓸 새 주문이 있습니다. /alfa curacion에서 여세요.",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "시간이 지나며 피해를 주는 암흑 주문: 쉬는 시간이 거의 없이 혼자 레벨을 가장 잘 올리는 사제입니다.",
	["Hechizos de tu mascota"] = "소환수의 주문",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "멀리서 주문을 쓰고 뿌리로 묶어 몬스터가 다가오지 못하게 합니다. 마지막에 달빛야수 변신을 얻습니다.",
	["Hecho"] = "완료",
	["Hemet Nesingwary organiza safaris por toda la Vega: sus encargos de cazar panteras, tigres y raptores son famosos."] = "헤멧 네싱워리는 가시덤불 골짜기 곳곳에서 사냥 여행을 열어요. 표범, 호랑이, 랩터 사냥 의뢰로 유명해요.",
	["Hemorragia: suma puntos de combo y el enemigo recibe más daño."] = "과다출혈: 연계 점수를 쌓고 적이 받는 피해가 늘어납니다.",
	["Hender armadura más barato."] = "더 저렴한 방어구 가르기.",
	["Hender armadura más barato: amenaza constante."] = "더 저렴한 방어구 가르기: 꾸준한 위협 수준.",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "더 저렴한 방어구 가르기: 여러 적에게 위협 수준을 더 쌓습니다.",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "방어구 가르기: 꾸준한 위협 수준, 적이 받는 피해 증가.",
	["Herboristería"] = "약초채집",
	["Herboristería combina bien con Alquimia, y también con Desollar o Minería para recolectar el doble."] = "약초 채집은 연금술과 잘 맞고, 무두질이나 채광과 함께하면 두 배로 모을 수 있어요.",
	["Herramienta"] = "도구",
	["Herramientas"] = "도구",
	["Herrería"] = "대장기술",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "대장기술로 내 레벨에 아주 좋은 무기와 판금 방어구를 만들고, 채광으로 재료를 공짜로 얻습니다.",
	["Herrería fabrica escudos y piezas resistentes."] = "대장기술로 방패와 튼튼한 장비를 만듭니다.",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "대장기술로 방어 숙련과 체력이 붙은 방패와 판금을 만듭니다. 방어 전담에게 딱 필요한 것입니다.",
	["Herrería y Minería van de la mano: tú sacas el metal y tú lo forjas."] = "대장기술과 채광은 짝꿍이에요. 금속을 직접 캐서 직접 벼려요.",
	["Hielo"] = "얼음",
	["Hierbas"] = "약초",
	["Historias"] = "이야기",
	["Historias de tus misiones"] = "내 퀘스트 이야기",
	["Historias guardadas"] = "저장된 이야기",
	["Historias y datos curiosos"] = "이야기와 흥미로운 사실",
	["Hogger es un gnoll de Elwynn tan temido que, para muchos aventureros, fue su primer gran reto."] = "호거는 엘윈 숲의 놀인데, 너무 무서워서 많은 모험가에게 첫 큰 시련이었어요.",
	["Hombros"] = "어깨",
	["Honor"] = "명예",
	["Horarios de barcos y zepelines"] = "배와 비행선 시간표",
	["Horda"] = "호드",
	["Hoy"] = "오늘",
	["Hoy en números"] = "오늘의 숫자",
	["Hoy te guía"] = "오늘이 안내합니다",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "오늘, 모험, 캐릭터, 월드, 전문 기술, 무리를 한 창에서: %s 또는 미니맵의 늑대.",
	["Hoy, a tu clase"] = "오늘, 내 직업에 맞게",
	["Huele a pan recién hecho por aquí… se me antoja."] = "여기서 갓 구운 빵 냄새가 나요… 먹고 싶다.",
	["Huele a salchichas asadas por aquí… ¿o es mi imaginación?"] = "여기서 구운 소시지 냄새가 나요… 아니면 제 착각일까요?",
	["Huella"] = "발자국",
	["Humanos"] = "인간",
	["Humo, agua y efectos se funden con lo que tocan en lugar de cortarse en seco."] = "연기, 물, 효과가 닿는 곳과 뚝 끊기지 않고 자연스럽게 섞입니다.",
	["Huracán: golpea a todos a tu alrededor."] = "소용돌이: 주위의 모든 적을 공격합니다.",
	["Háblame de mi gente"] = "내 종족 이야기 들려줘",
	["Iconos de viaje en el minimapa"] = "미니맵 이동 아이콘",
	["Idioma"] = "언어",
	["Igual que Alfa"] = "Alfa와 같게",
	["Igual que lo tuyo"] = "내 것과 같음",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "다른 군주들과 같습니다. 번개를 쓰고 자신을 치유합니다. 치유를 차단하세요.",
	["Illidan absorbió el poder del Cráneo de Gul'dan y se volvió mitad demonio. Por eso Malfurion lo desterró."] = "일리단은 굴단의 해골의 힘을 흡수해 반쯤 악마가 됐어요. 그래서 말퓨리온이 그를 추방했어요.",
	["Illidan guardó agua del Pozo antes de su caída y creó uno nuevo en Hyjal. Por eso Malfurion lo encerró bajo tierra durante diez mil años."] = "일리단은 샘이 무너지기 전에 그 물을 챙겨 하이잘에 새 샘을 만들었어요. 그래서 말퓨리온이 그를 만 년 동안 땅속에 가뒀어요.",
	["Illidan se fue a Terrallende, lo que quedó de Draenor, y ahí se hizo de un ejército propio."] = "일리단은 드레노어의 남은 조각인 아웃랜드로 가서 자기 군대를 꾸렸어요.",
	["Illidan, el gemelo de Malfurion, amaba a Tyrande, pero ella eligió a su hermano. Esa herida lo acompañó por diez mil años."] = "말퓨리온의 쌍둥이 일리단은 티란데를 사랑했지만, 그녀는 형제를 택했어요. 그 상처가 만 년 동안 그를 따라다녔어요.",
	["Imagen HDR"] = "HDR 출력",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "능력치 척도 문자열을 가져오고, 보유한 척도를 사용, 이름 변경, 내보내기 또는 삭제합니다.",
	["Importado"] = "가져옴",
	["Importado: %s. Ya puedes seguirlo."] = "가져옴: %s. 이제 따라갈 수 있습니다.",
	["Importar"] = "가져오기",
	["Importar un build"] = "빌드 가져오기",
	["Importar una ruta"] = "경로 가져오기",
	["Importar..."] = "가져오기...",
	["Inclina la cámara al subir y bajar cuestas."] = "오르막과 내리막에서 카메라를 기울입니다.",
	["Ingeniería"] = "기계공학",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "기계공학은 결투를 이기게 해 주는 기절 도구와 잔재주를, 채광은 재료를 줍니다.",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "기계공학은 상대를 제어하는 수류탄과 그물을, 채광은 재료를 줍니다.",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "기계공학은 PvP 전투를 결정짓는 수류탄, 그물, 폭탄을, 채광은 재료를 줍니다.",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "기계공학은 탈출 도구로 목숨을 구해 주고, 재봉술은 옷을 만들어 줍니다.",
	["Inicio"] = "홈",
	["Inicio de Alfa"] = "Alfa 홈",
	["Inicio del horizonte"] = "지평선 시작",
	["Instantánea: úsala cada vez que esté lista."] = "즉시 시전: 준비될 때마다 쓰세요.",
	["Instructor"] = "상급자",
	["Instructor de %s"] = "%s 상급자",
	["Instructor de equitación"] = "탈것 조련사",
	["Instructor de pesca"] = "낚시 전문가",
	["Instructores"] = "상급자",
	["Instructores de %s"] = "%s 상급자",
	["Instructores de pesca"] = "낚시 전문가",
	["Instructores y vendedores"] = "전문가와 상인",
	["Intelecto"] = "지능",
	["Intelecto Arcano"] = "신비한 지능",
	["Intentar ahora"] = "지금 시도",
	["Intentar otra vez"] = "다시 시도",
	["Interceptar más seguido: el rival no se escapa."] = "가로막기를 더 자주: 상대가 도망치지 못합니다.",
	["Interfaz"] = "인터페이스",
	["Interfaz del juego"] = "게임 인터페이스",
	["Interrumpes hechizos y los silencias."] = "주문을 차단하고 침묵시킵니다.",
	["Interrumpes y silencias hechizos."] = "주문을 차단하고 침묵시킵니다.",
	["Intimidación: tu mascota aturde al enemigo."] = "위협: 소환수가 적을 기절시킵니다.",
	["Invitaciones a hermandades"] = "길드 초대",
	["Invitaciones de grupo de desconocidos"] = "모르는 사람의 파티 초대",
	["Invitar"] = "초대",
	["Invitar al grupo"] = "파티에 초대",
	["Invitar, comerciar, susurrar…"] = "초대, 거래, 귓속말…",
	["Invitaste a %s a tu grupo."] = "%s 님을 파티에 초대했습니다.",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "멧돼지 정령을 소환합니다. 처치하거나 누군가 맡으세요.",
	["Invócalo antes de pelear."] = "전투 전에 소환하세요.",
	["Ir"] = "이동",
	["Ir a la zona recomendada"] = "추천 지역으로 이동",
	["Ir a un lugar"] = "장소로 이동",
	["Ir a: %s"] = "이동: %s",
	["Ir al mapa del juego"] = "게임 지도로 가기",
	["Ir al resumen"] = "요약으로 이동",
	["Ir por el camino es más seguro que cortar por en medio: los caminos tienen menos enemigos."] = "가로질러 가는 것보다 길을 따라가는 게 안전해요. 길에는 적이 적어요.",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "공포에서 벗어날 때 분노를 얻습니다. 상대가 공포를 자주 겁니다.",
	["Ira aunque el rival huya o te frene."] = "상대가 도망치거나 나를 느리게 해도 분노를 얻습니다.",
	["Ira constante en peleas largas contra jefes."] = "우두머리와의 긴 전투에서도 분노가 꾸준합니다.",
	["Ira constante."] = "꾸준한 분노.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "꾸준한 분노: 쓸 기술이 떨어지지 않습니다.",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "아무도 때리지 않아도 몇 초마다 분노를 공짜로 얻습니다.",
	["Izquierdo"] = "왼쪽",
	["Jaina Valiente fue alumna de Antonidas antes de fundar Theramore."] = "제이나 프라우드무어는 테라모어를 세우기 전에 안토니다스의 제자였어요.",
	["JcJ"] = "PvP",
	["JcJ (12): rangos de honor 3, 7, 10, 13 y 14; exaltado con las 4 facciones de los campos de batalla; las semanas 4, 7 y 10 del viaje de temporada Campo de Honor."] = "PvP (12): 명예 계급 3, 7, 10, 13, 14; 전장 진영 4곳에서 확고한 동맹; 명예의 전장 시즌 여정 4, 7, 10주차.",
	["Jefe"] = "우두머리",
	["Jefe %d por descubrir"] = "우두머리 %d, 아직 미발견",
	["Jefe final"] = "최종 우두머리",
	["Jefes"] = "우두머리",
	["Jefes vencidos"] = "처치한 우두머리",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "이 캐릭터의 처치한 우두머리, 완료한 던전, 기록된 전리품입니다. 설정은 그대로 둡니다.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "모든 던전과 공격대의 우두머리, 전리품, 입구.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "캐릭터마다 한 번씩 플레이하면 Alfa가 가방과 은행을 기억합니다.",
	["Juega siempre en actitud defensiva con escudo."] = "항상 방패를 들고 방어 태세로 플레이하세요.",
	["Juguetes y consumibles de pesca"] = "낚시 장난감과 소비용품",
	["Junta %d de %s"] = "%d개 모으기: %s",
	["Junta 100 capturas."] = "100마리를 낚으세요.",
	["Junta 1000 capturas."] = "1000마리를 낚으세요.",
	["Junta 500 capturas."] = "500마리를 낚으세요.",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "몬스터 두 마리를 끌고 휩쓸기 일격을 쓰세요. 그러면 레벨이 더 빨리 오릅니다.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "몬스터를 두세 마리 끌고 천둥벼락과 복수를 쓰세요. 쉬지 않고 안전하게 레벨을 올립니다.",
	["Junta lo gris y lo blanco para vender: suma más de lo que parece."] = "회색과 흰색 아이템을 모아 파세요. 생각보다 꽤 쌓여요.",
	["Junta los montones y acomoda tus objetos con un clic."] = "클릭 한 번으로 아이템을 합치고 정리합니다.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "아이템을 합치고 정리합니다. 전투 중에는 안 됩니다.",
	["Junta materiales de tu profesión donde más hay."] = "전문 기술 재료가 가장 많은 곳에서 모읍니다.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "전문 기술 재료를 모으면서 중간중간 경험치 퀘스트도 합니다.",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "같은 지역의 퀘스트를 모아서 하세요. 한 번에 여러 개를 끝낼 수 있어요.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "몬스터 여러 마리를 끄세요. 신성 공격이 모두에게 닿습니다.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "게임의 모든 정보를 모으는 중입니다. 처음 열 때만 그렇습니다.",
	["Juntar %s"] = "모으기: %s",
	["Juntar los materiales de mi profesión"] = "내 전문 기술 재료 모으기",
	["Juntar materiales para vender"] = "팔 재료 모으기",
	["Juntar nodos cercanos al alejar"] = "지도를 축소하면 가까운 지점 묶기",
	["Juntar oro"] = "골드 모으기",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "게임 지도 돋보기 옆: 레이어, 깔끔 모드, Alfa 지도로 바꾸는 «Alfa 지도».",
	["Junto a tu guía hay un botón para buscar lo que tienes cerca: vuelo, banco, subasta, reparar, comerciantes y entrenadores."] = "가이드 옆에 근처의 비행, 은행, 경매장, 수리, 상인, 상급자를 찾는 버튼이 있습니다.",
	["Kael'thas fue miembro del Kirin Tor de Dalaran antes de guiar a los elfos de sangre."] = "캘타스는 블러드 엘프를 이끌기 전에 달라란 키린 토의 일원이었어요.",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "마지막 수호자 메디브의 탑 카라잔은 자연 마력선이 교차하는 곳에 솟아 있어요.",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "호드 야영지 카르가스는 으스러진 손 부족의 옛 오크 족장 이름을 땄어요.",
	["Kel'Thuzad era un archimago de Dalaran. Lo expulsaron por estudiar nigromancia y acabó al servicio del Rey Exánime."] = "켈투자드는 달라란의 대마법사였어요. 강령술을 연구하다 쫓겨났고, 결국 리치 왕을 섬기게 됐어요.",
	["Kel'Thuzad tiene un gato, el señor Bigglesworth, que lo acompaña en Naxxramas. ¡Ni se te ocurra hacerle daño!"] = "켈투자드에게는 낙스라마스에서 함께하는 고양이 미스터 비글스워스가 있어요. 절대 다치게 하지 마세요!",
	["Khadgar fue el aprendiz de Medivh. Al pelear contra su maestro poseído envejeció de golpe y se quedó con el pelo blanco."] = "카드가는 메디브의 제자였어요. 사로잡힌 스승과 싸우다 단숨에 늙어 머리가 하얗게 셌어요.",
	["Khaz Modan es la tierra de los enanos, desde las nieves de Dun Morogh hasta los valles de Loch Modan."] = "카즈 모단은 던 모로의 눈밭부터 모단 호수의 골짜기까지 이어진 드워프의 땅이에요.",
	["Kil'jaeden encerró el alma de Ner'zhul en un bloque de hielo y lo arrojó a Rasganorte: así nació el Rey Exánime."] = "킬제덴은 넬쥴의 영혼을 얼음 덩어리에 가둬 노스렌드로 던졌어요. 그렇게 리치 왕이 태어났어요.",
	["Kil'jaeden engañó a Ner'zhul, el chamán más sabio de Draenor, y su aprendiz Gul'dan terminó de entregar a los orcos a la Legión."] = "킬제덴은 드레노어에서 가장 현명한 주술사 넬쥴을 속였고, 그 제자 굴단이 오크들을 군단에 완전히 넘겼어요.",
	["Korialstrasz, el consorte de Alexstrasza, anduvo entre los mortales como Krasus, un mago del consejo de Dalaran."] = "알렉스트라자의 배우자 코리알스트라즈는 달라란 의회의 마법사 크라서스로 필멸자들 사이를 다녔어요.",
	["Kul Tiras es un reino isleño de marineros. Su gran almirante, Daelin Valiente, era el padre de Jaina."] = "쿨 티라스는 뱃사람들의 섬 왕국이에요. 대제독 데일린 프라우드무어가 제이나의 아버지였어요.",
	["La %s también está en el menú del juego."] = "%s 설정은 게임 메뉴에도 있습니다.",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "북녘골 수도원은 왕국에서 가장 오래된 수도원 중 하나예요. 많은 인간 모험가가 이곳에서 여정을 시작해요.",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "얼라이언스는 2차 대전쟁 때 인간 왕국들, 드워프, 하이 엘프가 호드에 맞서 손잡으며 탄생했어요.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Shift+B, 가방별 단축키, 상인이 Alfa 창을 엽니다. 끄면 게임 가방으로 돌아갑니다.",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "희망의 빛 예배당은 전설적인 전투에서 스컬지를 버텨 냈어요. 지금은 은빛 여명회의 큰 피난처예요.",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "빛의 대성당은 스톰윈드 신앙의 중심이에요. 사제들이 얼라이언스 모두를 돌봐요.",
	["La Cresta de la Llama es el puesto de la Horda en las estepas, en lo alto de las rocas."] = "화염 마루는 평원 바위 높은 곳에 있는 호드 전초기지예요.",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "붉은십자군은 역병 이후 로데론의 슬픔에서 태어났지만, 증오 때문에 맞서 싸우는 상대만큼 잔인해졌어요.",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "붉은십자군의 수도원이 여기 있어요. 그들에게 언데드는 모두 불타야 해요. 포세이큰도요.",
	["La Cuenca de Arathi, el campo de batalla, está en estas tierras: se pelea por la granja, la mina, el aserradero, los establos y la herrería."] = "이 땅에 전장 아라시 분지가 있어요. 농장, 광산, 제재소, 마구간, 대장간을 두고 싸워요.",
	["La Feria de la Luna Negra tiene su propia reputación, y se sube con sus vales y sus encargos."] = "다크문 축제에는 따로 평판이 있고, 교환권과 심부름으로 올려요.",
	["La Fortaleza de Grommash, en Orgrimmar, lleva el nombre de Grom Grito Infernal, el héroe que liberó a los orcos de la sangre demoníaca."] = "오그리마의 그롬마쉬 요새는 오크를 악마의 피에서 해방한 영웅 그롬 헬스크림의 이름을 땄어요.",
	["La Fuente del Sol, el corazón de Quel'Thalas, nació de un frasco de agua del Pozo de la Eternidad que los altos elfos se llevaron."] = "쿠엘탈라스의 심장 태양샘은 하이 엘프가 가져간 영원의 샘 물 한 병에서 태어났어요.",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "이글거리는 협곡이 이렇게 된 건 검은무쇠 탓이에요. 마법사 군주 타우릿산이 라그나로스를 불러내 땅이 불타올랐어요.",
	["La Gran Forja nunca se apaga: es el corazón de Forjaz y el orgullo de tu gente."] = "대용광로는 절대 꺼지지 않아요. 아이언포지의 심장이자 당신 종족의 자랑이에요.",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "아이언포지 한가운데의 대용광로는 절대 꺼지지 않아요.",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "야경대는 다크샤이어의 민병대예요. 늑대, 언데드, 늑대인간으로부터 마을을 지켜요.",
	["La Guerra de los Ancestros fue la primera invasión de la Legión Ardiente a Azeroth, hace unos diez mil años."] = "고대의 전쟁은 약 만 년 전 불타는 군단의 첫 아제로스 침공이었어요.",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "토륨 대장조합은 부족을 떠난 검은무쇠 드워프들이에요. 뛰어난 대장장이로, 자신들을 존중하는 누구와도 거래해요.",
	["La Hermandad del Torio, en La Garganta de Fuego, enseña planos que muchos herreros sueñan."] = "이글거리는 협곡의 토륨 대장조합은 많은 대장장이가 꿈꾸는 도면을 가르쳐요.",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "1차 대전쟁 때 호드가 스톰윈드를 파괴했어요. 도시를 다시 지은 석공들은 대가를 받지 못했고, 그 분노에서 데피아즈단이 태어났어요.",
	["La Horda tiene su propio pueblo al norte del marjal, para vigilar Theramore de cerca."] = "호드는 테라모어를 가까이서 감시하려고 습지대 북쪽에 마을을 두고 있어요.",
	["La Horda tiene una aldea en la costa de Desolace, y la Alianza un campamento en las montañas del norte."] = "호드는 잊혀진 땅 해안에 마을을, 얼라이언스는 북쪽 산에 야영지를 두고 있어요.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "지도 위의 La Jauría",
	["La Jauría: estado"] = "La Jauría: 상태",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: 지도의 내 무리, 따라가기, 클랜 (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: 내 명령어",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "불타는 군단은 모든 창조물을 불태우려는 타락한 티탄 살게라스의 악마 군대예요.",
	["La Liga de Arathor y los Rapiñadores se pelean la Cuenca de Arathi; las Centinelas Ala de Plata y la Escolta Grito de Guerra, la Garganta Grito de Guerra."] = "아라소르 연맹과 포세이큰 파멸단은 아라시 분지를, 은빛날개 파수대와 전쟁노래 정찰대는 전쟁노래 협곡을 두고 싸워요.",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "아이언포지의 고고학자들인 탐험가 연맹은 드워프의 기원을 알려 줄 유적을 찾아 온 세상을 뒤져요.",
	["La Luz para los humanos y enanos, Elune para los elfos de la noche y las sombras para muchos Renegados: cada sacerdote sirve a algo distinto."] = "인간과 드워프에겐 빛, 나이트 엘프에겐 엘룬, 많은 포세이큰에겐 어둠. 사제마다 섬기는 게 달라요.",
	["La Mano de Plata la fundó el arzobispo Alonsus Faol, y Uther fue su primer paladín."] = "백은의 손은 대주교 알론서스 파올이 세웠고, 우서가 첫 성기사였어요.",
	["La Mano de Plata, la orden de paladines, la fundó el arzobispo Alonsus Faol, y Uther fue el primero de sus caballeros."] = "성기사 기사단 백은의 손은 대주교 알론서스 파올이 세웠고, 우서가 그 첫 기사였어요.",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "혈투의 전장은 대분리 이전 명가 엘프의 도시 엘드레탈라스였어요.",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "감시의 언덕의 민병대는 스톰윈드가 병사를 보내지 않자 농부들이 직접 만들었어요.",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "검은바위 산은 이 협곡과 불타는 평원 사이에 솟아 있어요. 안에는 검은무쇠 드워프, 라그나로스, 검은용들이 살아요.",
	["La Muralla de Thoradin separa Arathi de las Laderas de Trabalomas; lleva el nombre del rey que unió a los humanos."] = "소라딘의 성벽은 아라시 고원과 힐스브래드 구릉지를 갈라요. 인간을 하나로 모은 왕의 이름을 땄어요.",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "아제로스의 수호자를 뽑던 비밀 마법사 집단 티리스팔의 결사단은 이 숲에서 이름을 땄어요. 메디브가 마지막 수호자였어요.",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "스컬지는 리치 왕의 언데드 군대예요. 켈투자드가 감염된 곡식으로 로데론 전역에 퍼뜨렸어요.",
	["La Polimorfia convierte al enemigo en oveja. Yo me portaría muy bien con esa oveja, palabra de loba."] = "변이는 적을 양으로 바꿔요. 저는 그 양한테 아주 얌전하게 굴 거예요. 늑대의 맹세예요.",
	["La Segadora de arcanita es una de las armas más famosas que puede forjar un herrero."] = "아케이나이트 수확낫은 대장장이가 만들 수 있는 가장 유명한 무기 중 하나예요.",
	["La Sima Ígnea está bajo Orgrimmar: ahí se esconden brujos de un culto junto con troggs."] = "성난불길 협곡은 오그리마 아래에 있어요. 교단의 흑마법사들이 트로그와 함께 숨어 있어요.",
	["La Sociedad Real de Boticarios trabaja en Entrañas en una plaga nueva. Mejor no preguntes para quién."] = "왕실 약제사 협회는 언더시티에서 새 역병을 만들고 있어요. 누구를 위한 건지는 묻지 않는 게 좋아요.",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "왕실 약제사 협회는 몰래 새 역병을 만들고 있어요... 인간만 노리는 것도 아니에요.",
	["La Tercera Guerra empezó con la plaga del grano en Lordaeron y terminó en Hyjal con la caída de Archimonde."] = "3차 대전쟁은 로데론의 곡식 역병으로 시작해 하이잘에서 아키몬드의 몰락으로 끝났어요.",
	["La Torre de Azora, en el este de Elwynn, es la casa de Theocritus, un mago al servicio del reino."] = "엘윈 숲 동쪽의 아조라의 탑은 왕국을 위해 일하는 마법사 테오크리투스의 집이에요.",
	["La aldea Sen'jin, en la costa de Durotar, lleva el nombre del líder que dio su vida por su pueblo."] = "듀로타 해안의 센진 마을은 백성을 위해 목숨을 바친 지도자의 이름을 땄어요.",
	["La ayuda de rotación está apagada"] = "로테이션 도우미가 꺼져 있음",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "지역 이름과 시간 바가 스타일의 색상과 글꼴을 따릅니다. 추적, 달력, 우편 버튼은 그대로입니다.",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "행동 단축바, 추가 바, 경험치 바, 메뉴, 가방이 고른 스타일을 따릅니다. 전투 중이 아닐 때 모양만 바뀌며, 끄면 게임 기본으로 돌아갑니다.",
	["La barra de pesca"] = "낚시 바",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "생명력 바를 각자의 직업 색상으로 표시합니다. 끄면 초록색 바에 이름이 직업 색상으로 나옵니다.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "기본 제공 데이터베이스에는 %s곳이 있습니다(%d개 지역). 내가 찾은 곳: %s.",
	["La bienvenida con las novedades de esta versión."] = "이번 버전의 새 기능을 담은 환영 화면.",
	["La bienvenida ocupa toda la pantalla, con el juego oscurecido detrás."] = "환영 설정이 화면 전체를 차지하고 뒤의 게임은 어둡게 표시됩니다.",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "기본 낚싯대는 낚시 전문가와 낚시용품 상인이 팝니다.",
	["La búsqueda de lugares cercanos no está disponible."] = "주변 장소 검색을 사용할 수 없습니다.",
	["La cadena de los Defias te lleva de Villadorada a los Páramos de Poniente y termina en las Minas de la Muerte, frente a VanCleef."] = "데피아즈 연계 퀘스트는 골드샤이어에서 서부 몰락지대로 이어져 죽음의 폐광에서 밴클리프와 마주하며 끝나요.",
	["La cadena no trae talentos válidos."] = "문자열에 올바른 특성이 없습니다.",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "입력창이 스타일을 따르고, 입력하는 동안 강조 색 테두리가 생깁니다. WoW 클래식 스타일에서는 게임 기본 입력창이 남습니다.",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "Alfa 밖(게임 메뉴나 콘솔)에서 바꿨습니다.",
	["La capa de escamas de Onyxia protege del aliento de Nefarian, y en su banda la piden todos."] = "오닉시아 비늘 망토는 네파리안의 숨결을 막아 줘서, 그 공격대에서는 모두에게 필요해요.",
	["La cerveza es casi sagrada para tu gente: en Kharanos está la destilería Cebatruenos."] = "맥주는 당신 종족에게 거의 신성해요. 카라노스에 썬더브루 양조장이 있어요.",
	["La cola está vacía."] = "대기열이 비어 있습니다.",
	["La cura de ese clic pasa al botón central."] = "그 클릭의 치유 주문은 가운데 버튼으로 옮겨집니다.",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "카메라와 캐릭터 사이의 나무나 기둥마다 카메라가 앞으로 튀지 않습니다.",
	["La cámara se mece un poco con tus pasos."] = "걸음에 맞춰 카메라가 살짝 흔들립니다.",
	["La cámara se queda sobre el agua en lugar de meterse."] = "카메라가 물속으로 들어가지 않고 물 위에 머뭅니다.",
	["La cámara te sigue"] = "카메라가 따라옴",
	["La de ahora pasa a tus sesiones anteriores."] = "지금 세션은 지난 세션으로 넘어갑니다.",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "지금 세션은 지난 세션으로 넘어갑니다. 도감과 업적은 그대로입니다.",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "레벨업 중에는 직업 우선순위. 특성을 찍으면 자동으로 바뀝니다.",
	["La derecha"] = "오른쪽",
	["La dirección del texto sobre tu personaje."] = "캐릭터 위 글자의 방향.",
	["La empieza un objeto"] = "아이템으로 시작",
	["La enciclopedia de La Jauría"] = "La Jauría 백과사전",
	["La enciclopedia no puede abrir todavía"] = "백과사전을 아직 열 수 없음",
	["La entrada de %s"] = "입구: %s",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "각 던전 입구를 미니맵에 표시하며, 이미 완료한 곳은 초록색입니다. 세계 지도에는 이미 «던전 입구»로 표시됩니다.",
	["La familia Barov le entregó su castillo de Caer Darrow al Culto a cambio de vida eterna. Así nació Scholomance, y así les fue."] = "바로브 가문은 영원한 생명을 대가로 카엘 다로우 성을 교단에 넘겼어요. 그렇게 스칼로맨스가 생겼고, 결말은 보시는 대로예요.",
	["La flecha no está disponible ahora."] = "지금은 화살표를 쓸 수 없습니다.",
	["La flecha que te guía"] = "안내 화살표",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "화살표가 그 사람의 흔적을 따라 움직이고 도착하면 멈춥니다.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "화살표가 Alfa 보행 지도로 절벽, 물, 벽을 돌아 지면의 길을 따라갑니다. 끄면 각 지점을 곧장 가리킵니다.",
	["La flecha sigue en el paso de ahora."] = "화살표는 현재 단계에 남아 있습니다.",
	["La flecha te lleva a %s."] = "화살표가 %s(으)로 안내합니다.",
	["La flecha te lleva a su entrada."] = "화살표가 입구로 안내합니다.",
	["La flecha te lleva aquí."] = "화살표가 이곳으로 안내합니다.",
	["La flecha te lleva de un lugar al siguiente."] = "화살표가 한 곳에서 다음 곳으로 안내합니다.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "화살표의 목적지가 바뀌어 %s 님 따라가기를 멈췄습니다.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "화살표는 유리할 때 비행과 귀환석을 씁니다.",
	["La flecha y el camino"] = "화살표와 경로",
	["La flecha ya no sigue tu ruta de farmeo."] = "화살표가 더 이상 파밍 경로를 따라가지 않습니다.",
	["La fuerza se cambia en la ventana, en Filtros."] = "강도는 창의 필터에서 바꿉니다.",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "오닉시아의 둥지는 이 습지대에 있어요. 데스윙의 딸 오닉시아는 스톰윈드에서 인간 귀족 행세를 해요.",
	["La guía en el minimapa"] = "미니맵 가이드",
	["La guía que mejor te queda por tu nivel y donde estás."] = "내 레벨과 위치에 가장 잘 맞는 가이드.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "따라가는 가이드, 현재 단계, 가이드의 모든 것을 클릭 한 번으로.",
	["La guía te lleva a entrenar en %d pasos."] = "가이드가 %d단계에 걸쳐 수련하러 안내합니다.",
	["La guía te lleva a quien recibe cada una."] = "가이드가 각 퀘스트를 제출할 NPC에게 안내합니다.",
	["La haces de paso: abre %s."] = "가는 길에 하면 %s 열림.",
	["La haré"] = "할게요",
	["La historia"] = "이야기",
	["La historia se guarda cuando el juego te muestra la misión."] = "게임이 퀘스트를 보여 줄 때 이야기가 저장됩니다.",
	["La lengua de la Alianza es el común y la de la Horda, el orco. Por eso lo que le dices al otro bando le llega como palabras raras."] = "얼라이언스는 공용어를, 호드는 오크어를 써요. 그래서 상대 진영에게 한 말은 알아들을 수 없는 말로 전해져요.",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "스킨 글꼴(Alfa 스킨은 Inter, 후광은 Fira Sans, 나머지는 게임 글꼴) 또는 원하는 글꼴을 선택합니다.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "목록이 꺼져 있습니다. 편의 기능에서 \"내 소리 목록\"을 켜세요(/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "레벨별 목록과 내 진행도.",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "추적기 상단의 돋보기가 메뉴를 엽니다. /alfa cerca나 단축키로도 됩니다.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Blizzard 타임라인은 어떤 공격이 언제 오는지, 큰 메시지는 무엇이 위험한지 알려 줍니다. Alfa는 경고를 지어내지 않습니다. 설정에서 켜고 조정하세요.",
	["La línea de tu personaje ya no se corta: si no cabe, quita partes y nunca tu nombre ni tu nivel."] = "캐릭터 줄이 더 이상 잘리지 않습니다. 자리가 부족하면 일부를 빼되 이름과 레벨은 절대 빼지 않습니다.",
	["La línea del camino también en el minimapa."] = "경로 선을 미니맵에도 표시합니다.",
	["La manada a la vista"] = "보이는 무리",
	["La manada aúlla contigo."] = "무리가 함께 울부짖습니다.",
	["La manada crece"] = "무리가 커져요",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "늑대 하나하나가 강하기에 무리가 강해요. 그리고 당신도 강해요.",
	["La manada no te ve en el mapa"] = "무리가 지도에서 나를 볼 수 없음",
	["La manada no ve a tu personaje en el mapa."] = "무리가 지도에서 내 캐릭터를 볼 수 없습니다.",
	["La manada te ve en el mapa"] = "무리가 지도에서 나를 볼 수 있음",
	["La manada te ve en el mapa: %s"] = "무리가 지도에서 나를 봅니다: %s",
	["La manada ya no ve a tu personaje en el mapa."] = "이제 무리가 지도에서 내 캐릭터를 볼 수 없습니다.",
	["La manada ya ve a tu personaje en el mapa del juego."] = "이제 무리가 게임 지도에서 내 캐릭터를 봅니다.",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "이제 무리가 게임 지도에서 내 캐릭터를 봅니다. /alfa manada에서 언제든 바꿀 수 있습니다.",
	["La mazmorra"] = "던전",
	["La mazmorra para mi nivel"] = "내 레벨에 맞는 던전",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "내 레벨에 맞는 던전과 우두머리, 전리품, 퀘스트, 공략.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "내 레벨에 맞는 던전, 퀘스트, 가는 방법.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "내 레벨에 맞는 던전, 이름을 붙이면 그 던전 (그 외: progreso, ajustes)",
	["La mezcla de texturas del terreno."] = "지형 텍스처의 섞임.",
	["La misión"] = "퀘스트",
	["La montura"] = "탈것",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "골짜기, 늪, 새벽의 짙은 안개.",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "게임이 그래픽을 다시 시작하는 동안 화면이 1~2초 까맣게 됩니다. 게임에서 나가지도, 아무것도 잃지도 않습니다.",
	["La pesca de Alfa está apagada"] = "Alfa 낚시가 꺼져 있습니다",
	["La pesca se rehízo: una sola tecla para equiparte, lanzar y recoger, con diario, logros y una guía de 1 a 300."] = "낚시를 새로 만들었습니다. 키 하나로 장비 착용, 던지기, 낚아 올리기를 하고, 도감, 업적, 1~300 가이드도 있습니다.",
	["La piel verde de los orcos es una huella de la magia vil que usaron sus brujos en Draenor."] = "오크의 초록 피부는 드레노어에서 흑마법사들이 쓴 지옥 마법의 흔적이에요.",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "적중이 가장 중요합니다. 쌍수 무기는 적중이 없으면 자주 빗나갑니다.",
	["La primera vez: %s%s."] = "처음: %s%s.",
	["La princesa Moira, hija de Magni Barbabronce, vive en las Profundidades de Roca Negra como esposa del emperador Thaurissan."] = "마그니 브론즈비어드의 딸 모이라 공주는 황제 타우릿산의 아내로 검은바위 나락에 살아요.",
	["La profesión"] = "전문 기술",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "가방 페이지. «abrir»는 가방을, «banco»는 은행을 엽니다",
	["La que te toca, con sus misiones y su botín."] = "나에게 맞는 던전, 퀘스트와 전리품까지.",
	["La recoges ahora"] = "지금 받기",
	["La recomendada para ti y todas las demás"] = "나에게 추천하는 것과 나머지 모두",
	["La recomendada para ti y todas las demás."] = "나에게 추천하는 것과 나머지 모두.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "내 레벨에서 시작하는 가장 빠른 경로, 퀘스트 하나하나.",
	["La ruta no trae tramos."] = "경로에 구간이 없습니다.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "경로가 %s(으)로 안내합니다. 화살표가 꺼져 있습니다. 보려면 설정 > 가이드에서 켜세요.",
	["La ruta ya no se salta para siempre una misión que todavía no puede revisar."] = "경로가 아직 확인할 수 없는 퀘스트를 영원히 건너뛰지 않습니다.",
	["La sabes"] = "배움",
	["La sacas de tu plan."] = "계획에서 뺍니다.",
	["La sastrería usa la tela que sueltan los humanoides: lino, lana, seda, tejido mágico y tela rúnica."] = "재봉술은 인간형 몹이 떨어뜨리는 천을 써요: 리넨, 양모, 비단, 마법 옷감, 룬무늬 옷감.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "다음 칸은 %s이며 아직 돈이 부족합니다.",
	["La siguiente casilla cuesta %s: cómprala con el botón del banco del juego, que ya está a la vista."] = "다음 칸은 %s입니다: 화면에 보이는 게임의 은행 버튼으로 구입하세요.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "경매장 전체 스캔은 15분마다 할 수 있습니다. 남은 시간: %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "경매장이 스캔을 받아들이지 않았습니다. 나중에 다시 시도하세요.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "경매장에서 경매 목록을 보내지 않았습니다. 나중에 다시 시도하세요.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "경매장이 응답하지 않았습니다. 아직 대기 시간일 수 있으니 몇 분 뒤에 다시 시도하세요.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Alfa가 저장한 캐릭터별 골드의 합계입니다(현재 캐릭터는 최신 값).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "그 기술이 있는 단축바 버튼의 단축키를 아이콘 위에 표시합니다.",
	["La tecla del mapa abre este mapa"] = "지도 키로 이 지도 열기",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "게임 지도를 여는 키(M)로 Alfa 지도가 열리고, 그 안의 버튼으로 게임 지도로 갈 수 있습니다. 끄면 키가 다시 게임 지도를 엽니다. 설정 > 단축키 설정 > Alfa에서 따로 키를 지정할 수도 있습니다.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "다른 낚시 애드온에서 쓰던 단축키(%s)로 이제 Alfa 낚시를 합니다.",
	["La tela rúnica sale de humanoides de nivel 50 o más: los trols de las Tierras del Interior o los sátiros de Frondavil son buena opción."] = "룬무늬 옷감은 50레벨 이상 인간형 몹에게서 나와요. 동부 내륙지 트롤이나 악령의 숲 사티로스가 좋아요.",
	["La tela vil sale de sátiros y demonios de Frondavil y Azshara."] = "악마 옷감은 악령의 숲과 아즈샤라의 사티로스와 악마에게서 나와요.",
	["La tomo otra vez"] = "다시 받을게요",
	["La tribu Zandalar se considera la primera de todos los trols. Sus sacerdotes acampan en la Isla de Yojamba para frenar a Hakkar."] = "잔달라 부족은 자신들이 모든 트롤 중 첫째라고 여겨요. 그 사제들이 학카르를 막으려고 요잠바 섬에 진을 치고 있어요.",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "벌목기가 사람들을 날려 버립니다. 빨리 다시 어그로를 잡으세요.",
	["La tuya tiene %d semanas: salen seguido."] = "내 버전은 %d주 전 것입니다. 업데이트가 자주 나옵니다.",
	["La venta se detuvo: vendiste %d de %d."] = "판매 중지: %d/%d개 판매함.",
	["La ventana"] = "창",
	["La ventana del Legado no abrió."] = "유산 창이 열리지 않았습니다.",
	["La última: %s."] = "마지막: %s.",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "실바나스 윈드러너는 포세이큰을 다스려요. 아서스에게 죽기 전에는 쿠엘탈라스의 순찰대장이었어요.",
	["Lady Vashj, que fue dama de compañía de Azshara, ahora guía a sus naga al servicio de Illidan."] = "한때 아즈샤라의 시녀였던 여군주 바쉬는 이제 나가를 이끌고 일리단을 섬겨요.",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "화염구와 주변 불길을 씁니다. 차단하고, 원거리라면 떨어지세요.",
	["Lanza bombas de humo que aturden: sal del humo."] = "기절시키는 연막탄을 던집니다. 연기에서 벗어나세요.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "주변 모두를 넘어뜨리는 덩굴을 씁니다. 원거리라면 멀리 있으세요.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "주변에 불길을 뿜습니다. 원거리라면 떨어져 있으세요.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "대지 주문을 쓰고 토템을 세웁니다. 토템부터 부수세요.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "녹은 금속을 던집니다. 방어 전담이 아니라면 바로 옆에 붙어 있지 마세요.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "번개를 쓰고 자신을 치유할 수 있습니다. 주문을 차단하세요.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "비전 폭발을 씁니다. 차단하세요.",
	["Lanza sombras: interrúmpelo."] = "암흑 주문을 씁니다. 차단하세요.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "거미줄과 저주를 씁니다. 가능하면 저주를 해제하세요.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "방 안을 돌아다니는 모래 폭풍을 만듭니다. 그 안에 서 있지 마세요.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "멀리서 가장 강한 주문을 쓰고 즉시 시전 주문으로 마무리하세요.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "가장 강한 주문을 먼저 쓰고 충격 주문으로 마무리하세요.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "앞쪽으로 독구름을 뿜습니다. 파티 반대쪽으로 돌려세우세요.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "플레이어 한 명을 제자리에 묶는 그물을 던집니다. 큰일 아니니 계속 공격하세요.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "모두에게 독을 겁니다. 가능하면 독을 해제하세요.",
	["Lanzado"] = "던짐",
	["Lanzamientos"] = "던진 수",
	["Lanzamientos: %d de %d"] = "던진 수: %d / %d",
	["Las Cavernas del Tiempo guardan los momentos más importantes de la historia, y el Vuelo Bronce no deja que nadie los cambie."] = "시간의 동굴은 역사에서 가장 중요한 순간들을 지키고, 청동용군단은 누구도 그걸 바꾸지 못하게 해요.",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "불타는 평원은 라그나로스가 깨어날 때 불타올랐고, 그 불씨는 아직도 꺼지지 않았어요.",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "메아리 섬은 검은창 부족의 고향이었어요. 그런데 부두술사 잘라잔이 부두 마법으로 많은 이를 지배했고, 나머지는 본토로 옮겨 가야 했어요.",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "죽음의 폐광에는 밴클리프의 은신처가... 해적선까지 숨어 있어요.",
	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "붉은마루 산맥은 붉은빛 바위 때문에 그런 이름이 붙었어요.",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "검은바위 나락은 산 아래 통째로 있는 드워프 도시, 검은무쇠의 수도예요.",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "멀고어의 붉은 바위는 신성한 곳이에요. 타우렌의 조상들이 그곳에 잠들어 있어요.",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "붉은 바위는 멀고어에서 가장 신성한 곳이에요. 당신 종족의 조상들이 그곳에 잠들어 있어요.",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "20~35레벨 물. 전문 단계는 무법항 낚시꾼이 파는 책으로 배웁니다.",
	["Las barras de abajo"] = "아래쪽 바",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "상급 축복은 더 오래가고 파티의 한 직업 전체에 걸려요. 마나를 많이 아껴 줘요!",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "직접 만든 가방은 늘 팔려요. 누구나 공간이 더 필요하거든요.",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "폭탄과 수류탄은 던전과 상대 진영과의 싸움에서 목숨을 구해 줘요.",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "잠긴 상자는 도적이 열어요. 대화창에서 부탁하면 가끔 공짜로 해 주기도 해요.",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "다크문 카드는 온 세상의 적에게서 떨어져요. 한 벌을 다 모으면 축제에서 강력한 장신구로 바꿔요.",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "무법항, 가젯잔, 눈망루 마을의 중립 경매장은 수수료가 더 비싸지만 상대 진영과 거래할 수 있어요.",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "잿빛 골짜기의 파수병들은 전쟁노래 오크 벌목꾼들과 쉬지 않고 싸워요.",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "파수병들은 여명의 설원에서 서리표범을 길들이고, 존경을 얻은 사람에게만 맡겨요.",
	["Las criaturas que invocan los enemigos por un rato."] = "적이 잠시 소환하는 생물.",
	["Las cuentas"] = "계산",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "체험판 계정은 공유할 수 없습니다. 게임이 허용하지 않습니다.",
	["Las demás"] = "나머지",
	["Las demás ranuras"] = "나머지 칸",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "둘 다 사냥하고 이동하는 동안 저절로 오르고, 모은 것은 잘 팔립니다. 탈것과 기술에 쓸 골드가 됩니다.",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "드라이어드는 세나리우스의 딸들이고, 숲의 수호자는 아들들이에요.",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "사진처럼 화면 모서리가 서서히 어두워집니다.",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "드워프의 발굴이 트로그를 깨웠고, 이제 텔사마는 그들을 조심해야 해요.",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "악령의 숲의 타락한 노래꽃은 정화할 수 있어요. 그러면 한동안 이어지는 축복을 받아요.",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "기계공학 고글은 기계공학자만 쓸 수 있어요. 자랑스럽게 쓰세요!",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "높은 레벨 약초는 경매장에서 아주 잘 팔려요.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "알리기가 파티나 공격대 대화창에 쓰는 줄입니다.",
	["Las marca con una flecha."] = "화살표로 표시합니다.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "무리 표시를 세계 지도뿐 아니라 미니맵에도 표시합니다.",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "주문과 범위의 바닥 표시. 끄면 전투 경고가 가려지니 켜 두는 편이 좋습니다.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "근처에서 지금 받을 수 있는 최고의 퀘스트를 가장 짧은 순서로.",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "썬더 블러프의 고원들은 다리로 이어져 있고, 도시에는 승강기를 타고 올라가요.",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "목표는 하면 자동으로 달성되고, 메모는 직접 표시합니다. 원하는 순서로 정렬하세요.",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "타렌 밀농장 퀘스트는 호드를 구릉지의 인간 농장으로 보내요.",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "회색 퀘스트는 경험치가 적어요. 제출하고 다음으로 가요.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "받기 위해 필요한 선행 퀘스트와 레벨.",
	["Las misiones que más experiencia dan cerca de ti."] = "내 주변에서 경험치를 가장 많이 주는 퀘스트입니다.",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "천 납품 같은 반복 평판 퀘스트도 파밍의 한 방법이에요.",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "노움의 탈것은 직접 발명한 기계 새, 기계타조예요.",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "같은 진영 다른 종족의 탈것은 그 도시의 평판이 필요할 수 있습니다. 내 종족의 탈것은 언제나 살 수 있습니다.",
	["Las monturas de tu raza"] = "내 종족의 탈것",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "클래식의 에픽 탈것은 골드가 꽤 들어요. 조금씩 모으는 것도 모험의 일부예요.",
	["Las ondas al caminar o nadar en el agua."] = "물에서 걷거나 헤엄칠 때 생기는 물결.",
	["Las orillas de la pantalla un poco más oscuras."] = "화면 가장자리를 조금 더 어둡게.",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "탭이 스타일의 글꼴과 색상을 따르고, 선택한 탭에는 강조 색 줄이 생깁니다. WoW 클래식 스타일에서는 게임 기본 탭이 남습니다.",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "직접 만든 숫돌과 무게추는 전사와 도적에게 쓸모 있어서 늘 살 사람이 있어요.",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "만들어 낸 생명석이 파티 모두의 목숨을 구해요.",
	["Las placas de nombre de los enemigos."] = "적 이름표.",
	["Las plantas de herboristería."] = "약초채집 식물입니다.",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "생명력과 마나 물약은 늘 팔려요. 모든 던전에 필요하거든요.",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "인간의 북녘골 첫 퀘스트는 코볼트, 데피아즈 도적... 그리고 늑대 이야기예요. 우리가 다 착한 건 아니라고요?",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "제작 전문 기술은 150, 225, 300에 유산 도전을 줘요.",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "채집 전문 기술은 1레벨부터 골드를 벌어 줘요. 약초 채집이나 채광!",
	["Las que me faltan"] = "없는 것",
	["Las que se hacen una sola vez."] = "한 번만 하는 퀘스트입니다.",
	["Las que se repiten cada día."] = "매일 반복되는 퀘스트입니다.",
	["Las que se repiten cada semana."] = "매주 반복되는 퀘스트입니다.",
	["Las que tengo"] = "있는 것",
	["Las que vienen después, más pequeñas a la derecha."] = "다음 기술은 오른쪽에 더 작게 표시됩니다.",
	["Las que ya hiciste no cuentan."] = "이미 한 퀘스트는 계산하지 않습니다.",
	["Las recetas se compran a vendedores de comida y algunas caen de enemigos."] = "요리법은 음식 상인에게서 사고, 일부는 적에게서 떨어져요.",
	["Las ruinas de Eldarath fueron una ciudad élfica; hoy están llenas de naga."] = "엘다라스 폐허는 한때 엘프 도시였어요. 지금은 나가로 가득해요.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "Alfa의 경로 페이지에서 만든 경로와 계획.",
	["Las sacerdotisas de Elune guían a tu pueblo, y Tyrande lo gobierna desde el Templo de la Luna."] = "엘룬의 여사제들이 당신 종족을 이끌고, 티란데가 달의 신전에서 다스려요.",
	["Las sesiones guardadas de este personaje."] = "이 캐릭터의 저장된 세션입니다.",
	["Las sesiones, las zonas y los objetos de este personaje."] = "이 캐릭터의 세션, 지역, 아이템.",
	["Las vendas suben de lino a lana, seda, tejido mágico y tela rúnica."] = "붕대는 리넨에서 양모, 비단, 마법 옷감, 룬무늬 옷감으로 올라가요.",
	["Las ventanas de chat, sus pestañas y la caja para escribir toman el estilo que elijas abajo y cambian con él. Al apagarlo vuelve el chat de siempre, sin /reload."] = "대화창, 탭, 입력창이 아래에서 고른 스타일을 따르고 함께 바뀝니다. 끄면 /reload 없이 원래 대화창으로 돌아갑니다.",
	["Lavanda"] = "라벤더색",
	["Lectura del agua"] = "물 읽기",
	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "경매장 전체에서 아이템별 최저가를 읽습니다. 아무것도 사거나 등록하지 않습니다. 15분마다 쓸 수 있습니다.",
	["Lee los objetivos de la misión antes de salir: te ahorras vueltas."] = "나가기 전에 퀘스트 목표를 읽어요. 헛걸음을 줄여 줘요.",
	["Leeroy Jenkins se hizo famoso por lanzarse solo, gritando su nombre, a una sala llena de dragoncitos en la Cumbre de Roca Negra."] = "리로이 젠킨스는 자기 이름을 외치며 검은바위 첨탑의 새끼용 가득한 방에 혼자 뛰어든 걸로 유명해졌어요.",
	["Legado"] = "유산",
	["Legendario"] = "전설",
	["Lejos de aquí"] = "멀리 있음",
	["Lejos de aquí: %s"] = "멀리 있음: %s",
	["Letra del estilo"] = "스타일 글꼴",
	["Letras grandes en el centro de la pantalla cuando el jefe hace algo importante."] = "우두머리가 중요한 행동을 할 때 화면 가운데에 큰 글씨로 알려 줍니다.",
	["Leyenda"] = "전설",
	["Leyendo precios... %d%%"] = "가격 읽는 중... %d%%",
	["Leyendo tus bolsas…"] = "가방을 읽는 중…",
	["Libera tu sello en el enemigo: daño extra."] = "문장을 적에게 풀어 추가 피해를 줍니다.",
	["Liberar misiones"] = "퀘스트 정리",
	["Liberar tu espíritu en campos de batalla"] = "전장에서 영혼 해방",
	["Libre: %d de %d"] = "빈 칸: %d/%d",
	["Libro"] = "책",
	["Ligado: no se subasta"] = "귀속: 경매 불가",
	["Limpien a sus ayudantes antes de empezar con él."] = "우두머리와 싸우기 전에 도우미부터 정리하세요.",
	["Lista"] = "준비됨",
	["Lista de pasos"] = "단계 목록",
	["Lista para entrar"] = "입장 준비 완료",
	["Lista para entregar"] = "제출 가능",
	["Listas"] = "준비됨",
	["Listas para entregar"] = "제출 가능",
	["Listo"] = "완료",
	["Listo para ayudar a tu grupo"] = "파티를 도울 준비 완료",
	["Listo para curar"] = "치유 준비 완료",
	["Listo para pescar"] = "낚시 준비 완료",
	["Listo, fijarlos"] = "완료, 고정",
	["Listo: aprendiste %d rangos de talento"] = "완료: 특성 %d단계를 배웠습니다",
	["Listo: aprendiste 1 rango de talento"] = "완료: 특성 1단계를 배웠습니다",
	["Listo: te abrimos un susurro para %s. Revisa el mensaje y pulsa Intro."] = "완료: %s 님에게 귓속말을 열었습니다. 메시지를 확인하고 Enter를 누르세요.",
	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "완료: 내 클릭 설정이 블리자드 프레임에서도 작동합니다.",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "시작할 때 늑대 여러 마리를 부릅니다. 광역 공격을 쓰거나 늑대부터 처치하세요.",
	["Llave"] = "열쇠",
	["Llavero"] = "열쇠고리",
	["Llaves"] = "열쇠",
	["Llega Lya, una loba compañera que guarda la historia de cada misión y te cuenta datos de cada zona."] = "Lya를 만나 보세요. 퀘스트마다 이야기를 간직하고 지역마다 흥미로운 사실을 들려주는 동료 암컷 늑대입니다.",
	["Llega a 150 de habilidad."] = "숙련도 150에 도달하세요.",
	["Llega a 225 de habilidad."] = "숙련도 225에 도달하세요.",
	["Llega a 75 de habilidad."] = "숙련도 75에 도달하세요.",
	["Llega a la habilidad máxima de pesca."] = "낚시 숙련도 최대치에 도달하세요.",
	["Llega a la maestría Diestro con una captura."] = "한 어종으로 능숙 단계에 도달하세요.",
	["Llega a nivel %d"] = "%d레벨 달성",
	["Llega a nivel 25 con cualquier clase"] = "아무 직업으로 25레벨 달성",
	["Llega al nivel 40 (te faltan %d)"] = "40레벨 달성 (남은 레벨: %d)",
	["Llega con %d puntos del legado ganados en tu cuenta."] = "계정에서 얻은 유산 점수 달성: %d점.",
	["Llega con ayudantes naga: mátenlos primero."] = "나가 도우미와 함께 옵니다. 나가부터 처치하세요.",
	["Llega con guardias: tírenlos aparte si pueden."] = "경비병과 함께 옵니다. 가능하면 경비병을 따로 끌어내세요.",
	["Llega con lobos: elimínenlos primero."] = "늑대와 함께 옵니다. 늑대부터 처치하세요.",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "개를 데리고 옵니다. 한 명씩 하나를 맡거나, 개부터 처치하세요.",
	["Llega en el nivel %d"] = "%d레벨에 배움",
	["Llegar a nivel %d"] = "%d레벨 달성",
	["Llegar a un nivel"] = "레벨 달성",
	["Llegas al rival con ira para pegar de inmediato."] = "분노를 가진 채 상대에게 도달해 바로 때릴 수 있습니다.",
	["Llegaste al final; quedaron %d pasos sin hacer."] = "끝에 도착했습니다. 하지 않은 단계 %d개가 남았습니다.",
	["Llegaste con %s."] = "%s 님에게 도착했습니다.",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "카메라 거리(설정 > 조작의 그 설정)를 최대로 늘립니다. 끄면 원래 쓰던 거리로 돌아갑니다.",
	["Lleva siempre un sello puesto aunque estés curando."] = "치유 중에도 항상 문장을 켜 두세요.",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "항상 붕대와 음식을 챙기세요. 조금 쉬더라도 안전한 편이 죽는 것보다 빠릅니다.",
	["Llevarla a Mis planes"] = "내 계획으로 보내기",
	["Llevas %d de %d pasos. El rastreador te dice el siguiente y la flecha te lleva."] = "%d/%d단계 진행. 추적기가 다음 단계를 알려 주고 화살표가 안내합니다.",
	["Llevas %s ahora. Solo oro entero (10 = 10 de oro)."] = "지금 가진 골드: %s. 골드 단위로만(10 = 10골드).",
	["Llevas %s jugando. Estírate, toma agua y regresas con más fuerza."] = "%s째 플레이 중이에요. 기지개를 켜고 물 한 잔 마신 뒤 더 힘차게 돌아와요.",
	["Llevas %s. La manada te espera aunque te tomes un respiro."] = "벌써 %s. 잠깐 쉬어도 무리는 기다려요.",
	["Llevas %s. Si cierras sesión en una posada, ganas XP descansada."] = "벌써 %s. 여관에서 접속을 종료하면 휴식 경험치가 쌓여요.",
	["Llorar"] = "울기",
	["Llámala antes de pelear."] = "전투 전에 소환수를 부르세요.",
	["Llévame"] = "길 안내",
	["Llévame a la entrada"] = "입구로 가기",
	["Llévame a la subasta"] = "경매장으로 가기",
	["Llévame a reparar"] = "수리하러 가기",
	["Llévame a un vendedor"] = "상인에게 가기",
	["Llévame al banco"] = "은행으로 가기",
	["Llévame al comerciante"] = "상인에게 가기",
	["Llévame al instructor"] = "전문가에게 가기",
	["Llévame con mi entrenador"] = "상급자에게 가기",
	["Lo acompañan otros lanzadores: interrúmpanlos."] = "다른 주문 시전자들이 함께 있습니다. 차단하세요.",
	["Lo agregué a tu plan."] = "계획에 추가했습니다.",
	["Lo alto de cada compañero."] = "파티원 칸의 높이입니다.",
	["Lo ancho de cada compañero."] = "파티원 칸의 너비입니다.",
	["Lo apagas o lo enciendes cuando quieras en Manada > La Jauría."] = "무리 > La Jauría에서 언제든 끄거나 켤 수 있습니다.",
	["Lo conozco de memoria"] = "눈 감고도 알아요",
	["Lo de %s y %s tiene su historia. ¿Te la platico?"] = "%s와(과) %s 일에는 사연이 있어요. 들려줄까요?",
	["Lo demás, de un vistazo"] = "나머지는 한눈에",
	["Lo enseña un instructor de la profesión"] = "전문 기술 상급자에게 배움",
	["Lo enseña un instructor en %s"] = "%s의 상급자에게 배움",
	["Lo esencial"] = "핵심만",
	["Lo estás siguiendo"] = "따라가는 중",
	["Lo estás siguiendo."] = "따라가는 중입니다.",
	["Lo gris véndelo a los vendedores, no en la subasta: nadie lo va a comprar ahí."] = "회색 아이템은 경매장 말고 상인에게 파세요. 경매장에선 아무도 안 사요.",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "회색 아이템과 잡동사니로 표시한 것. 남겨 두기로 표시한 것과 퀘스트에 필요한 것은 절대 팔지 않습니다.",
	["Lo justo para abrir la siguiente fila."] = "다음 줄을 여는 데 딱 필요한 만큼.",
	["Lo marca como tu objetivo"] = "대상으로 지정합니다",
	["Lo mejor de los dos lados. Si no sabes cuál elegir, elige este."] = "양쪽의 장점을 모았습니다. 무엇을 고를지 모르겠다면 이것을 고르세요.",
	["Lo mejor para ti"] = "나에게 가장 좋은 것",
	["Lo mejor para tu nivel"] = "내 레벨에 맞는 최고 장비",
	["Lo menos que espera Lya entre un consejo y otro. Lo importante no espera."] = "Lya가 조언 사이에 기다리는 최소 시간. 중요한 것은 기다리지 않습니다.",
	["Lo menos que espera Lya entre una historia y otra. Nunca en combate ni en mazmorras."] = "Lya가 이야기 사이에 기다리는 최소 시간. 전투 중이나 던전에서는 절대 하지 않습니다.",
	["Lo más cerca"] = "가장 가까움",
	["Lo más cerca de ti"] = "가장 가까운 곳",
	["Lo más ligero: para equipos modestos o para subir los FPS en peleas grandes."] = "가장 가벼움: 사양이 낮은 PC나 큰 전투에서 FPS를 올릴 때.",
	["Lo más parecido"] = "가장 비슷한 것",
	["Lo nuevo de esta versión"] = "이번 버전의 새로운 점",
	["Lo nuevo de esta versión, en pocas palabras."] = "이번 버전의 새 기능을 간단히 소개합니다.",
	["Lo nuevo en Alfa %s"] = "Alfa %s의 새 기능",
	["Lo nuevo en Alfa 1.0"] = "Alfa 1.0의 새 기능",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, chat y barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos."] = "게임을 더 편하게 하는 작은 기능: 퀘스트, 비행, 미니맵, Alfa 스타일의 대화창과 바, 프레임, 툴팁, 미리보기 창, 카메라, 소리.",
	["Lo pescado en esta sesión"] = "이번 세션에 낚은 것",
	["Lo piden estas misiones"] = "이 퀘스트들에 필요",
	["Lo pones al empezar a pelear."] = "전투를 시작할 때 사용합니다.",
	["Lo que Alfa acepta, rechaza o comparte sola. Mantén presionado Mayús para decidir tú en el momento."] = "Alfa가 자동으로 수락, 거절, 공유하는 것. Shift를 누르고 있으면 그때 직접 결정합니다.",
	["Lo que Lya sabe de aquí"] = "Lya가 아는 이곳",
	["Lo que buscas en la Enciclopedia"] = "백과사전에서 찾은 것",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "파티원이 Alfa로 공유한 것은 이름과 함께 내 마커에 들어오고, 따라갈 수 있게 알려 줍니다.",
	["Lo que conoce Alfa"] = "Alfa가 아는 것",
	["Lo que cuentan las misiones que vas tomando"] = "받은 퀘스트들이 들려주는 이야기",
	["Lo que da"] = "보상",
	["Lo que dice el diario de monturas"] = "탈것 도감 내용",
	["Lo que el menú del juego no enseña, a tu gusto"] = "게임 메뉴에 없는 설정을 내 취향대로",
	["Lo que encuentras en la manada"] = "무리에서 만날 수 있는 것",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "이 캐릭터의 던전 기록입니다. 우두머리를 처치하고 전리품을 주우면 자동으로 저장됩니다.",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "이 캐릭터로 마지막에 플레이했을 때 얻은 것입니다.",
	["Lo que gastan tus hechizos"] = "주문에 소모되는 것",
	["Lo que hay dentro"] = "안에 든 것",
	["Lo que llevas"] = "소지품",
	["Lo que llevas pescado: %s."] = "지금까지 낚은 것: %s.",
	["Lo que me sirve"] = "내가 쓸 수 있는 것",
	["Lo que menos vale: %s"] = "가장 싼 것: %s",
	["Lo que más conviene ahora"] = "지금 가장 좋은 것",
	["Lo que obtuviste en esta sesión"] = "이번 세션에 얻은 것",
	["Lo que pescaste"] = "낚은 것",
	["Lo que pide %s antes, en orden."] = "%s에 먼저 필요한 것, 순서대로.",
	["Lo que quieras contarle al desarrollador de Alfa."] = "Alfa 개발자에게 전하고 싶은 말.",
	["Lo que quieras; la marcas tú cuando la hagas."] = "무엇이든 좋습니다. 하고 나서 직접 표시하세요.",
	["Lo que sacas en %s: %s."] = "%s에서 낚이는 것: %s.",
	["Lo que se pesca aquí"] = "여기서 낚이는 것",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "경매장이 판매마다 가져가는 몫입니다. 보통 자기 진영 경매장은 5%, 중립 경매장은 15%입니다. 추정치입니다.",
	["Lo que sigue en tu build no está en tu árbol"] = "빌드의 다음 특성이 내 트리에 없음",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "다음 단계는 이 레벨이 필요합니다. 그때까지 가이드가 그곳으로 보내지 않습니다.",
	["Lo que sugiere Alfa"] = "Alfa 추천",
	["Lo que te ha contado"] = "들려준 이야기",
	["Lo que te pasa a ti: curación recibida, esquivas, recursos. Puede necesitar /reload la primera vez."] = "나에게 일어나는 일: 받은 치유, 회피, 자원. 처음에는 /reload가 필요할 수 있습니다.",
	["Lo que te piden"] = "부탁받은 일",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "내 빌드가 장비에서 필요로 하는 것과 얻는 곳.",
	["Lo que tu clase se pone antes de pelear está activo."] = "내 직업이 전투 전에 거는 버프가 활성화되어 있습니다.",
	["Lo que tu profesión de recolección junta mejor."] = "내 채집 전문 기술로 가장 잘 모으는 것.",
	["Lo que vale"] = "가치",
	["Lo que ya tienes en el banco"] = "이미 은행에 있는 것",
	["Lo recolectaste %d veces"] = "%d번 채집함",
	["Lo recolectaste 1 vez"] = "1번 채집함",
	["Lo revisa el desarrollador de Alfa. En ese canal nadie más ve tu mensaje. Si aún no estás en el Discord, entra con la invitación de arriba."] = "Alfa 개발자가 확인합니다. 그 채널에서는 다른 누구도 내 메시지를 볼 수 없습니다. 아직 Discord에 없다면 위의 초대로 들어오세요.",
	["Lo sigues"] = "따라가는 중",
	["Lo sigues: el rastreador te muestra la meta de ahora y la flecha va a cada lugar."] = "따라가는 중: 추적기가 현재 목표를 보여 주고 화살표가 각 장소로 안내합니다.",
	["Lo siguiente"] = "다음 할 일",
	["Lo siguiente para ti"] = "나를 위한 다음 할 일",
	["Lo sueltan"] = "떨어뜨리는 대상",
	["Lo último que consultaste"] = "최근에 찾아본 것",
	["Lobo"] = "늑대",
	["Lobos conectados"] = "접속 중인 늑대",
	["Logrado el %s"] = "달성: %s",
	["Logrados"] = "달성",
	["Logro de pesca: %s"] = "낚시 업적: %s",
	["Logros"] = "업적",
	["Logros de pesca"] = "낚시 업적",
	["Lord Kazzak, un demonio enorme, ronda las Tierras Devastadas; en el Clásico es un jefe de mundo para bandas."] = "거대한 악마 군주 카자크가 저주받은 땅을 돌아다녀요. 클래식에서는 공격대용 월드 우두머리예요.",
	["Lord Xavius, el consejero de Azshara, convenció a los Altonato de abrirle la puerta a Sargeras. Cuando murió, Sargeras lo trajo de vuelta como el primer sátiro."] = "아즈샤라의 조언자 군주 자비우스는 명가를 설득해 살게라스에게 길을 열게 했어요. 그가 죽자 살게라스가 그를 첫 사티로스로 되살렸어요.",
	["Los Altonato eran la nobleza élfica que vivía para la magia del Pozo. Su reina, Azshara, era tan bella que su pueblo la adoraba."] = "명가는 샘의 마법을 위해 살던 엘프 귀족이었어요. 여왕 아즈샤라는 너무 아름다워서 백성이 그녀를 숭배했어요.",
	["Los Amani pelearon contra los altos elfos durante miles de años. Su capital, Zul'Aman, está en los bosques cerca de Quel'Thalas."] = "아마니는 수천 년 동안 하이 엘프와 싸웠어요. 수도 줄아만은 쿠엘탈라스 근처 숲에 있어요.",
	["Los Barbabronce ganaron la Guerra de los Tres Martillos, y por eso Forjaz es suya."] = "청동수염 부족이 세 망치의 전쟁에서 이겼고, 그래서 아이언포지는 그들 것이에요.",
	["Los Claros de Tirisfal guardan las ruinas de Lordaeron, el reino de Arthas. Bajo su antigua capital, los Renegados levantaron Entrañas."] = "티리스팔 숲에는 아서스의 왕국 로데론의 폐허가 있어요. 옛 수도 아래에 포세이큰이 언더시티를 세웠어요.",
	["Los Defias usan cosechadores mecánicos que trabajan solos en los campos... y no les gustan las visitas."] = "데피아즈는 들판에서 혼자 일하는 기계 수확기를 써요... 손님은 싫어해요.",
	["Los Furiarena de Zul'Farrak son trols del desierto, primos lejanos de los Lanza Negra."] = "줄파락의 성난모래 부족은 사막 트롤로, 검은창 부족의 먼 친척이에요.",
	["Los Gurubashi llamaron a Hakkar, el Desollador de Almas. Cuando vieron lo que hacía, las demás tribus se unieron para echarlo."] = "구루바시는 영혼의 학살자 학카르를 불러냈어요. 그가 하는 짓을 본 다른 부족들이 힘을 합쳐 그를 쫓아냈어요.",
	["Los Hierro Negro invocaron a Ragnaros sin querer al final de la Guerra de los Tres Martillos, y desde entonces son sus esclavos."] = "검은무쇠 드워프는 세 망치의 전쟁 끝에 실수로 라그나로스를 불러냈고, 그 뒤로 그의 노예가 되었어요.",
	["Los Hierro Negro también excavan en Uldaman, buscando lo mismo que los enanos de Forjaz."] = "검은무쇠 드워프도 울다만을 파요. 아이언포지 드워프와 같은 걸 찾고 있어요.",
	["Los Lanza Negra suelen terminar sus frases con un «mon». ¡Se pega, mon!"] = "검은창 트롤은 말끝에 «몬»을 자주 붙여요. 입에 붙어요, 몬!",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPC가 인사하거나 퀘스트를 줄 때 말하지 않습니다. 오류 음성도 끕니다.",
	["Los Perdidos del pantano son draenei que llegaron de Draenor y quedaron cambiados para siempre."] = "늪의 잃어버린 자들은 드레노어에서 와서 영원히 변해 버린 드레나이예요.",
	["Los Páramos de Poniente eran el granero de Ventormenta; hoy muchas de sus granjas están en manos de la Hermandad Defias."] = "서부 몰락지대는 스톰윈드의 곡창이었어요. 지금은 많은 농장이 데피아즈단의 손에 있어요.",
	["Los Renegados aguantan bajo el agua mucho más que los vivos. ¡No necesitan respirar tanto!"] = "포세이큰은 산 자보다 물속에서 훨씬 오래 버텨요. 숨을 그렇게 많이 쉴 필요가 없거든요!",
	["Los Renegados entraron a la Horda gracias a los tauren, que esperaban encontrarles una cura. Muchos orcos aún no se fían de ellos."] = "포세이큰은 치료법을 찾아 주길 바란 타우렌 덕분에 호드에 들어왔어요. 많은 오크가 아직도 그들을 믿지 않아요.",
	["Los Renegados hicieron de Rémol, un viejo pueblo humano, su primera parada en Tirisfal."] = "포세이큰은 옛 인간 마을 브릴을 티리스팔 숲의 첫 거점으로 삼았어요.",
	["Los Renegados nuevos despiertan en Camposanto, en Tirisfal, como no-muertos libres del Rey Exánime."] = "새 포세이큰은 티리스팔 숲의 죽음의 종소리에서 리치 왕에게서 풀려난 언데드로 깨어나요.",
	["Los Renegados pueden comerse cadáveres para recuperar vida. Yo prefiero las salchichas, gracias."] = "포세이큰은 시체를 먹어 생명력을 회복할 수 있어요. 저는 소시지가 더 좋아요, 고마워요.",
	["Los Renegados recuerdan quiénes fueron en vida, y eso pesa más que cualquier herida."] = "포세이큰은 살아 있을 때 누구였는지 기억하고, 그건 어떤 상처보다 무거워요.",
	["Los Renegados son no-muertos que recuperaron su voluntad cuando el poder del Rey Exánime se debilitó."] = "포세이큰은 리치 왕의 힘이 약해졌을 때 자유 의지를 되찾은 언데드예요.",
	["Los Tótem Siniestro son tauren que no quieren a la Horda; su jefa Magatha vive en la misma Cima del Trueno."] = "그림토템은 호드를 싫어하는 타우렌이에요. 그 우두머리 마가사는 바로 썬더 블러프에 살아요.",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "알림 설정은 Alfa 창의 검색에서 찾을 수 있습니다.",
	["Los altos elfos pelearon con la Alianza en la Segunda Guerra por una vieja deuda de sangre con el linaje de Thoradin."] = "하이 엘프는 소라딘 혈통에 진 오랜 피의 빚 때문에 2차 대전쟁에서 얼라이언스와 함께 싸웠어요.",
	["Los altos elfos que sobrevivieron a la Plaga empezaron a llamarse elfos de sangre, en honor a los suyos caídos. Kael'thas los guía."] = "스컬지에게서 살아남은 하이 엘프는 쓰러진 동족을 기려 스스로를 블러드 엘프라 부르기 시작했어요. 캘타스가 그들을 이끌어요.",
	["Los antídotos que haces curan venenos. ¡En las arañas de Vallefresno se agradecen!"] = "직접 만든 해독제는 독을 치료해요. 잿빛 골짜기 거미들 상대로 정말 고마워요!",
	["Los aqir eran un imperio antiguo de insectos que peleó contra los trols. De ellos vienen los qiraji de Ahn'Qiraj y los nerubianos del norte."] = "아퀴르는 트롤과 싸운 고대 곤충 제국이었어요. 그들에게서 안퀴라즈의 퀴라지와 북쪽의 네루비안이 나왔어요.",
	["Los ayudantes de los enemigos."] = "적의 조력자.",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "미니맵 주변의 다른 애드온 버튼(Alfa 버튼 포함)이 마우스를 올렸을 때만 나타납니다.",
	["Los cebos suben tu habilidad de pesca un rato: úsalos en aguas difíciles."] = "미끼는 잠시 낚시 숙련도를 올려 줘요. 어려운 물에서 쓰세요.",
	["Los cementerios del Ocaso están llenos de no-muertos levantados por nigromantes que se esconden en el bosque."] = "그늘숲의 묘지는 숲에 숨은 강령술사들이 일으킨 언데드로 가득해요.",
	["Los centauros dicen descender de Zaetar, hijo del semidiós Cenarius, y de Theradras, la princesa de la tierra. Pelean entre sus clanes casi tanto como contra los demás."] = "켄타우로스는 반신 세나리우스의 아들 자에타르와 대지의 공주 테라드라스의 후손이라고 해요. 다른 종족과 싸우는 만큼 부족끼리도 싸워요.",
	["Los cinco Aspectos Dragón recibieron su poder de los titanes: Alexstrasza la vida, Ysera el sueño, Nozdormu el tiempo, Malygos la magia y Neltharion la tierra."] = "다섯 위상은 티탄에게서 힘을 받았어요: 알렉스트라자는 생명, 이세라는 꿈, 노즈도르무는 시간, 말리고스는 마법, 넬타리온은 대지.",
	["Los clanes Gelkis y Magram de Desolace pelean entre sí, y ambos buscan aliados entre los aventureros."] = "잊혀진 땅의 겔키스 부족과 마그람 부족은 서로 싸우며, 둘 다 모험가 중에서 동맹을 찾아요.",
	["Los clanes orcos tienen historias distintas: Lobo Gélido, Grito de Guerra, Roca Negra, Faucedraco... cada uno con su orgullo."] = "오크 부족마다 이야기가 달라요. 서리늑대, 전쟁노래, 검은바위, 용아귀... 저마다 자부심이 있어요.",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "붉은십자군 성전사들이 무리 지어 오고 일부는 치유를 합니다. 치유하는 적을 차단하세요.",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "치명타는 두 배의 피해를 주고, 전사에게는 분노를 더 줍니다.",
	["Los cuatro dragones verdes de la pesadilla, Ysondre, Lethon, Emeriss y Taerar, aparecen junto a los grandes árboles del Sueño."] = "악몽의 녹색용 넷, 이손드레, 레손, 에메리스, 타에라가 꿈의 거대한 나무 곁에 나타나요.",
	["Los cuatro señores elementales son Ragnaros del fuego, Al'Akir del aire, Therazane de la tierra y Neptulon del agua."] = "네 정령 군주는 불의 라그나로스, 바람의 알아키르, 대지의 테라제인, 물의 넵튤론이에요.",
	["Los cultistas del Martillo Crepuscular usan piedras de viento para invocar a sus señores; con su disfraz, tú también puedes."] = "황혼의 망치 신도는 바람의 돌로 군주를 소환해요. 그들의 변장을 하면 당신도 할 수 있어요.",
	["Los datos de Alfa no cargaron (%s)."] = "Alfa 데이터를 불러오지 못했습니다(%s).",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Alfa 데이터에 이 우두머리들 고유의 전리품이 없습니다.",
	["Los datos de las mazmorras no están cargados."] = "던전 데이터가 불러와지지 않았습니다.",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "던전 데이터는 전투 중이 아닐 때 불러옵니다. 전투가 끝나면 이 페이지가 자동으로 채워집니다.",
	["Los datos del mundo (Codex) no están disponibles: faltan los bancos, las misiones y de dónde sale cada cosa."] = "월드 데이터(Codex)를 쓸 수 없습니다. 물고기 떼, 퀘스트, 출처가 빠져 있습니다.",
	["Los datos del mundo de Alfa están apagados: activa «Alfa Codex» en la lista de addons."] = "Alfa 월드 데이터가 꺼져 있습니다. 애드온 목록에서 «Alfa Codex»를 켜세요.",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "데이터는 게임의 공식 측정기에서 옵니다. 나, 파티나 공격대, 소환수까지 포함합니다.",
	["Los dioses antiguos son seres de antes de los titanes, encerrados bajo la tierra de Azeroth. C'Thun y Yogg-Saron susurran a quien quiera escuchar."] = "고대 신은 티탄보다 오래된 존재로, 아제로스 땅 밑에 갇혀 있어요. 쑨과 요그사론은 귀 기울이는 누구에게나 속삭여요.",
	["Los dioses antiguos susurran en la mente de los mortales; muchos cultos, como el Martillo Crepuscular, nacieron de escucharlos."] = "고대 신은 필멸자의 마음에 속삭여요. 황혼의 망치 같은 많은 교단이 그 속삭임을 듣고 생겨났어요.",
	["Los dos"] = "둘 다",
	["Los dos bandos"] = "양 진영",
	["Los dracoleones son las monturas voladoras de la Horda; los grifos, las de la Alianza; y los hipogrifos, las de los elfos de la noche."] = "와이번은 호드의, 그리핀은 얼라이언스의, 히포그리프는 나이트 엘프의 비행 탈것이에요.",
	["Los dracónidos negros rondan la entrada de la guarida de Onyxia, al sur del marjal."] = "검은 용족이 습지대 남쪽 오닉시아의 둥지 입구를 어슬렁거려요.",
	["Los dracónidos son los soldados de los dragones; los negros sirven a Nefarian en la Montaña Roca Negra."] = "용족은 용의 병사예요. 검은 용족은 검은바위 산에서 네파리안을 섬겨요.",
	["Los draenei huyeron de su mundo, Argus, con el profeta Velen. Su nombre quiere decir «los exiliados»."] = "드레나이는 예언자 벨렌과 함께 고향 세계 아르거스를 떠났어요. 그 이름은 «망명자»라는 뜻이에요.",
	["Los dragones cromáticos, con escamas de todos los colores, son experimentos de Nefarian. Su obra más temida es Chromaggus."] = "온갖 색 비늘을 가진 오색용은 네파리안의 실험작이에요. 가장 무서운 작품은 크로마구스예요.",
	["Los dragones negros se disfrazan de humanos para engañar: Onyxia es Lady Katrana Prestor en Ventormenta, y Nefarian se hace llamar Lord Victor Nefarius."] = "검은용은 사람으로 변장해 속여요. 오닉시아는 스톰윈드의 카트라나 프레스터 부인이고, 네파리안은 빅터 네파리우스 경이라 자칭해요.",
	["Los dragones verdes siguen vigilando el templo hundido para que nadie vuelva a llamar a Hakkar."] = "녹색용들은 아무도 학카르를 다시 부르지 못하게 지금도 가라앉은 신전을 지켜요.",
	["Los elementales de fuego de La Garganta de Fuego y del Cráter de Un'Goro sueltan materiales de fuego que piden muchas profesiones."] = "이글거리는 협곡과 운고로 분화구의 화염 정령은 여러 전문 기술에 필요한 불 재료를 떨어뜨려요.",
	["Los elementales de fuego y las arañas de lava son los vecinos de siempre de La Garganta de Fuego."] = "화염 정령과 용암 거미는 이글거리는 협곡의 단골 이웃이에요.",
	["Los elfos de la noche fueron inmortales gracias a Nordrassil, hasta que lo sacrificaron para vencer a Archimonde en el Monte Hyjal."] = "나이트 엘프는 놀드랏실 덕분에 불멸이었지만, 하이잘 산에서 아키몬드를 물리치려고 그것을 희생했어요.",
	["Los elfos de la noche montan sables, grandes felinos. No es por nada, pero un lobo es más simpático."] = "나이트 엘프는 큰 고양이인 표범을 타요. 자랑은 아니지만 늑대가 더 상냥해요.",
	["Los elfos de la noche nuevos empiezan en la Cañada Umbría, en Teldrassil, entre arañas y fuegos fatuos."] = "새 나이트 엘프는 텔드랏실의 그늘 협곡에서 거미와 위습 사이에서 시작해요.",
	["Los elfos de la noche pueden fundirse con las sombras cuando se quedan quietos."] = "나이트 엘프는 가만히 있으면 그림자 속에 녹아들 수 있어요.",
	["Los elfos de la noche se unieron a la Alianza después de la Tercera Guerra."] = "나이트 엘프는 3차 대전쟁 뒤 얼라이언스에 합류했어요.",
	["Los enanos Hierro Negro tomaron Dun Modr, al norte de Los Humedales, y desde ahí molestan a quien cruce el puente."] = "검은무쇠 드워프가 저습지 북쪽의 둔 모드르를 차지하고, 다리를 건너는 누구든 괴롭혀요.",
	["Los enanos creen descender de los terráneos de piedra de los titanes, y por eso la Liga de Expedicionarios excava sin parar."] = "드워프는 티탄의 돌 대지인의 후손이라고 믿어서, 탐험가 연맹이 쉬지 않고 발굴해요.",
	["Los enanos de Forjaz pelean contra los Hierro Negro en Los Humedales y en las Tierras Inhóspitas."] = "아이언포지 드워프는 저습지와 황야의 땅에서 검은무쇠와 싸워요.",
	["Los enanos nuevos empiezan en un valle helado de Dun Morogh, peleando contra trols de las nieves y troggs."] = "새 드워프는 던 모로의 얼어붙은 골짜기에서 얼음 트롤과 트로그와 싸우며 시작해요.",
	["Los encantadores también hacen varitas: los magos, sacerdotes y brujos te lo agradecerán."] = "마법부여사는 마법봉도 만들어요. 마법사, 사제, 흑마법사가 고마워할 거예요.",
	["Los enemigos de alrededor pegan menos."] = "주위의 적이 주는 피해가 줄어듭니다.",
	["Los enemigos de tus misiones marcados sobre su placa de nombre y los objetos de misión brillando en tus bolsas."] = "퀘스트 대상 적은 이름표 위에 표시되고, 퀘스트 아이템은 가방에서 빛납니다.",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "적들이 방사능과 독을 씁니다. 생명력 물약을 챙기세요.",
	["Los enemigos más débiles, que el juego marca con un signo de menos."] = "게임이 빼기 표시로 구분하는 가장 약한 적.",
	["Los espíritus de las elfas caídas que la Plaga esclaviza se vuelven banshees. Sylvanas es la más famosa de todas."] = "스컬지에게 사로잡힌 쓰러진 엘프 여인들의 영혼은 밴시가 돼요. 실바나스가 그중 가장 유명해요.",
	["Los fragmentos de alma se ganan drenando el alma del enemigo justo cuando muere."] = "영혼의 조각은 적이 죽는 순간 영혼을 흡수해서 얻어요.",
	["Los frascos del Clásico duran dos horas y aguantan aunque mueras: por eso las bandas los piden tanto."] = "클래식의 영약은 두 시간 동안 가고 죽어도 남아요. 그래서 공격대에서 그렇게 찾아요.",
	["Los frascos más poderosos llevan Loto negro, la hierba más rara de Azeroth."] = "가장 강력한 영약에는 아제로스에서 가장 귀한 약초, 검은 연꽃이 들어가요.",
	["Los fuegos artificiales también son ingeniería. ¡Uno para festejar cada nivel!"] = "불꽃놀이도 기계공학이에요. 레벨마다 하나씩 터뜨려요!",
	["Los fuegos fatuos son espíritus de elfos de la noche que siguen cuidando el bosque después de morir."] = "위습은 죽은 뒤에도 숲을 지키는 나이트 엘프의 영혼이에요.",
	["Los furbolgs Fauces de Madera son de los pocos que no se han corrompido; sus túneles llevan a Cuna del Invierno y al Claro de la Luna."] = "나무구렁 퍼볼그는 타락하지 않은 몇 안 되는 무리예요. 그들의 굴은 여명의 설원과 달의 숲으로 이어져요.",
	["Los furbolgs de Costa Oscura se están corrompiendo, y los elfos de Auberdine no saben bien por qué."] = "어둠의 해안 퍼볼그가 타락하고 있는데, 아우버다인 엘프들은 이유를 잘 몰라요.",
	["Los furbolgs eran un pueblo pacífico de hombres oso, pero la corrupción de los demonios enloqueció a muchas de sus tribus."] = "퍼볼그는 평화로운 곰 인간 종족이었지만, 악마의 타락이 많은 부족을 미치게 했어요.",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "풍수사들이 불을 쓰고 토템을 세웁니다. 차단하고 토템을 부수세요.",
	["Los gnomos empiezan con los enanos en Dun Morogh: Gnomeregan está perdida y tu gente vive refugiada en Forjaz."] = "노움은 던 모로에서 드워프와 함께 시작해요. 놈리건을 잃고 당신 종족은 아이언포지에서 피난민으로 살아요.",
	["Los gnomos inventaron el Tranvía Subterráneo que une Forjaz con Ventormenta."] = "아이언포지와 스톰윈드를 잇는 깊은굴 지하철은 노움이 만들었어요.",
	["Los gnomos que se quedaron en Gnomeregan quedaron dañados por la radiación; algunos perdieron la razón."] = "놈리건에 남은 노움들은 방사능에 다쳤고, 일부는 정신을 잃었어요.",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "주조소의 고블린 근처에는 도우미가 있습니다. 공격하기 전에 주변을 살피세요.",
	["Los goblins vienen de la isla de Kezan, y su gran ciudad es Minahonda. Le son más leales al oro que a cualquier bando."] = "고블린은 케잔 섬 출신이고, 큰 도시는 언더마인이에요. 어떤 진영보다 골드에 더 충성해요.",
	["Los grandes árboles que hablan en Darnassus y Vallefresno son Ancestros, guardianes del bosque."] = "다르나서스와 잿빛 골짜기의 말하는 큰 나무들은 숲의 수호자인 고대정령이에요.",
	["Los grifos (o dragones) a los lados de la barra principal."] = "주 행동 단축바 양옆의 그리핀(또는 와이번).",
	["Los gules, las abominaciones y las gárgolas son los soldados más comunes de la Plaga. Las abominaciones se cosen con partes de muchos cadáveres."] = "구울, 누더기골렘, 가고일은 스컬지의 가장 흔한 병사예요. 누더기골렘은 여러 시체를 꿰매 만들어요.",
	["Los herreros hacen llaves que abren cofres y cajas cerradas. ¡Útil y divertido!"] = "대장장이는 상자와 잠긴 상자를 여는 열쇠를 만들어요. 쓸모 있고 재밌어요!",
	["Los humanos fueron los primeros en aprender magia de los altos elfos, allá en las Guerras Trol."] = "인간은 트롤 전쟁 때 하이 엘프에게 처음으로 마법을 배웠어요.",
	["Los infernales son demonios que la Legión arroja desde el cielo como meteoritos."] = "지옥불정령은 군단이 유성처럼 하늘에서 떨어뜨리는 악마예요.",
	["Los ingenieros pueden fabricar mascotas mecánicas, como una ardilla."] = "기계공학자는 다람쥐 같은 기계 애완동물을 만들 수 있어요.",
	["Los instructores y vendedores de pesca se ven en el mapa y el minimapa."] = "낚시 전문가와 상인이 지도와 미니맵에 표시됩니다.",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "선택 우두머리와 희귀 우두머리는 던전을 끝내면 공개됩니다.",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "우두머리는 처치하면 공개됩니다. 그 전까지 이름과 전리품은 숨겨져 있습니다. 공략은 언제든 볼 수 있습니다.",
	["Los kits de armadura que haces le sirven a todo el mundo: siempre hay quien los compre."] = "직접 만든 방어구 강화 키트는 누구에게나 쓸모 있어서 늘 살 사람이 있어요.",
	["Los kodos son los compañeros de viaje de los tauren, y en Desolace está su cementerio."] = "코도는 타우렌의 여행 동반자이고, 그 무덤은 잊혀진 땅에 있어요.",
	["Los kóbolds de las minas de Elwynn cuidan sus velas como un tesoro: bajo tierra, la luz lo es todo."] = "엘윈 숲 광산의 코볼트는 양초를 보물처럼 지켜요. 땅속에서는 빛이 전부거든요.",
	["Los lobos aprenden Aullido furioso, que sube el daño de tu grupo. ¡Ya ves, los lobos somos lo máximo!"] = "늑대는 사나운 울부짖음을 배워 파티의 피해를 올려요. 봐요, 늑대가 최고라니까요!",
	["Los lobos que se dejan ver en el mapa. Un clic en su marca y la flecha te lleva."] = "지도에 자신을 공개한 늑대들. 표시를 클릭하면 화살표가 안내합니다.",
	["Los lobos que usan Alfa y se dejan ver en el mapa, y tu grupo, que ves ahora."] = "Alfa를 쓰며 지도에 자신을 공개한 늑대들과, 지금 보이는 내 파티.",
	["Los logros de la manada: se ganan pescando, cocinando lo que pescas y explorando aguas nuevas. Cada uno se anuncia una sola vez."] = "무리의 업적: 낚시하고, 낚은 것을 요리하고, 새 물을 탐험하면 얻습니다. 각 업적은 한 번만 알립니다.",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "백과사전에서 지도에 표시하라고 한 장소.",
	["Los maestros de vuelo de tu facción y los neutrales: verdes si ya los conoces, ámbar con «?» si te falta descubrirlos. Clic: seguirlo con la flecha."] = "내 진영과 중립 비행 조련사. 이미 알면 초록색, 아직 찾아야 하면 «?»가 붙은 호박색. 클릭: 화살표로 따라가기.",
	["Los magos de Dalaran forman el Kirin Tor, su consejo de sabios."] = "달라란 마법사들은 현자 의회인 키린 토를 이뤄요.",
	["Los marcos de Curación están apagados"] = "치유 프레임이 꺼져 있습니다",
	["Los marcos se mueven fuera de combate."] = "프레임은 전투 중이 아닐 때 옮길 수 있습니다.",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "게임 자체의 프레임, 배경, 버튼, 글꼴과 금색 제목.",
	["Los mismos marcadores de misiones en el minimapa."] = "같은 퀘스트 표시를 미니맵에도 표시합니다.",
	["Los múrlocs hablan con gorgoteos y burbujas: ese «mrglglgl» es su idioma de verdad."] = "멀록은 꾸르륵거리는 소리와 거품으로 말해요. 그 «므르글글글»이 진짜 그들 언어예요.",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "나가와 사티로스가 냉기와 번개를 씁니다. 주문 시전자부터 차단하세요.",
	["Los nerubianos, arañas gigantes de Rasganorte, pelearon contra el Rey Exánime y perdieron; muchos hoy le sirven."] = "노스렌드의 거대 거미 네루비안은 리치 왕과 싸우다 졌고, 지금은 많은 수가 그를 섬겨요.",
	["Los no-muertos de la Plaga no sienten miedo ni cansancio, y por eso es tan difícil detenerlos."] = "스컬지의 언데드는 두려움도 피로도 몰라서 막기가 너무 어려워요.",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "보고 있는 지역의 채집 지점입니다. 마우스를 올리면 이름, 레벨, 채집 횟수가 나옵니다. 클릭하면 화살표가 안내합니다.",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "화면에서 겹치는 지점은 개수와 함께 하나의 핀으로 묶입니다. 지도를 확대하면 나뉩니다.",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "주변의 채집 지점입니다. 게임의 추적 점으로 지금 그곳에 무언가 있는지 알 수 있습니다.",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Alfa에 들어 있는 채집 지점입니다. 끄면 내가 찾은 지점만 보입니다.",
	["Los números de las habilidades de tu mascota."] = "소환수 기술의 피해 숫자.",
	["Los números de lo que curas encima de quien recibe."] = "치유받는 대상 위의 내 치유량 숫자.",
	["Los números de los golpes de tu mascota."] = "소환수 근접 공격의 피해 숫자.",
	["Los números de tu daño encima de quien golpeas."] = "공격한 대상 위의 내 피해량 숫자.",
	["Los oasis de Los Baldíos se están secando y llenando de bestias raras: los Druidas del Colmillo, que salieron de las Cuevas de los Lamentos, los corrompen."] = "불모의 땅 오아시스가 마르고 이상한 짐승으로 가득 차고 있어요. 통곡의 동굴에서 나온 송곳니의 드루이드가 타락시키고 있어요.",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "아이템을 가방의 처음이 아니라 끝쪽으로 모읍니다.",
	["Los orcos Faucedraco siguen en Los Humedales, aunque ya sin la Reina Dragón."] = "용아귀 오크는 용의 여왕은 잃었지만 아직 저습지에 있어요.",
	["Los orcos Roca Negra de Rend se adueñaron de la cumbre de la montaña y la llaman su hogar."] = "렌드의 검은바위 오크들이 산꼭대기를 차지하고 그곳을 집이라 불러요.",
	["Los orcos Roca Negra ocupan una vieja fortaleza humana al este de las montañas."] = "검은바위 오크가 산맥 동쪽의 옛 인간 요새를 차지하고 있어요.",
	["Los orcos llegaron de Draenor corrompidos por la sangre de Mannoroth. Thrall los sacó de los campos de internamiento y fundó la nueva Horda."] = "오크들은 만노로스의 피에 타락한 채 드레노어에서 왔어요. 스랄이 수용소에서 그들을 해방하고 새 호드를 세웠어요.",
	["Los orcos nuevos empiezan en el Valle de los Retos, en Durotar, donde prueban su valor."] = "새 오크는 듀로타의 시험의 골짜기에서 용기를 증명하며 시작해요.",
	["Los orcos vienen de Draenor, un mundo que hoy está roto y se llama Terrallende."] = "오크는 지금은 부서져 아웃랜드라 불리는 세계, 드레노어에서 왔어요.",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "계획의 나머지 %d포인트는 다음 레벨들에서 찍게 됩니다.",
	["Los peleteros hacen carcajes y bolsas de munición para los cazadores."] = "가죽세공사는 사냥꾼을 위해 화살통과 탄환 주머니를 만들어요.",
	["Los portales a pie que puedes usar, con a dónde llevan."] = "걸어서 쓸 수 있는 차원문과 그 목적지.",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "가격은 변합니다. 이 일수가 지나면 Alfa가 다시 스캔하라고 알려 줍니다.",
	["Los primeros caballeros de la muerte los creó Gul'dan: cuerpos de caballeros humanos caídos con almas de brujos orcos."] = "첫 죽음의 기사는 굴단이 만들었어요. 쓰러진 인간 기사의 몸에 오크 흑마법사의 영혼을 넣었죠.",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "다른 애드온이 설정한 경유지와 /way 명령어가 Alfa 화살표를 움직입니다. 다른 경유지 애드온의 설정을 기대하는 애드온은 이 옵션을 켜면 작동하지 않을 수 있습니다.",
	["Los puntos de vuelo y de viaje ya se ven en el mapa."] = "비행 지점과 이동 지점이 이제 지도에 보입니다.",
	["Los puntos que ganas en la cuenta también llenan el registro del Legado: premios de aspecto, sin ventaja en el juego. Al salir Forever son un rifle de réplica de Forjaz (juguete), la cría de oso espectral (mascota), el tabardo del oso espectral y las riendas del oso espectral (montura)."] = "계정에서 얻은 점수는 유산 보상 트랙도 채웁니다. 외형 보상이며 게임 내 이점은 없습니다. Forever 출시 시점에는 아이언포지 공기총 모형(장난감), 유령 새끼 곰(애완동물), 유령 곰 휘장, 유령 곰 고삐(탈것)입니다.",
	["Los puntos que ganas también llenan el registro del Legado, con premios de aspecto como la cría de oso espectral."] = "얻은 점수는 유산 보상 트랙도 채우고, 유령 새끼 곰 같은 외형 보상을 줘요.",
	["Los raros están apagados (página Descubrir)."] = "희귀가 꺼져 있습니다(발견 페이지).",
	["Los raros también en el minimapa."] = "희귀를 미니맵에도 표시합니다.",
	["Los recolectaste %d veces en total"] = "총 %d번 채집함",
	["Los sacerdotes Atal'ai siguieron adorando a Hakkar en secreto. Los desterraron, y levantaron su templo en el Pantano de las Penas."] = "아탈라이 사제들은 몰래 학카르를 계속 섬겼어요. 쫓겨난 그들은 슬픔의 늪에 신전을 세웠어요.",
	["Los servicios también en el minimapa."] = "시설을 미니맵에도 표시합니다.",
	["Los señores del terror, como Mal'Ganis, Balnazzar y Varimathras, eran los carceleros que la Legión le puso al Rey Exánime."] = "말가니스, 발나자르, 바리마트라스 같은 공포의 군주는 군단이 리치 왕에게 붙여 둔 간수였어요.",
	["Los señores elementales servían a los dioses antiguos. Cuando los titanes encerraron a esos dioses, desterraron a los elementales a sus propios planos."] = "정령 군주들은 고대 신을 섬겼어요. 티탄이 그 신들을 가두면서 정령들을 각자의 차원으로 추방했어요.",
	["Los sumos sacerdotes de Zul'Gurub tomaron el poder de los loa animales: el murciélago, la serpiente, la araña, la pantera y el tigre."] = "줄구룹의 대사제들은 동물 로아의 힘을 빼앗았어요: 박쥐, 뱀, 거미, 표범, 호랑이.",
	["Los sátiros de Azshara sueltan tela vil, muy buscada por los sastres."] = "아즈샤라의 사티로스는 재봉사들이 많이 찾는 악마 옷감을 떨어뜨려요.",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "확정한 특성은 공짜로 되돌릴 수 없습니다. 수락하기 전에 목록을 확인하세요.",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "계획의 다음 특성이 내 트리에 없거나 아직 찍을 수 없습니다. 게임의 특성 창에서 직접 찍거나 다른 빌드를 고르세요.",
	["Los tauren Tótem Siniestro tienen campamentos en Las Mil Agujas, y no son nada amigables."] = "그림토템 타우렌은 버섯구름 봉우리에 야영지를 두고 있고, 전혀 친절하지 않아요.",
	["Los tauren ayudaron a los Renegados a entrar a la Horda, con la esperanza de encontrarles una cura."] = "타우렌은 치료법을 찾아 주길 바라며 포세이큰이 호드에 들어오도록 도왔어요.",
	["Los tauren de Viento Libre viven en lo alto de Las Mil Agujas, a salvo de los centauros."] = "바람길 타우렌은 켄타우로스를 피해 버섯구름 봉우리 높은 곳에 살아요.",
	["Los tauren de Viento Libre viven en lo alto de las agujas, unidas por puentes colgantes, a salvo de los centauros de abajo."] = "바람길 타우렌은 흔들다리로 이어진 바위 기둥 꼭대기에 살아요. 아래의 켄타우로스로부터 안전하게요.",
	["Los tauren honran a la Madre Tierra. Dicen que el sol y la luna son sus ojos: An'she y Mu'sha."] = "타우렌은 대지모신을 섬겨요. 해와 달이 그녀의 눈이라고 해요: 안셰와 무샤.",
	["Los tauren llaman An'she al sol y Mu'sha a la luna: los ojos de la Madre Tierra."] = "타우렌은 해를 안셰, 달을 무샤라고 불러요. 대지모신의 두 눈이에요.",
	["Los tauren nuevos empiezan en el Campamento Narache, en Mulgore."] = "새 타우렌은 멀고어의 나라쉬 야영지에서 시작해요.",
	["Los tauren vivían como nómadas, acosados por los centauros, hasta que Cairne Pezuña de Sangre se alió con Thrall. Con la ayuda de la Horda encontraron su hogar en Mulgore."] = "타우렌은 켄타우로스에게 쫓기며 떠돌았지만, 케언 블러드후프가 스랄과 손잡으면서 호드의 도움으로 멀고어에 보금자리를 찾았어요.",
	["Los tesoros también en el minimapa."] = "보물을 미니맵에도 표시합니다.",
	["Los titanes dejaron guardianes de piedra y metal en Azeroth. En Uldaman todavía hay uno despierto: Archaedas."] = "티탄은 아제로스에 돌과 금속의 수호자를 남겼어요. 울다만에는 아직 깨어 있는 수호자 아카에다스가 있어요.",
	["Los titanes le dieron forma a Azeroth y dejaron guardianes y ciudades, como Uldaman, para cuidar su obra."] = "티탄은 아제로스를 빚고, 그 작품을 돌보도록 수호자와 울다만 같은 도시를 남겼어요.",
	["Los titanes son seres colosales que recorren el cosmos poniendo orden en los mundos. Los más famosos forman el Panteón, que guiaba Aman'Thul."] = "티탄은 우주를 누비며 세계에 질서를 세우는 거대한 존재예요. 가장 유명한 이들은 아만툴이 이끌던 판테온을 이뤄요.",
	["Los titanes usaron este cráter como un jardín de pruebas para la vida; por eso hay dinosaurios y plantas gigantes."] = "티탄은 이 분화구를 생명의 실험 정원으로 썼어요. 그래서 공룡과 거대한 식물이 있어요.",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "트로그는 생명력이 낮으면 도망쳐서 동료를 데려옵니다. 도망치기 전에 막으세요.",
	["Los troggs invadieron Gnomeregan, y los gnomos inundaron su propia ciudad de radiación al intentar sacarlos. Fue idea del mekigeniero Termochufe."] = "트로그가 놈리건을 침공했고, 노움들은 그들을 몰아내려다 자기 도시를 방사능으로 뒤덮었어요. 멕기니어 텔마플러그의 생각이었어요.",
	["Los troggs salieron de las profundidades de Uldaman. Todo indica que son una creación antigua de los titanes que salió mal."] = "트로그는 울다만 깊은 곳에서 나왔어요. 모든 증거가 잘못된 고대 티탄의 창조물이라고 말해요.",
	["Los trols Lanza Negra conocieron a Thrall en las islas donde naufragó su flota rumbo a Kalimdor. Su líder Sen'jin murió ahí, y desde entonces los guía su hijo Vol'jin."] = "검은창 트롤은 칼림도어로 가던 스랄의 함대가 난파한 섬에서 그를 만났어요. 지도자 센진이 그곳에서 죽은 뒤로 아들 볼진이 이끌어요.",
	["Los trols Lanza Negra empiezan con los orcos, en el Valle de los Retos de Durotar."] = "검은창 트롤은 듀로타의 시험의 골짜기에서 오크와 함께 시작해요.",
	["Los trols adoran a espíritus llamados loa. Hakkar es uno de ellos, y de los más peligrosos."] = "트롤은 로아라 불리는 정령을 섬겨요. 학카르도 그중 하나인데, 가장 위험한 축이에요.",
	["Los trols de estas tierras descienden de los Amani, el antiguo imperio de los trols del bosque. En Jintha'Alor siguen levantando sus altares."] = "이 땅의 트롤은 고대 숲 트롤 제국 아마니의 후손이에요. 진타알로에서 아직도 제단을 세워요.",
	["Los vendedores de suministros de pesca tienen cañas, lombrices y baratijas."] = "낚시용품 상인에게는 낚싯대, 지렁이, 미끼 장신구가 있습니다.",
	["Los worgen son hombres lobo de origen misterioso. Arugal los trajo a Lordaeron. ¡No me confundas con ellos, eh!"] = "늑대인간은 기원이 수수께끼인 인간 늑대예요. 아루갈이 그들을 로데론에 데려왔어요. 저랑 헷갈리면 안 돼요!",
	["Los zepelines salen de las torres junto a Orgrimmar hacia Entrañas y hacia Grom'gol, en la Vega de Tuercespina."] = "비행선은 오그리마 옆 탑에서 언더시티와 가시덤불 골짜기의 그롬골로 떠나요.",
	["Los árboles del Legado son tres: Profesiones, Aventura y Recursos. Al salir Forever, cada personaje gasta hasta 16 puntos."] = "유산 트리는 세 개예요: 전문 기술, 모험, 수완. Forever 출시 시점에는 캐릭터마다 최대 16점을 써요.",
	["Los últimos Altonato de Kalimdor siguen en La Masacre: se llaman Shen'dralar y cuidan su vieja biblioteca."] = "칼림도어의 마지막 명가는 혈투의 전장에 남아 있어요. 셴드랄라라고 불리며 옛 도서관을 돌봐요.",
	["Los últimos puntos."] = "마지막 포인트.",
	["Lothar cayó ante Orgrim Martillo Maldito al pie de la Montaña Roca Negra. Turalyon tomó su lugar y ganó la Segunda Guerra."] = "로타는 검은바위 산 기슭에서 오그림 둠해머에게 쓰러졌어요. 투랄리온이 그 자리를 이어 2차 대전쟁에서 이겼어요.",
	["Luego cópialo con Ctrl+C."] = "그런 다음 Ctrl+C로 복사하세요.",
	["Lugar"] = "위치",
	["Lugar conocido: el punto del rastreo del juego dice si ahora hay algo."] = "알려진 위치: 게임의 추적 점으로 지금 무언가 있는지 알 수 있습니다.",
	["Lugar de los marcos"] = "프레임 위치",
	["Lugar desconocido"] = "알 수 없는 장소",
	["Lugar: %s"] = "장소: %s",
	["Luna"] = "달",
	["Luz y efectos"] = "빛과 효과",
	["Lya"] = "Lya",
	["Lya ahora es una loba negra de cuerpo completo, con 39 cuadros de animación: se sienta, corre, se busca la cola, bosteza y duerme enroscada."] = "Lya가 이제 39프레임 애니메이션의 온몸이 보이는 검은 암컷 늑대가 됐습니다. 앉고, 달리고, 꼬리를 쫓고, 하품하고, 몸을 말고 잡니다.",
	["Lya cuenta historias"] = "Lya가 들려주는 이야기",
	["Lya de cuerpo completo"] = "온몸이 보이는 Lya",
	["Lya en tu pantalla"] = "화면의 Lya",
	["Lya está calladita"] = "Lya가 조용히 있어요",
	["Lya está descansando"] = "Lya가 쉬고 있어요",
	["Lya fue una gran perrita: noble, leal y siempre al lado de los suyos, la gordita consentida de la casa. Alfa la recuerda así, como la loba que cuida a la manada y nunca deja a nadie atrás."] = "Lya는 멋진 강아지였습니다. 고귀하고 충직했으며 언제나 가족 곁을 지킨, 집안의 통통한 귀염둥이였죠. Alfa는 그렇게 기억합니다. 무리를 지키고 누구도 두고 가지 않는 암컷 늑대로.",
	["Lya guarda la historia de cada misión que tomas, aunque la aceptes sin leerla. Tú sigue la flecha: ella se acuerda de todo."] = "Lya는 받는 퀘스트마다 이야기를 저장합니다. 읽지 않고 수락해도요. 화살표만 따라가세요. Lya가 다 기억해요.",
	["Lya platica mucho más: lore de Warcraft, datos de cada zona, de tu raza, tu clase y tus profesiones, y consejos de eventos y de farmeo. ¡Y le encantan las salchichas!"] = "Lya가 훨씬 더 많이 이야기합니다: 워크래프트 이야기, 각 지역과 내 종족, 직업, 전문 기술에 관한 사실, 이벤트와 파밍 조언까지. 그리고 소시지를 정말 좋아해요!",
	["Lya se fue a descansar. Vuelve con /alfa lya."] = "Lya가 쉬러 갔습니다. /alfa lya로 다시 부르세요.",
	["Lya se queda calladita una hora. Aquí sigue, cuidándote."] = "Lya가 한 시간 동안 조용히 있어요. 여전히 곁에서 지켜보고 있어요.",
	["Lya te acompaña"] = "Lya가 함께합니다",
	["Lya te espera"] = "Lya가 기다려요",
	["Lya tiene mucho que contar"] = "Lya에게 들려줄 이야기가 많아요",
	["Lya volvió. Dale clic cuando quieras un consejo."] = "Lya가 돌아왔어요. 조언이 필요하면 언제든 클릭하세요.",
	["Lya vuelve a contarte sus consejos desde el principio."] = "Lya가 조언을 처음부터 다시 들려줍니다.",
	["Lya vuelve a hablar."] = "Lya가 다시 말해요.",
	["Lya, la loba de confianza del Alfa"] = "Lya, 알파가 믿는 암컷 늑대",
	["Lánzalo antes de la siguiente pelea."] = "다음 전투 전에 시전하세요.",
	["Lánzalo antes de pelear."] = "전투 전에 시전하세요.",
	["Línea de la ruta"] = "경로 선",
	["Línea de tiempo apagada"] = "타임라인 꺼짐",
	["Línea de tiempo del jefe"] = "우두머리 타임라인",
	["Línea de tiempo prendida"] = "타임라인 켜짐",
	["Maestro"] = "달인",
	["Maestro de armas"] = "무기 전문가",
	["Maestro de batalla"] = "전장 관리인",
	["Maestro de establos"] = "야수 관리인",
	["Maestro de vuelo"] = "비행 조련사",
	["Maestro del agua"] = "물의 달인",
	["Maestros de armas"] = "무기 전문가",
	["Maestros de batalla"] = "전장 관리인",
	["Maestros de establos"] = "야수 관리인",
	["Maestros de vuelo"] = "비행 조련사",
	["Maestría elemental: tu siguiente hechizo es crítico y gratis."] = "정기의 숙련: 다음 주문이 비용 없이 치명타로 나갑니다.",
	["Maestría nueva: %s (%d)"] = "새 숙련 단계: %s (%d)",
	["Mago"] = "마법사",
	["Maiev Cantosombrío fue la carcelera de Illidan durante diez mil años, al frente de las Vigilantes."] = "마이에브 섀도송은 감시자들을 이끌고 만 년 동안 일리단의 간수였어요.",
	["Mal'Ganis, el señor del terror, guió la plaga en Lordaeron. Arthas lo persiguió hasta Rasganorte, y esa cacería lo perdió."] = "공포의 군주 말가니스가 로데론의 역병을 이끌었어요. 아서스는 그를 노스렌드까지 쫓았고, 그 사냥이 그를 망쳤어요.",
	["Maldiciones y daño con el tiempo: pones tus hechizos y el monstruo muere solo mientras pasas al siguiente."] = "저주와 지속 피해: 주문을 걸어 두면 다음 몬스터로 넘어가는 동안 저절로 죽습니다.",
	["Maldición que hace cada vez más daño."] = "갈수록 피해가 커지는 저주.",
	["Malfurion Tempestira fue el primer druida de los elfos de la noche. Aprendió del semidiós Cenarius, a quien llamaba shan'do: «maestro honrado»."] = "말퓨리온 스톰레이지는 나이트 엘프 최초의 드루이드였어요. 반신 세나리우스에게 배웠고, 그를 «존경하는 스승»이라는 뜻의 샨도라 불렀어요.",
	["Malfurion Tempestira, el gran druida, está perdido en el Sueño Esmeralda, y Tyrande lo espera."] = "위대한 드루이드 말퓨리온 스톰레이지는 에메랄드의 꿈에서 길을 잃었고, 티란데가 그를 기다려요.",
	["Malla"] = "사슬",
	["Malygos, el Tejehechizos, guía a los dragones azules. La traición de Alamuerte casi acaba con su vuelo, y nunca se repuso del todo."] = "주문술사 말리고스는 푸른용을 이끌어요. 데스윙의 배신으로 그의 용군단은 거의 전멸했고, 그는 끝내 완전히 회복하지 못했어요.",
	["Manada"] = "무리",
	["Mano derecha"] = "주장비",
	["Mano firme"] = "흔들림 없는 손",
	["Mano izquierda"] = "보조장비",
	["Mano principal"] = "주장비",
	["Mano secundaria"] = "보조장비",
	["Manos"] = "손",
	["Mantén Furia recta encendida cuando tanquees."] = "방어 전담을 할 때는 정의의 격노를 켜 두세요.",
	["Mantén Grito de batalla siempre puesto."] = "전투의 외침을 항상 유지하세요.",
	["Mantén Seccionar en el rival para que no huya."] = "상대가 도망치지 못하게 무력화를 유지하세요.",
	["Mantén al monstruo lejos: tu mascota lo detiene mientras disparas."] = "몬스터를 멀리 두세요. 소환수가 붙잡는 동안 사격하세요.",
	["Maná"] = "마나",
	["Maná cada 5 s"] = "5초당 마나",
	["Mapa de Alfa"] = "Alfa 지도",
	["Mapa del mundo"] = "세계 지도",
	["Mapa estable y 46 arreglos"] = "안정된 지도와 46가지 수정",
	["Mapa y marcadores"] = "지도와 마커",
	["Mar abierto y zonas de nivel 35 en adelante. El rango Artesano lo da Nat Pagle en el Marjal Revolcafango con su misión."] = "먼바다와 35레벨 이상 지역. 장인 단계는 먼지진흙 습지대의 냇 페이글이 퀘스트로 줍니다.",
	["Maraudon es sagrado para los centauros: ahí descansa el espíritu de Zaetar, el padre de su raza."] = "마라우돈은 켄타우로스에게 신성한 곳이에요. 종족의 아버지 자에타르의 영혼이 그곳에 잠들어 있어요.",
	["Marca a los enemigos y empieza por el más peligroso."] = "적에게 표시를 하고 가장 위험한 적부터 시작하세요.",
	["Marca al enemigo: todos le pegan más."] = "적에게 표식을 남겨 모두가 더 큰 피해를 줍니다.",
	["Marca de lo Salvaje"] = "야생의 징표",
	["Marca el botón de tu barra que tiene la habilidad sugerida."] = "추천 기술이 있는 단축바 버튼을 표시합니다.",
	["Marca en el mapa a los instructores y vendedores de pesca de tu facción."] = "내 진영의 낚시 전문가와 상인을 지도에 표시합니다.",
	["Marca en el minimapa la entrada de cada mazmorra (en verde las que ya hiciste). El mapa del mundo ya las marca solo."] = "각 던전 입구를 미니맵에 표시합니다(이미 완료한 곳은 초록색). 세계 지도에는 이미 표시됩니다.",
	["Marcador"] = "마커",
	["Marcador borrado"] = "마커 삭제됨",
	["Marcador puesto: %s."] = "마커 설치: %s.",
	["Marcadores con Mayús+clic derecho en el mapa del juego"] = "게임 지도에서 Shift+오른쪽 클릭으로 마커",
	["Marcadores propios para compartir y seguir con la flecha."] = "공유하고 화살표로 따라갈 수 있는 나만의 마커.",
	["Marcar a quien te falta para una misión"] = "퀘스트에 아직 필요한 대상 표시",
	["Marcar como chatarra (%d)"] = "잡동사니로 표시 (%d)",
	["Marcar como hecha"] = "완료로 표시",
	["Marcar como hecha (o desmarcar)"] = "완료로 표시(또는 해제)",
	["Marcar las que no valen la pena"] = "할 가치 없는 것 표시",
	["Marcar para abandonar"] = "포기 대상으로 표시",
	["Marcas sobre cada objeto"] = "아이템 위 표시",
	["Marcaste como chatarra: %s. Se vende sola al hablar con un comerciante."] = "잡동사니로 표시함: %s. 상인과 대화하면 자동으로 팝니다.",
	["Marcaste como chatarra: %s. Véndela con «Vender la chatarra» en el comerciante."] = "잡동사니로 표시함: %s. 상인에게서 «잡동사니 팔기»로 파세요.",
	["Marco de prueba"] = "테스트 프레임",
	["Marcos"] = "프레임",
	["Marcos apagados"] = "프레임 꺼짐",
	["Marcos de Curación apagados."] = "치유 프레임 꺼짐.",
	["Marcos de Curación encendidos."] = "치유 프레임 켜짐.",
	["Marcos de grupo de Alfa: pasas el ratón sobre un compañero y haces clic para curarlo."] = "Alfa 파티 프레임: 파티원 위에 마우스를 올리고 클릭하면 치유합니다.",
	["Marcos de grupo y banda para curar con un clic, con preajustes por clase."] = "클릭 한 번으로 치유하는 파티 및 공격대 프레임입니다. 직업별 프리셋이 들어 있습니다.",
	["Marcos encendidos"] = "프레임 켜짐",
	["Marcos y barra"] = "프레임과 행동 단축바",
	["Marqué %d misiones"] = "퀘스트 %d개를 표시했습니다",
	["Mascota"] = "애완동물",
	["Mascotas"] = "애완동물",
	["Mascotas enemigas"] = "적 소환수",
	["Materiales"] = "직업용품",
	["Mayús"] = "Shift",
	["Mayús+Espacio sigue saltando"] = "Shift+스페이스는 여전히 점프",
	["Maza de dos manos"] = "양손 둔기",
	["Maza de una mano"] = "한손 둔기",
	["Mazmorra"] = "던전",
	["Mazmorras"] = "던전",
	["Mazmorras (3): derrotar al último jefe de todas las mazmorras de nivel 15-25, 26-45 y 46-60 (un punto por grupo)."] = "던전 (3): 15-25, 26-45, 46-60레벨 모든 던전의 마지막 우두머리 처치(묶음마다 1점).",
	["Mazmorras claras"] = "알기 쉬운 던전",
	["Mazmorras hechas"] = "완료한 던전",
	["Mazmorras y bandas"] = "던전과 공격대",
	["Mazthoril es la guarida de los dragones azules, siempre atentos a quién usa la magia."] = "마즈소릴은 푸른용의 둥지예요. 누가 마법을 쓰는지 늘 지켜봐요.",
	["Me encanta cazar contigo. ¡Vamos por la siguiente!"] = "함께 사냥하는 게 정말 좋아요. 다음 사냥감으로 가요!",
	["Me gusta cuidarte la espalda. Para eso estoy."] = "등 뒤를 지켜 주는 게 좋아요. 그러려고 제가 있는 거예요.",
	["Me gusta este paso tranquilo. Así se disfruta el camino."] = "이렇게 느긋한 걸음이 좋아요. 이래야 길을 즐기죠.",
	["Me gusta ir contigo. Se nota que sabes lo que haces."] = "당신과 함께 다니는 게 좋아요. 뭘 하는지 잘 아시네요.",
	["Media"] = "중간",
	["Medianos y graves"] = "중간 및 위험",
	["Medias"] = "중간",
	["Medidor de daño"] = "피해 측정기",
	["Medio"] = "중간",
	["Medivh era hijo de Aegwynn, la Guardiana anterior. Ella escondió en él el poder del Guardián sin saber que Sargeras también se escondía ahí."] = "메디브는 전 수호자 에이그윈의 아들이었어요. 그녀는 수호자의 힘을 아들 안에 숨겼지만, 살게라스도 거기 숨어 있는 줄은 몰랐어요.",
	["Medivh era hijo de Aegwynn, la Guardiana, y de Nielas Aran, un mago de la corte de Ventormenta."] = "메디브는 수호자 에이그윈과 스톰윈드 궁정 마법사 닐라스 아란의 아들이었어요.",
	["Medivh murió a manos de Khadgar y Lothar, pero años después regresó como el misterioso profeta que llevó a Thrall a Kalimdor."] = "메디브는 카드가와 로타의 손에 죽었지만, 몇 년 뒤 스랄을 칼림도어로 이끈 수수께끼의 예언자로 돌아왔어요.",
	["Medivh, poseído por Sargeras, abrió el camino para que la Horda llegara a Azeroth."] = "살게라스에게 사로잡힌 메디브가 호드가 아제로스에 올 길을 열었어요.",
	["Mejor %s"] = "대신 %s",
	["Mejor:"] = "추천:",
	["Mejora"] = "고양",
	["Mejora para subir"] = "레벨업용 고양",
	["Mejora tu defensa con escudo."] = "방패를 들었을 때 방어력이 좋아집니다.",
	["Mejorar el cuadro de información"] = "툴팁 개선",
	["Mejorar el minimapa"] = "미니맵 개선",
	["Mejorar el probador"] = "미리보기 창 개선",
	["Mejoras de equipo"] = "장비 향상",
	["Mensajes de aviso en pantalla"] = "화면 경고 메시지",
	["Mensajes enviados: %d (frenados: %d) · recibidos: %d · en cola: %d"] = "보낸 메시지: %d (제한됨: %d) · 받은 메시지: %d · 대기 중: %d",
	["Menú del jugador"] = "플레이어 메뉴",
	["Menú y bolsas"] = "메뉴와 가방",
	["Mercancías generales"] = "잡화",
	["Meta cumplida"] = "목표 달성",
	["Meta cumplida (%d de %d)"] = "목표 달성 (%d / %d)",
	["Metas de pesca"] = "낚시 목표",
	["Mi configuración"] = "내 설정",
	["Mi entrenador"] = "내 상급자",
	["Mi oreja derecha se para sola cuando alguien dice «salchicha». Pruébalo."] = "누가 «소시지»라고 하면 제 오른쪽 귀가 저절로 서요. 해 보세요.",
	["Mi panza hizo un ruido. No fui yo, fue la panza."] = "배에서 꼬르륵 소리가 났어요. 제가 아니라 배가 그랬어요.",
	["Mi plan"] = "내 계획",
	["Mi plan perfecto: una buena cacería y luego salchichas junto a la fogata."] = "완벽한 계획: 멋진 사냥 다음엔 모닥불 옆에서 소시지.",
	["Mi plan · %s"] = "내 계획 · %s",
