	["Mi primera montura"] = "내 첫 탈것",
	["Mi propio plan"] = "나만의 계획",
	["Mi ruta"] = "내 경로",
	["Mi ruta: hacer oro"] = "내 경로: 골드 벌기",
	["Mi ruta: subir rápido"] = "내 경로: 빠른 레벨업",
	["Mientras caminas o corres, tu tecla hace lo de siempre (con Espacio, saltar)."] = "걷거나 달리는 동안에는 키가 원래 하던 일을 합니다(스페이스면 점프).",
	["Mientras el corcho está en el agua, una línea fina con el tiempo, tu habilidad y lo último que sacaste."] = "찌가 물에 있는 동안 시간, 숙련도, 마지막으로 낚은 것을 보여 주는 얇은 줄.",
	["Mientras estás aquí"] = "여기 있는 동안",
	["Mientras estás aquí: %s"] = "여기 있는 김에: %s",
	["Mientras la haces"] = "하는 김에",
	["Mientras los druidas dormían en el Sueño Esmeralda, las Centinelas de Tyrande cuidaron solas los bosques de Kalimdor."] = "드루이드들이 에메랄드의 꿈에서 잠든 동안, 티란데의 파수병들이 홀로 칼림도어의 숲을 지켰어요.",
	["Mientras más alto el nivel de las bestias, mejor el cuero que sueltan."] = "짐승의 레벨이 높을수록 더 좋은 가죽이 나와요.",
	["Mientras más nivel tenga la bestia, más habilidad te pide para desollarla."] = "짐승의 레벨이 높을수록 무두질에 더 높은 숙련도가 필요해요.",
	["Mientras pescas"] = "낚시하는 동안",
	["Mientras pescas se ve solo el mundo y la barra de pesca. Nunca en combate: al empezar uno, todo vuelve."] = "낚시하는 동안에는 세상과 낚시 바만 보입니다. 전투 중에는 절대 아니며, 전투가 시작되면 모두 돌아옵니다.",
	["Mientras pescas, el juego se sigue oyendo aunque estés en otra ventana."] = "낚시하는 동안에는 다른 창에 있어도 게임 소리가 계속 들립니다.",
	["Mientras tenga la maldición, cura antes de que la vida baje mucho."] = "저주가 걸려 있는 동안에는 생명력이 많이 떨어지기 전에 미리 치유하세요.",
	["Mientras, junta el oro: con la equitación y la montura se va casi todo."] = "그동안 골드를 모으세요. 타기 숙련과 탈것에 거의 다 들어갑니다.",
	["Mil y un peces"] = "천하고도 한 마리",
	["Mina, herboriza, pesca en un banco o abre un cofre: aquí verás cuánto, qué te dio cada nodo y en qué zona."] = "채광, 약초 채집, 물고기 떼 낚시, 상자 열기: 얼마나, 각 지점에서 무엇을, 어느 지역에서 얻었는지 여기에 표시됩니다.",
	["Minas, hierbas y tesoros en tu mapa"] = "지도에 광석, 약초, 보물",
	["Minería"] = "채광",
	["Minería, hierbas, pesca y tesoros en tu mapa y minimapa, con rutas de farmeo e historial."] = "채광, 약초, 낚시, 보물을 지도와 미니맵에 표시하고, 파밍 경로와 기록도 제공합니다.",
	["Minimapa"] = "미니맵",
	["Minimapa cuadrado"] = "사각형 미니맵",
	["Minutos entre consejos"] = "조언 사이 간격(분)",
	["Minutos entre historias"] = "이야기 사이 간격(분)",
	["Mira a sus jefes y sus consejos antes de cada pelea."] = "전투마다 미리 우두머리와 공략을 확인하세요.",
	["Mira en la Enciclopedia de dónde sale."] = "백과사전에서 어디서 나오는지 확인하세요.",
	["Mira la línea de tiempo: llegan tres ataques de prueba"] = "타임라인을 보세요. 테스트 공격 세 개가 옵니다",
	["Mira las bolsas o el banco de otro de tus personajes."] = "다른 캐릭터의 가방이나 은행을 봅니다.",
	["Mira tus retos en el Legado del juego"] = "게임의 유산에서 내 도전 확인",
	["Mis planes"] = "내 계획",
	["Mis planes: la flecha va sola al siguiente lugar"] = "내 계획: 화살표가 다음 장소로 자동으로 이동",
	["Mis rutas"] = "내 경로",
	["Misceláneo"] = "기타",
	["Misiles arcanos: daño constante que no se interrumpe fácil."] = "신비한 화살: 쉽게 끊기지 않는 꾸준한 피해.",
	["Misiones"] = "퀘스트",
	["Misiones de pesca"] = "낚시 퀘스트",
