	["Misiones que da"] = "주는 퀘스트",
	["Misiones que dejan dinero u objetos que se venden bien."] = "골드나 잘 팔리는 아이템을 주는 퀘스트입니다.",
	["Misiones que dejan dinero y materiales de tu profesión para vender."] = "돈을 주는 퀘스트와 팔 수 있는 내 전문 기술 재료.",
	["Misiones que dejan dinero y materiales para vender."] = "골드와 팔 수 있는 재료를 주는 퀘스트입니다.",
	["Misiones que dejan dinero y materiales que se venden bien."] = "돈을 주는 퀘스트와 잘 팔리는 재료.",
	["Misiones que empiezan aquí"] = "여기서 시작하는 퀘스트",
	["Misiones que piden derrotarlo"] = "처치해야 하는 퀘스트",
