	["Misiones que recibe"] = "제출받는 퀘스트",
	["Misiones semanales"] = "주간 퀘스트",
	["Misiones solo para tu clase que dan un objeto o una habilidad única."] = "고유 아이템이나 기술을 주는 내 직업 전용 퀘스트입니다.",
	["Misiones y monstruos por tu cuenta, sin depender de nadie."] = "누구에게도 기대지 않고 혼자 퀘스트와 몬스터를 처리합니다.",
	["Misiones: %s"] = "퀘스트: %s",
