	["Modo historia: %d jefes por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "스토리 모드: 발견할 우두머리 %d. 처치해야 이름과 전리품이 보입니다(설정에서 끌 수 있음).",
	["Modo historia: 1 jefe por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "스토리 모드: 발견할 우두머리 1. 처치해야 이름과 전리품이 보입니다(설정에서 끌 수 있음).",
	["Modo limpio"] = "깔끔 모드",
