	["Moviendo"] = "이동 중",
	["Mucho daño con tu arma a distancia: disparos fuertes antes de que el monstruo llegue."] = "원거리 무기로 큰 피해: 몬스터가 다가오기 전에 강한 사격을 퍼붓습니다.",
	["Mucho maná y hechizos arcanos potentes: el mago que menos descansa."] = "많은 마나와 강력한 비전 주문: 가장 적게 쉬는 마법사입니다.",
	["Mucho tiempo sin verte, %s. Repasa tus misiones antes de salir."] = "오랜만이에요, %s. 나가기 전에 퀘스트를 살펴봐요.",
	["Muchos"] = "많이",
	["Muchos enemigos duermen a un jugador: no es grave, el sueño se quita solo."] = "많은 적이 플레이어를 재웁니다. 위험하지 않고 저절로 풀립니다.",
	["Muchos: consejos del momento y de vez en cuando uno de Alfa. Pocos: menos seguido. Solo importantes: al morir, al subir de nivel y en tus logros."] = "많이: 상황에 맞는 조언과 가끔 Alfa에 관한 조언. 조금: 덜 자주. 중요한 것만: 죽었을 때, 레벨이 올랐을 때, 업적을 이뤘을 때.",
	["Muchísima amenaza en un golpe."] = "한 번의 공격으로 엄청난 위협 수준.",
	["Muelles y torres de zepelín, con a dónde van."] = "선착장과 비행선 탑, 그리고 행선지입니다.",
	["Muertes"] = "죽음",
	["Muerto"] = "죽음",
	["Muestra la ventana de guía y la flecha, y cierra esta ventana para que las veas."] = "가이드 창과 화살표를 표시하고, 잘 보이도록 이 창을 닫습니다.",
	["Muestra la vida en número, debajo del nombre."] = "생명력을 이름 아래에 숫자로 표시합니다.",
	["Muestra lo que aún no exploras, con un tono más frío para distinguirlo."] = "아직 탐험하지 않은 곳을 차가운 색조로 구분해 보여 줍니다.",
	["Muestra un aviso de ejemplo para que veas dónde sale."] = "알림이 어디에 뜨는지 보이도록 예시 알림을 띄웁니다.",
	["Muestra un ícono encima del corcho: así sabes que tu tecla lo va a recoger."] = "찌 위에 아이콘을 표시합니다. 아이콘이 보이면 단축키로 낚아 올릴 수 있습니다.",
	["Mueve tus marcos"] = "프레임 옮기기",
	["Mundo"] = "월드",
	["Munición"] = "탄약",
	["Muradin Barbabronce acompañó a Arthas a Rasganorte. Cuando Arthas tomó la espada, un trozo de hielo golpeó a Muradin y lo dieron por muerto."] = "무라딘 브론즈비어드는 아서스와 노스렌드에 갔어요. 아서스가 검을 집었을 때 얼음 조각이 무라딘을 덮쳐, 모두 그가 죽었다고 여겼어요.",
	["Muradin Barbabronce le enseñó a Arthas a pelear cuando el príncipe era joven."] = "무라딘 브론즈비어드는 왕자가 어렸을 때 아서스에게 싸움을 가르쳤어요.",
	["Muro de escudo dura más."] = "방패의 벽이 더 오래 지속됩니다.",
	["Muro de escudo dura más: te salva en los jefes."] = "방패의 벽이 더 오래 지속되어 우두머리 전투에서 목숨을 구해 줍니다.",
	["Muy pronto"] = "곧 공개",
	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "표시하거나 숨깁니다. 단축키나 /alfa guia로도 할 수 있습니다.",
	["Muévete a las zonas de nivel 10 a 20. Las lombrices ayudan a que no se escapen. Pide el rango Experto desde 125."] = "10~20레벨 지역으로 옮기세요. 지렁이가 있으면 덜 놓칩니다. 125부터 전문 단계를 배우세요.",
	["Muñecas"] = "손목",
	["Márcala cuando la hagas"] = "하고 나서 표시하세요",
	["Más"] = "더 보기",
	["Más Abrumar gracias a Desgarrar."] = "분쇄 덕분에 제압이 늘어납니다.",
	["Más Golpes heroicos: más daño por pelea."] = "영웅의 일격을 더 많이: 전투마다 피해가 늘어납니다.",
	["Más adelante"] = "나중에",
	["Más adelante eliges entre ingeniería gnómica y goblin: los inventos gnómicos fallan a veces de forma muy graciosa, y los goblin explotan más."] = "나중에 노움 기계공학과 고블린 기계공학 중 하나를 골라요. 노움 장치는 가끔 아주 웃기게 고장 나고, 고블린 장치는 더 자주 터져요.",
	["Más adelante eliges especialidad: de escamas de dragón, elemental o tribal."] = "나중에 전문 분야를 골라요: 용비늘, 원소, 부족 가죽세공.",
	["Más adelante eliges especialidad: forjador de armaduras o armero, y los armeros, entre espadas, mazas y hachas."] = "나중에 전문 분야를 골라요: 방어구제작자나 무기제작자, 그리고 무기제작자는 도검, 둔기, 도끼 중에서 골라요.",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "체력과 안전성이 높습니다. 처치는 조금 느리지만 거의 죽지 않습니다.",
	["Más alto, atraviesa objetos más grandes antes de acercarse."] = "높일수록 카메라가 다가오기 전에 더 큰 사물도 통과합니다.",
	["Más alto, los objetos lejanos tardan más en desaparecer."] = "높일수록 먼 사물이 더 늦게 사라집니다.",
	["Más alto, más nítido. Demasiado puede marcar bordes y brillos."] = "높일수록 선명해집니다. 너무 높으면 가장자리와 빛이 도드라질 수 있습니다.",
	["Más alto, ves más a los lados."] = "높일수록 옆이 더 많이 보입니다.",
	["Más amenaza."] = "위협 수준 증가.",
	["Más amenaza: los monstruos se quedan contigo."] = "위협 수준 증가: 몬스터가 나에게서 떨어지지 않습니다.",
	["Más baja, la niebla se ve más ligera y cuesta menos."] = "낮출수록 안개가 옅어 보이고 부담이 줄어듭니다.",
	["Más bajo, se siguen viendo objetos pequeños a lo lejos."] = "낮출수록 먼 곳의 작은 사물이 계속 보입니다.",
	["Más crítico en Abrumar, ideal contra pícaros que esquivan."] = "제압의 치명타 증가: 회피하는 도적에게 딱 좋습니다.",
	["Más crítico."] = "치명타 증가.",
	["Más daño con dos manos."] = "양손 무기 피해 증가.",
	["Más daño con el tiempo."] = "지속 피해 증가.",
	["Más daño con escudo."] = "방패를 들었을 때 피해 증가.",
	["Más daño con escudo: lo que hace que Protección suba bien."] = "방패를 들었을 때 피해 증가: 방어 전문이 레벨을 잘 올리게 해 줍니다.",
	["Más daño con tu arma de dos manos, que es la que usas."] = "지금 쓰는 양손 무기의 피해가 늘어납니다.",
	["Más daño con tu arma de dos manos."] = "양손 무기의 피해가 늘어납니다.",
	["Más daño de sangrado; abre Heridas profundas."] = "출혈 피해 증가. 깊은 상처를 엽니다.",
	["Más daño mientras llevas escudo."] = "방패를 들고 있는 동안 피해가 늘어납니다.",
	["Más daño y más riesgo. Matas rápido, pero un error se paga caro."] = "피해도 위험도 더 큽니다. 빨리 처치하지만 실수 하나가 크게 돌아옵니다.",
	["Más de mi gente"] = "내 종족 이야기 더",
	["Más defensa desde el principio."] = "처음부터 방어 숙련 증가.",
	["Más defensa: te golpean y te hacen crítico menos seguido."] = "방어 숙련 증가: 공격과 치명타를 덜 맞습니다.",
	["Más defensa: te hacen menos críticos."] = "방어 숙련 증가: 치명타를 덜 맞습니다.",
	["Más distancia, sombras finas y agua con reflejos."] = "더 먼 거리, 섬세한 그림자, 반사되는 물.",
	["Más en Calidad de vida"] = "편의 기능에서 더 보기",
	["Más espacio en el banco"] = "은행 공간 늘리기",
	["Más golpe crítico para todo lo que haces."] = "모든 행동의 치명타 증가.",
	["Más golpe crítico, que también te da más ira."] = "치명타 증가: 분노도 더 얻습니다.",
	["Más golpe crítico."] = "치명타 증가.",
	["Más golpes bloqueados con el escudo, y cada bloqueo te da ira."] = "방패로 막는 공격이 늘고, 막을 때마다 분노를 얻습니다.",
	["Más guías"] = "가이드 더 보기",
	["Más ira al cargar."] = "돌진할 때 분노 증가.",
	["Más ira al cargar: tu primer golpe llega antes."] = "돌진할 때 분노 증가: 첫 공격이 더 빨리 들어갑니다.",
	["Más ira al empezar la pelea."] = "전투 시작 시 분노 증가.",
	["Más ira al empezar."] = "시작할 때 분노 증가.",
	["Más ira por cada golpe, sobre todo con armas rápidas."] = "공격마다 분노 증가, 특히 빠른 무기에서.",
	["Más ira por cada golpe: más Golpe heroico y Golpe mortal."] = "공격마다 분노 증가: 영웅의 일격과 죽음의 일격을 더 씁니다.",
	["Más ira por golpe."] = "공격마다 분노 증가.",
	["Más ira por golpe: más habilidades seguidas."] = "공격마다 분노 증가: 기술을 연달아 더 씁니다.",
	["Más lugares"] = "다른 장소",
	["Más maná y algo de crítico con hechizos."] = "마나 증가와 약간의 주문 극대화.",
	["Más opciones"] = "추가 설정",
	["Más opciones de Mundo"] = "월드 옵션 더 보기",
	["Más opciones de apariencia"] = "모양 옵션 더 보기",
	["Más para tu personaje"] = "내 캐릭터를 위한 추가 정보",
	["Más pasto"] = "풀 더 많이",
	["Más pasto, más horizonte, niebla ligera y rayos de sol, sin pedirle de más a tu PC. Se deshace con un clic en /alfa paisaje."] = "풀은 더 많이, 시야는 더 멀리, 옅은 안개와 햇살까지. PC에 무리를 주지 않습니다. /alfa paisaje에서 클릭 한 번으로 되돌릴 수 있습니다.",
	["Más pasto, más horizonte, niebla ligera y rayos de sol. Bonito sin pedir de más."] = "풀은 더 많이, 시야는 더 멀리, 옅은 안개와 햇살. 부담 없이 아름답게.",
	["Más poder de ataque para tu grupo."] = "파티의 전투력을 높입니다.",
	["Más sangrado; abre Heridas profundas."] = "출혈 증가. 깊은 상처를 엽니다.",
	["Más velocidad de ataque: mantenlo puesto."] = "공격 속도 증가: 계속 유지하세요.",
	["Más vida: aguantas más golpes antes de tener que comer o descansar."] = "생명력 증가: 먹거나 쉬기 전까지 더 많은 공격을 버팁니다.",
	["Mínimas"] = "최소",
	["Mínimo"] = "최소",
	["Músculos"] = "근육 자랑",
	["Música mientras pescas"] = "낚시 중 음악",
	["Nada coincide"] = "일치하는 항목 없음",
	["Nada con ese nombre"] = "그 이름으로 찾은 것 없음",
	["Nada con ese nombre."] = "그 이름으로 찾은 것이 없습니다.",
	["Nada de esto le sirve a tu clase"] = "내 직업에 맞는 것이 없음",
	["Nada en este grupo"] = "이 그룹에는 아무것도 없음",
	["Nada nuevo"] = "새로운 것 없음",
	["Nada nuevo por aprender"] = "새로 배울 것 없음",
	["Nada nuevo por aprender."] = "새로 배울 것이 없습니다.",
	["Nada por aquí"] = "여기에는 아무것도 없음",
	["Nada que aplicar"] = "적용할 것 없음",
	["Nada que entregar todavía"] = "아직 제출할 것 없음",
	["Nada que recoger"] = "받을 것 없음",
	["Nada que reparar"] = "수리할 것 없음",
	["Nada que vender por ahora: lo que llevas sirve o vale más guardado."] = "지금은 팔 것이 없습니다. 가진 것이 쓸모 있거나 보관하는 편이 낫습니다.",
	["Nada: todo esto lo haces tú."] = "없음: 모두 직접 합니다.",
	["Nadie a la vista tiene ubicación ahora: en una instancia o desconectados. Cuando vuelvan al mundo, aparecen aquí y en tu mapa."] = "지금 보이는 사람 중 위치가 있는 사람이 없습니다. 인스턴스 안이거나 접속하지 않았습니다. 월드로 돌아오면 여기와 지도에 나타납니다.",
	["Nadie de la manada a la vista"] = "보이는 무리 없음",
	["Naranja"] = "주황색",
	["Nat Pagle, el pescador legendario, vive en una isla del Marjal Revolcafango."] = "전설적인 낚시꾼 냇 페이글은 먼지진흙 습지대의 섬에 살아요.",
	["Nat Pagle, el pescador más famoso, vive en una isla del marjal; sus misiones son para pescadores pacientes."] = "가장 유명한 낚시꾼 냇 페이글은 습지대 섬에 살아요. 그의 퀘스트는 인내심 있는 낚시꾼을 위한 거예요.",
	["Nat Pagle, en el Marjal Revolcafango, te pide cuatro peces raros: con su misión aprendes el rango Artesano."] = "먼지진흙 습지대의 냇 페이글이 희귀한 물고기 네 마리를 부탁합니다. 그 퀘스트로 장인 단계를 배웁니다.",
	["Naxxramas, la necrópolis de Kel'Thuzad, flota sobre estas tierras como una sombra."] = "켈투자드의 강령의 성채 낙스라마스가 그림자처럼 이 땅 위에 떠 있어요.",
	["Necesita la base de misiones (página Misiones)."] = "퀘스트 데이터베이스가 필요합니다(퀘스트 진행 페이지).",
	["Necesita las rutas a pie de Alfa (Alfa_Nav), que se cargan solas con «Seguir caminos reales» encendido."] = "Alfa 도보 경로(Alfa_Nav)가 필요합니다. «실제 길 따라 걷기»를 켜면 자동으로 불러옵니다.",
	["Necesita un monitor HDR"] = "HDR 모니터 필요",
	["Necesitas %s"] = "%s 필요",
	["Necesitas %s con %s"] = "필요: %s, %s",
	["Necesitas %s para esta cadena: apréndela con un instructor."] = "이 연계 퀘스트에는 %s 필요: 상급자에게 배우세요.",
	["Necesitas %s para juntarlo: apréndela con un instructor de profesiones."] = "채집하려면 %s이(가) 필요합니다. 기술 전문가에게 배우세요.",
	["Neltharion, el Guardián de la Tierra, escuchó los susurros de los dioses antiguos y se convirtió en Alamuerte."] = "대지의 수호자 넬타리온은 고대 신의 속삭임에 귀를 기울였고 데스윙이 되었어요.",
	["Ner'zhul abrió varios portales en Draenor y la magia desgarró el planeta. Lo que quedó flota en la nada y se llama Terrallende."] = "넬쥴이 드레노어에 여러 차원문을 열자 마력이 행성을 찢어 놓았어요. 남은 조각은 허공에 떠 있고, 아웃랜드라 불려요.",
	["Nethergarde es un bastión de magos de la Alianza que vigila el Portal Oscuro, por si algo vuelve a cruzar."] = "황천의 요새는 어둠의 문을 감시하는 얼라이언스 마법사들의 거점이에요. 다시 무언가 넘어올까 봐요.",
	["Ni uno se escapa"] = "한 마리도 놓치지 않는다",
	["Niebla"] = "안개",
	["Niebla en interiores"] = "실내 안개",
	["Niebla volumétrica"] = "입체 안개",
	["Ninguna de tus recetas deja ganancia con los precios que tienes."] = "현재 가격으로는 이득이 나는 제조법이 없습니다.",
	["Ninguna guía cumple estos filtros. Quita alguno para ver más."] = "이 필터에 맞는 가이드가 없습니다. 필터를 하나 빼면 더 볼 수 있습니다.",
	["Ninguna receta deja ganancia"] = "이익이 나는 제조법 없음",
	["Ninguno coincide"] = "일치하는 것 없음",
	["Ninguno conocido para tu facción"] = "내 진영에 알려진 곳 없음",
	["Ninguno puesto"] = "세운 토템 없음",
	["Ningún oficial respondió ahora. %s"] = "지금은 응답한 관리자가 없습니다. %s",
	["Nitidez"] = "선명도",
	["Niv. %d"] = "%d레벨",
	["Nivel"] = "레벨",
	["Nivel %d"] = "레벨 %d",
	["Nivel %d: %d hechizos nuevos para aprender"] = "%d레벨: 배울 새 주문 %d개",
	["Nivel %d: un hechizo nuevo para aprender"] = "%d레벨: 배울 새 주문 1개",
	["Nivel %d–%d"] = "%d~%d레벨",
	["Nivel %s"] = "%s레벨",
	["Nivel 40, el oro, tu entrenador de equitación y aprender a montar."] = "40레벨, 골드, 탈것 조련사, 타기 배우기.",
	["Nivel de objeto"] = "아이템 레벨",
	["Nivel de objeto %d"] = "아이템 레벨 %d",
	["Nivel máximo"] = "최고 레벨",
	["Niveles"] = "레벨",
	["Niveles %d–%d"] = "%d~%d레벨",
	["Niveles %s"] = "레벨 %s",
	["Niveles %s, en %s."] = "%s레벨, %s.",
	["Niveles arriba del tuyo"] = "내 레벨보다 높은 레벨",
	["Niveles de zona"] = "지역 레벨",
	["Niveles, misiones, raros, mazmorras y servicios de cada zona."] = "지역마다 레벨, 퀘스트, 희귀, 던전, 편의 시설.",
	["No"] = "끄기",
	["No armé el plan"] = "계획을 만들지 못했습니다",
	["No armé la guía"] = "가이드를 만들지 못했습니다",
	["No armé tu ruta"] = "경로를 만들지 못했습니다",
	["No busca apagar tu cerebro ni jugar por ti: busca que entiendas y disfrutes un juego de hace años, a tu ritmo."] = "머리를 끄게 하거나 대신 플레이하려는 것이 아닙니다. 오래된 게임을 이해하고 내 속도로 즐기도록 돕습니다.",
	["No cambiar: %s"] = "바꾸지 않음: %s",
	["No conozco ese lugar. Prueba: vuelo, posada, reparar, banco, buzón, subasta, entrenador, oficio, vendedor, comida, componentes o establo."] = "모르는 장소입니다. 이렇게 입력해 보세요: vuelo, posada, reparar, banco, buzón, subasta, entrenador, oficio, vendedor, comida, componentes, establo (비행, 여관, 수리, 은행, 우체통, 경매장, 상급자, 전문 기술, 상인, 음식, 재료, 야수 관리인).",
	["No conozco ese preajuste."] = "모르는 프리셋입니다.",
	["No conozco la entrada de esta mazmorra"] = "이 던전의 입구를 모릅니다",
	["No conozco la profesión «%s»."] = "모르는 전문 기술입니다: «%s».",
	["No conozco ningún lugar de «%s» para tu facción."] = "내 진영에서 아는 «%s» 장소가 없습니다.",
	["No cupieron %d: el banco está lleno. Compra otra casilla o pon una bolsa más grande."] = "%d개가 들어가지 않았습니다. 은행이 가득 찼습니다. 칸을 더 사거나 더 큰 가방을 넣으세요.",
	["No disponible"] = "사용할 수 없음",
	["No disponible: %s"] = "사용 불가: %s",
	["No encontramos a \"%s\" en tu grupo ni entre quienes comparten su ubicación."] = "파티나 위치 공유 중인 사람 중에 \"%s\" 님을 찾지 못했습니다.",
	["No encontramos nada"] = "찾은 것이 없음",
	["No encontré cómo llegar a esa misión."] = "그 퀘스트까지 가는 길을 찾지 못했습니다.",
	["No encontré misiones de clase para ti ahora."] = "지금은 내 직업 퀘스트를 찾지 못했습니다.",
	["No encontré una mazmorra llamada «%s»."] = "«%s»(이)라는 던전을 찾지 못했습니다.",
	["No entregué %s: pide materiales de oficio. Entrégala tú si quieres."] = "%s 퀘스트를 제출하지 않았습니다: 전문 기술 재료가 필요합니다. 원하면 직접 제출하세요.",
	["No entregué %s: pide oro o monedas. Entrégala tú si quieres."] = "%s 퀘스트를 제출하지 않았습니다: 골드나 화폐가 필요합니다. 원하면 직접 제출하세요.",
	["No es para ti"] = "나에게 맞지 않음",
	["No es para tu clase"] = "내 직업용 아님",
	["No es para tu raza"] = "내 종족용이 아님",
	["No está al salir Forever. Cuando llegue, lo que ganes ahí cuenta en los otros modos, pero no al revés, y los retos de JcJ no se pueden hacer ahí."] = "Forever 출시 시점에는 없습니다. 나오면 거기서 얻은 것은 다른 모드에서도 인정되지만 반대는 안 되며, PvP 도전은 할 수 없습니다.",
	["No está en tu árbol"] = "내 트리에 없음",
	["No están en tu árbol y se saltan: %s."] = "내 트리에 없어 건너뜀: %s.",
	["No estás siguiendo a nadie."] = "아무도 따라가고 있지 않습니다.",
	["No gastes todo en equipo: aprender a montar a nivel 40 es la mejor inversión del camino."] = "장비에 다 쓰지 마세요. 40레벨에 타기를 배우는 게 길에서 가장 좋은 투자예요.",
	["No hay bancos de peces conocidos en esta zona: aquí se pesca en aguas abiertas."] = "이 지역에는 알려진 물고기 떼가 없습니다. 여기서는 탁 트인 물에서 낚습니다.",
	["No hay guías así"] = "그런 가이드가 없습니다",
	["No hay misiones para ti cerca de aquí. Prueba en el pueblo más cercano o sigue tu ruta."] = "근처에 맞는 퀘스트가 없습니다. 가장 가까운 마을로 가거나 경로를 따라가세요.",
	["No hay misiones que convenga dejar"] = "포기할 만한 퀘스트 없음",
	["No hay misiones que puedas tomar ahora: te llevo a la entrada."] = "지금 받을 수 있는 퀘스트가 없습니다. 입구로 안내합니다.",
	["No hay nada que comprar: o ya tienes todo lo del plan hasta tu nivel, o no tienes puntos libres."] = "찍을 것이 없습니다. 내 레벨까지의 계획을 이미 다 찍었거나 남은 포인트가 없습니다.",
	["No hay nodos conocidos en esta zona."] = "이 지역에 알려진 채집 지점이 없습니다.",
	["No hay prisa: el camino también se disfruta."] = "서두를 필요 없어요. 가는 길도 즐겨요.",
	["No hay un build exacto para %s y %s: este es el que más se parece."] = "%s, %s에 딱 맞는 빌드가 없어 가장 비슷한 빌드를 보여 줍니다.",
	["No hay un camino que Alfa pueda guiar para esto."] = "Alfa가 안내할 수 있는 길이 없습니다.",
	["No ignores los objetos verdes: si no te sirven, desencántalos o súbelos a la subasta."] = "녹색 아이템을 무시하지 마세요. 필요 없으면 마력 추출하거나 경매장에 올리세요.",
	["No la agregué"] = "추가하지 않았습니다",
	["No la usas"] = "사용 안 함",
	["No llevas chatarra para vender."] = "팔 잡동사니가 없습니다.",
	["No llevas juguetes ni consumibles de pesca. Lo que tenga que ver con pescar aparece aquí solo."] = "낚시 장난감이나 소비용품이 없습니다. 낚시와 관련된 것은 자동으로 여기에 나타납니다.",
	["No llevas nada de pesca. Compra una caña con un vendedor de suministros de pesca: la guía te dice dónde."] = "낚시용품이 하나도 없습니다. 낚시용품 상인에게서 낚싯대를 사세요. 가이드가 어디인지 알려 줍니다.",
	["No llevas nada para depositar con esa opción."] = "그 옵션으로 보관할 것이 없습니다.",
	["No llevas nada que convenga vender: guarda algo en el banco."] = "팔 만한 것이 없습니다. 은행에 보관하세요.",
	["No llevas nada que depositar"] = "보관할 것 없음",
	["No lo puedes usar todavía"] = "아직 쓸 수 없음",
	["No mostrar"] = "표시 안 함",
	["No muestra los ataques que todavía tardan mucho: la barra queda más limpia."] = "아직 한참 남은 공격은 표시하지 않아 막대가 더 깔끔해집니다.",
	["No muestra los ataques que ya deberían haber llegado y esperan su momento."] = "이미 올 때가 됐지만 시점을 기다리는 공격은 표시하지 않습니다.",
	["No pegaste nada."] = "아무것도 붙여 넣지 않았습니다.",
	["No pude armar esa guía"] = "그 가이드를 만들지 못했습니다",
	["No pude armar la ruta"] = "경로를 만들지 못했습니다",
	["No pude buscar ahora: inténtalo al salir de combate."] = "지금은 검색하지 못했습니다. 전투가 끝나면 다시 해 보세요.",
	["No pude cargar los datos del mundo de Alfa (%s)."] = "Alfa 월드 데이터를 불러오지 못했습니다(%s).",
	["No pude guardar esa meta: revisa lo que escribiste."] = "그 목표를 저장하지 못했습니다. 입력한 내용을 확인하세요.",
	["No pude leer dónde estás."] = "현재 위치를 읽지 못했습니다.",
	["No pude leer los datos del mundo de Alfa: vuelve a instalar Alfa."] = "Alfa 월드 데이터를 읽지 못했습니다. Alfa를 다시 설치하세요.",
	["No pude poner la flecha ahí."] = "그곳으로 화살표를 설정하지 못했습니다.",
	["No pude poner la flecha ahí. Inténtalo otra vez en un momento."] = "그곳으로 화살표를 설정하지 못했습니다. 잠시 후 다시 해 보세요.",
	["No pude preparar la ruta"] = "경로를 준비하지 못했습니다",
	["No pudimos unirnos al canal de la manada"] = "무리 채널에 들어가지 못했습니다",
	["No quedan puntos libres."] = "남은 포인트가 없습니다.",
	["No resaltarlo"] = "강조하지 않음",
	["No sabemos dónde está %s. Solo se puede seguir a tu grupo y a quien comparte su ubicación con Alfa."] = "%s 님의 위치를 알 수 없습니다. 파티원과 Alfa로 위치를 공유하는 사람만 따라갈 수 있습니다.",
	["No se aplicaron los talentos"] = "특성을 적용하지 못했습니다",
	["No se conoce de dónde sale."] = "출처를 모릅니다.",
	["No se conoce ningún Alfa más reciente. La app de CurseForge o la página de versiones lo dicen con seguridad."] = "알려진 새 Alfa가 없습니다. 확실히 알려면 CurseForge 앱이나 릴리스 페이지를 확인하세요.",
	["No se conoce su botín"] = "전리품 정보 없음",
	["No se encontró el chat."] = "대화창을 찾지 못했습니다.",
	["No se encontró la carpeta Alfa_Codex. Reinstala Alfa completo."] = "Alfa_Codex 폴더를 찾지 못했습니다. Alfa 전체를 다시 설치하세요.",
	["No se encontró nada mejor cerca de tu nivel. Vuelve a buscar al subir unos niveles."] = "내 레벨 근처에서 더 좋은 것을 찾지 못했습니다. 몇 레벨 오른 뒤 다시 찾아보세요.",
	["No se pudieron leer los datos del juego."] = "게임 데이터를 읽을 수 없습니다.",
	["No se pudo"] = "실패",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "Alfa Codex(아이템 데이터베이스)를 열 수 없습니다. Alfa Codex 애드온이 켜져 있는지 확인하세요.",
	["No se pudo armar la guía (%s)."] = "가이드를 만들 수 없습니다(%s).",
	["No se pudo armar la guía."] = "가이드를 만들지 못했습니다.",
	["No se pudo buscar el lugar más cercano."] = "가장 가까운 곳을 찾지 못했습니다.",
	["No se pudo comprar: %s"] = "찍지 못함: %s",
	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "스캔 결과를 읽을 수 없습니다. 나중에 다시 시도하세요.",
	["No se pudo marcar: falta el motor de Alfa."] = "표시할 수 없습니다: Alfa 엔진이 없습니다.",
	["No se pudo mostrar el banco del juego para comprar la casilla."] = "칸을 구입하기 위한 게임 은행을 표시할 수 없었어요.",
	["No se pudo probar ahora"] = "지금은 테스트할 수 없습니다",
	["No se puede dibujar el mapa continuo. El mapa del juego sigue funcionando con todas las capas de Alfa."] = "이어진 지도를 그릴 수 없습니다. 게임 지도는 Alfa의 모든 레이어와 함께 계속 작동합니다.",
	["No se puede en combate."] = "전투 중에는 할 수 없습니다.",
	["No se puede ordenar en combate."] = "전투 중에는 정렬할 수 없습니다.",
	["No se puede vender."] = "판매할 수 없습니다.",
	["No se pueden cambiar bolsas en combate."] = "전투 중에는 가방을 바꿀 수 없습니다.",
	["No se sabe en qué lugar está."] = "위치를 모릅니다.",
	["No se ve en pantalla. Tráela de vuelta cuando quieras (también con /alfa lya)."] = "화면에 보이지 않습니다. 언제든 다시 부르세요(/alfa lya로도).",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "광산에 항상 나오지는 않습니다. 보이면 좋은 전리품을 주는 추가 우두머리입니다.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "항상 있지는 않습니다. 암흑 고통을 거니 걸린 사람을 치유하세요.",
	["No sigues ninguna guía"] = "따라가는 가이드 없음",
	["No son para ti"] = "나에게 맞지 않음",
	["No sé de dónde sale este objeto."] = "이 아이템이 어디서 나오는지 모릅니다.",
	["No sé dónde se entrega"] = "제출 장소 모름",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "%s 퀘스트의 제출 장소를 몰라 경로에서 뺐습니다.",
	["No sé dónde se entrega %s: la saqué del plan."] = "%s 제출 장소를 몰라 계획에서 뺐습니다.",
	["No sé dónde se junta este material."] = "이 재료를 어디서 모으는지 모릅니다.",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "어디서 모으는지 모릅니다. 백과사전에서 어디서 나오는지 찾아보세요.",
	["No sé en qué zona estás."] = "현재 지역을 알 수 없습니다.",
	["No sé qué misión es."] = "어떤 퀘스트인지 모릅니다.",
	["No sé si alguien en Azeroth cocina salchichas como las de casa... pero si encuentras una receta, ¡me avisas!"] = "아제로스에 집에서 먹던 것 같은 소시지를 만드는 사람이 있을지 모르겠어요... 요리법을 찾으면 알려 줘요!",
	["No sé si se puede tomar"] = "받을 수 있는지 모름",
	["No te alcanza"] = "돈 부족",
	["No tienes cebos. Los venden los vendedores de suministros de pesca; la guía dice cuáles sirven a tu habilidad."] = "미끼가 없습니다. 낚시용품 상인이 팔며, 가이드가 내 숙련도에 맞는 것을 알려 줍니다.",
	["No tienes demonio: el abisario aguanta los golpes por ti."] = "악마가 없습니다. 보이드워커가 대신 공격을 받아 냅니다.",
	["No tienes demonio: invoca uno antes de pelear."] = "악마가 없습니다. 전투 전에 소환하세요.",
	["No tienes demonio: invócalo al instante, aun peleando."] = "악마가 없습니다. 전투 중이라도 즉시 소환하세요.",
	["No tienes marcadores en el mapa de Alfa. Pon uno en el mapa y vuelve aquí."] = "Alfa 지도에 마커가 없습니다. 지도에 하나 놓고 다시 오세요.",
	["No tienes mascota: llámala."] = "소환수가 없습니다. 부르세요.",
	["No tienes mascota: si murió, revívela."] = "소환수가 없습니다. 죽었다면 되살리세요.",
	["No tienes misiones para este plan con ese filtro."] = "그 필터로는 이 계획에 넣을 퀘스트가 없습니다.",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca en el nivel %d."] = "남은 포인트가 없습니다. 계획의 다음 특성(%s)은 %d레벨에 찍습니다.",
	["No tienes un sello puesto: ponte uno."] = "문장이 없습니다. 문장을 거세요.",
	["No volver a mostrar"] = "다시 보지 않기",
