	["Nombre del plan"] = "계획 이름",
	["Nombres de zona"] = "지역 이름",
	["Normal"] = "보통",
	["Nota de entrenar en la ventana de la guía"] = "가이드 창에 수련 안내 표시",
	["Nota de entrenar en tu guía"] = "가이드의 수련 메모",
	["Nota libre"] = "자유 메모",
	["Novedades de Alfa %s"] = "Alfa %s 새 소식",
	["Nozdormu, el Atemporal, cuida el curso del tiempo. Dicen que conoce el día de su propia muerte, y aun así sigue con su deber."] = "영원의 노즈도르무는 시간의 흐름을 지켜요. 자신이 죽는 날을 알면서도 계속 임무를 다한대요.",
	["Nuestra manada en Discord: ayuda, avisos y reportes. Haz clic en el enlace y cópialo con Ctrl+C."] = "Discord의 우리 무리: 도움, 소식, 제보. 링크를 클릭하고 Ctrl+C로 복사하세요.",
	["Nueva ruta vacía"] = "빈 새 경로",
