	["Objeto %d"] = "아이템 %d",
	["Objeto %s"] = "아이템 %s",
	["Objeto de misión: úsalo con su botón o con tu tecla de paso."] = "퀘스트 아이템: 아이템 버튼이나 단계 단축키로 쓰세요.",
	["Objeto del mundo"] = "필드 오브젝트",
	["Objetos"] = "아이템",
