	["Pescar %s: llevas %s"] = "%s 동안 낚시: 지금까지 %s",
	["Pescar un pez en particular…"] = "특정 물고기 낚기…",
	["Pescar: lanzar y recoger"] = "낚시: 던지기 및 낚아 올리기",
