	["Pescaste %d."] = "%d마리 낚았습니다.",
	["Pesos de %s activos: las flechas de mejora ya los usan."] = "%s 가중치 켜짐: 향상 화살표가 이미 사용 중입니다.",
	["Pestaña nueva"] = "새 탭",
	["Pestañas con el estilo"] = "스타일을 입힌 탭",
	["Pez"] = "물고기",
	["Picadura de serpiente: daño con el tiempo."] = "독사 쐐기: 지속 피해.",
