	["Placas de nombre"] = "이름표",
	["Placas de tótems enemigos"] = "적 토템 이름표",
	["Plaga devoradora: daño fuerte con el tiempo, cada vez que esté lista."] = "파멸의 역병: 강한 지속 피해. 준비될 때마다 쓰세요.",
	["Plan en marcha"] = "계획 진행 중",
