	["Plantillas"] = "템플릿",
	["Plegarla sola"] = "자동으로 접기",
	["Pobre"] = "하급",
	["Poco común"] = "고급",
	["Poco probable (%d)"] = "확률 낮음 (%d)",
	["Pocos"] = "적음",
	["Pocos lugares de %s en %s"] = "%s 채집 장소가 적음: %s",
	["Pocos precios"] = "가격 적음",
	["Poder a distancia"] = "원거리 전투력",
	["Poder arcano: más daño un rato, mientras te sobre maná."] = "신비의 마법 강화: 마나가 넉넉한 동안 잠시 피해가 늘어납니다.",
	["Poder con hechizos"] = "주문력",
	["Poder de ataque"] = "전투력",
	["Poder de ataque a distancia"] = "원거리 전투력",
	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "상대에게 닿자마자 무력화를 걸고 계속 유지하세요.",
	["Pon ahora"] = "지금 찍기",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "지속 피해 주문을 모두 걸고 악마가 버티게 하세요.",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "몬스터가 다가오기 전에 보호막과 지속 피해를 걸어 두세요.",
	["Pon tu piedra de hogar en la posada donde tengas más misiones."] = "퀘스트가 가장 많은 곳의 여관에 귀환석을 설정하세요.",
	["Pon tu tótem abrasador: dispara al enemigo por ti."] = "불타는 토템을 세우세요. 대신 적을 공격합니다.",
	["Pon tus tótems al empezar cada pelea grande."] = "큰 전투를 시작할 때마다 토템을 세우세요.",
	["Pon un cebo 10 veces."] = "미끼를 10번 다세요.",
	["Pon un tótem antes de empezar la pelea."] = "전투를 시작하기 전에 토템을 세우세요.",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "전투를 시작하기 전에 덫을 놓고 몬스터를 그쪽으로 유인하세요.",
	["Pon venenos en tus armas siempre."] = "무기에 항상 독을 발라 두세요.",
	["Pone el enlace en el chat."] = "대화창에 링크를 넣습니다.",
	["Pone la flecha ahí."] = "그곳에 화살표를 놓습니다.",
	["Pone los marcos donde estaban al instalar Alfa."] = "프레임을 Alfa 설치 때의 위치로 되돌립니다.",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "타임라인에 테스트 공격 세 개를 넣어 어디에 나오는지 보여 줍니다. 자동으로 지워집니다. 옮기려면 게임 메뉴(Esc) > 편집 모드.",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "받는 치유량을 줄이는 저주를 겁니다. 직업이 해제할 수 있으면 해제하세요.",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "약화 저주와 서서히 타는 불을 겁니다. 가능하면 저주를 해제하세요.",
	["Poner el cebo"] = "미끼 달기",
	["Poner la flecha aquí"] = "여기에 화살표 놓기",
	["Ponerme el equipo de pesca"] = "낚시 장비 입기",
	["Ponerme lo de pesca"] = "낚시용 장비 입기",
	["Ponerme una meta"] = "목표 정하기",
	["Ponerte la recompensa si es mejor"] = "더 좋은 보상은 착용",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "파티 반대쪽으로 돌려세워 공격이 나에게만 맞게 하세요.",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "파티 반대쪽으로 돌려세우고 버티세요. 전투는 짧습니다.",
	["Ponlos al empezar a pelear."] = "전투를 시작할 때 세우세요.",
	["Ponte la caña primero."] = "먼저 낚싯대를 장착하세요.",
	["Ponte un escudo antes de empezar cada pelea."] = "전투를 시작할 때마다 보호막을 거세요.",
	["Ponte una meta: un pez, capturas, tiempo o valor."] = "목표를 정하세요: 물고기, 낚은 수, 시간, 가치.",
	["Por Costa Oscura anda un explorador de la Liga muy despistado, que siempre necesita que alguien le eche la mano."] = "어둠의 해안에는 늘 누군가 도와줘야 하는 아주 덜렁대는 연맹 탐험가가 돌아다녀요.",
	["Por ahora, guárdalo todo"] = "지금은 모두 보관하세요",
	["Por bolsa"] = "가방별",
	["Por categorías"] = "분류별",
	["Por clase"] = "직업별",
	["Por debajo de tu nivel"] = "내 레벨보다 낮음",
	["Por defecto"] = "기본값",
	["Por dónde sale: %s"] = "보내는 경로: %s",
	["Por dónde se pasa a otra zona (caminos, pasos, túneles y puertas), con una flecha hacia ella y su rango de niveles. Se ven al acercarte a una zona."] = "다른 지역으로 넘어가는 곳(길, 고개, 터널, 문)을 그 지역 방향 화살표와 레벨 범위로 표시합니다. 지역을 확대하면 보입니다.",
	["Por ejemplo: primero un objeto, luego 10 de oro, luego subir cocina y al final el banco."] = "예: 먼저 아이템, 다음에 10골드, 그다음 요리 숙련, 마지막으로 은행.",
	["Por eso empezamos con esta configuración: para que cada quien arme su experiencia a su gusto. Todo se puede cambiar después."] = "그래서 이 설정으로 시작합니다. 누구나 자기 취향대로 경험을 꾸밀 수 있도록요. 모두 나중에 바꿀 수 있습니다.",
	["Por estas montañas se llega al Valle de Alterac, donde la Guardia Pico Tormenta y el clan Lobo Gélido pelean sin descanso."] = "이 산을 넘으면 알터랙 계곡이에요. 스톰파이크 경비대와 서리늑대 부족이 쉬지 않고 싸우는 곳이죠.",
	["Por grupo"] = "파티별",
	["Por honor (JcJ)"] = "명예 (PvP)",
	["Por hora"] = "시간당",
	["Por la Alianza mandan Bolvar como regente en Ventormenta, Magni en Forjaz, Tyrande en Darnassus y Mekkatorque con los gnomos."] = "얼라이언스는 볼바르가 스톰윈드의 섭정으로, 마그니가 아이언포지를, 티란데가 다르나서스를 다스리고, 멕카토크가 노움을 이끌어요.",
	["Por la selva de Feralas caminan gigantes enormes. ¡Cuidado con sus pisadas!"] = "페랄라스 밀림에는 거대한 거인들이 걸어 다녀요. 발밑을 조심하세요!",
	["Por lograr"] = "미달성",
	["Por los canales de Entrañas corre una baba verde que mejor ni probar."] = "언더시티 수로에는 초록 점액이 흘러요. 맛보지 않는 게 좋아요.",
	["Por mazmorra"] = "던전별",
	["Por nivel: jefes, botín, misiones, la entrada y consejos."] = "레벨별: 우두머리, 전리품, 퀘스트, 입구, 공략.",
	["Por nombre"] = "이름순",
	["Por nombre, tipo o calidad (verde, azul...) y por nivel de objeto: 20, >20, 20-30. Lo que coincide se resalta."] = "이름, 종류, 품질(녹색, 파란색...)과 아이템 레벨(20, >20, 20-30)로 찾습니다. 맞는 것이 강조됩니다.",
	["Por reputación"] = "평판",
	["Por rol"] = "역할별",
	["Por terminar"] = "진행 중",
	["Por una salchicha te sigo hasta Rasganorte. Bueno, te seguiría igual."] = "소시지 하나면 노스렌드까지도 따라갈게요. 뭐, 어차피 따라가겠지만요.",
	["Por zona (este personaje)"] = "지역별 (이 캐릭터)",
	["Porcentaje de vida"] = "생명력 백분율",
	["Portal a %s"] = "차원문: %s",
	["Portales"] = "차원문",
	["Posada"] = "여관",
	["Posadas"] = "여관",
	["Posadero"] = "여관주인",
	["Posaderos"] = "여관주인",
	["Posaderos; se marca el de tu piedra de hogar."] = "여관주인입니다. 귀환석이 묶인 곳의 여관주인은 따로 표시됩니다.",
	["Preajuste «%s» listo para tus clics."] = "«%s» 프리셋을 클릭에 적용했습니다.",
	["Preajustes"] = "프리셋",
	["Preajustes listos para usar"] = "바로 쓰는 프리셋",
	["Preajustes, ajustes escondidos del juego, cámara, placas y filtros para que el mundo se vea mejor."] = "세상을 더 보기 좋게 하는 프리셋, 게임의 숨은 설정, 카메라, 이름표, 필터.",
	["Precio"] = "가격",
	["Precio de %s"] = "%s 가격",
	["Precios %s · %s objetos"] = "가격 %s · 아이템 %s개",
	["Precios al día"] = "가격 최신",
	["Precios de la subasta"] = "경매장 가격",
	["Precios viejos"] = "오래된 가격",
	["Precios y qué conviene vender."] = "가격과 팔 만한 것.",
	["Precisión"] = "적중",
	["Precisión con hechizos"] = "주문 적중",
	["Premio: %s"] = "보상: %s",
	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "타임라인, 도움 아이콘, 중간 및 위험 메시지를 켭니다.",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "블리자드 우두머리 경고 기능 전체(타임라인과 화면 메시지)를 켭니다. 이것이 꺼져 있으면 나머지도 보이지 않습니다.",
	["Prenderlo"] = "켜기",
	["Prepara tus marcos de curación"] = "치유 프레임 준비",
	["Prepara tus marcos en 3 pasos"] = "3단계로 프레임 준비",
	["Preparando %s… %s"] = "%s 준비 중… %s",
	["Preparando %s… la ficha se completa sola."] = "%s 준비 중… 정보가 자동으로 채워집니다.",
	["Preparando la enciclopedia…"] = "백과사전을 준비하는 중…",
	["Preparando lo que contiene… la ficha se completa sola."] = "안에 든 것을 준비하는 중… 정보가 자동으로 채워집니다.",
	["Preparando lo que da… la ficha se completa sola."] = "보상을 준비하는 중… 정보가 자동으로 채워집니다.",
	["Preparando lo que vende y suelta… la ficha se completa sola."] = "파는 것과 떨어뜨리는 것을 준비하는 중… 정보가 자동으로 채워집니다.",
	["Preparar la mazmorra"] = "던전 준비",
	["Prepárame"] = "준비하기",
	["Prepárate para entrar"] = "입장 준비",
	["Presencia mental: tu siguiente hechizo es instantáneo."] = "냉정: 다음 주문이 즉시 시전됩니다.",
	["Primer aviso"] = "첫 알림",
	["Primer tirón"] = "첫 입질",
	["Primero cobra lo que ya hiciste: una ruta por el camino más corto, junta por PNJ."] = "먼저 이미 끝낸 것을 제출하세요. NPC별로 묶은 가장 짧은 경로 하나.",
	["Primero con el banco de la hermandad"] = "길드 은행 우선",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "먼저 경로를 만드세요: /alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "방어 우선: 무기 막기가 훨씬 늘고 쉬는 시간이 줄어듭니다.",
	["Primero elige tu build"] = "먼저 빌드를 고르세요",
	["Primero necesitas %s, que se toma a nivel %d."] = "먼저 %s 퀘스트가 필요합니다. %d레벨에 받습니다.",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "먼저 사령관 모그레인과 싸웁니다. 모그레인이 쓰러지면 그녀가 와서 부활시킵니다.",
	["Primero prende la línea de tiempo del jefe."] = "먼저 우두머리 타임라인을 켜세요.",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "먼저 벌목기가 나옵니다. 벌목기를 부수면 스니드가 내려와 걸어서 싸웁니다.",
	["Primero toma %s"] = "먼저 %s 받기",
	["Primero un objeto, luego oro, luego una profesión y al final el banco: tú eliges el orden."] = "먼저 아이템, 다음에 골드, 그다음 전문 기술, 마지막으로 은행: 순서는 직접 정합니다.",
	["Primero: %s"] = "먼저: %s",
	["Primeros auxilios"] = "응급치료",
	["Primeros auxilios le sirve a cualquier clase, sobre todo a las que no se curan solas."] = "응급치료는 모든 직업에, 특히 스스로 치유하지 못하는 직업에 쓸모 있어요.",
	["Primeros auxilios sirve a cualquier clase: unas vendas te sacan de apuros."] = "응급치료는 모든 직업에 쓸모 있어요. 붕대 몇 개면 위기를 넘길 수 있어요.",
	["Principal"] = "주",
	["Probador"] = "미리보기 창",
	["Probar"] = "테스트",
	["Probar con 20"] = "20명으로 테스트",
	["Probar con 5"] = "5명으로 테스트",
	["Probar la línea de tiempo"] = "타임라인 테스트",
	["Probar la ventana"] = "창 써 보기",
	["Probar otra vez"] = "다시 시도",
	["Probar un aviso"] = "알림 테스트",
	["Profesiones"] = "전문 기술",
	["Profesiones (18): llegar a 150, 225 y 300 en Alquimia, Herrería, Encantamiento, Ingeniería, Peletería y Sastrería."] = "전문 기술 (18): 연금술, 대장기술, 마법부여, 기계공학, 가죽세공, 재봉술에서 150, 225, 300 달성.",
	["Profesiones que te sirven"] = "도움이 되는 전문 기술",
	["Profesiones: más puntos de habilidad, más recursos al recolectar, mejores precios con los vendedores, más platos y más peces."] = "전문 기술: 숙련도 점수 증가, 채집 자원 증가, 상인 가격 할인, 요리와 물고기 증가.",
	["Profesión"] = "전문 기술",
	["Promedio de la sesión: %s XP por hora."] = "세션 평균: 시간당 경험치 %s.",
	["Promedio de la sesión: %s XP por hora. XP ganada: %s."] = "세션 평균: 시간당 경험치 %s. 얻은 경험치: %s.",
	["Protección"] = "방어",
	["Protección para subir"] = "레벨업용 방어",
	["Proyectiles"] = "투사체",
	["Prueba"] = "테스트",
	["Prueba con %d: arrastra para mover"] = "%d명으로 테스트: 끌어서 이동",
	["Prueba con otra búsqueda o quita un filtro."] = "다른 검색어를 쓰거나 필터를 하나 빼세요.",
	["Prueba con otra palabra o elige Todas."] = "다른 단어로 찾거나 «전체»를 고르세요.",
	["Prueba con otra palabra o quita el filtro."] = "다른 단어로 해 보거나 필터를 빼세요.",
	["Prueba con otra palabra, como «pasto», «niebla» o «sombras»."] = "«풀», «안개», «그림자» 같은 다른 단어로 해 보세요.",
	["Prueba con otra palabra, en español o en inglés, o quita un filtro."] = "다른 단어(스페인어나 영어)로 찾거나 필터를 하나 빼세요.",
	["Prueba con otra palabra."] = "다른 단어로 찾아보세요.",
	["Prueba con otro filtro."] = "다른 필터를 써 보세요.",
	["Prueba de Alfa %d"] = "Alfa 테스트 %d",
	["Prueba tus clics"] = "클릭 테스트",
	["Pruébala fuera de mazmorras y bandas."] = "던전과 공격대 밖에서 테스트하세요.",
	["Préndelo para ver jefes, botín, misiones y consejos de cada mazmorra."] = "켜면 던전마다 우두머리, 전리품, 퀘스트, 공략을 볼 수 있습니다.",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "플레이어의 정신을 지배할 수 있습니다. 그 플레이어를 공격하지 말고 풀릴 때까지 기다리세요.",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "플레이어를 늑대인간으로 바꿀 수 있습니다. 그 플레이어를 공격하지 마세요. 저절로 풀립니다.",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "파티원 한 명을 재울 수 있습니다. 계속 싸우세요. 저절로 깨어납니다.",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "한 명을 재우고 주변 모두를 때릴 수 있습니다.",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "어퍼컷으로 날려 보냅니다. 치유 전담에게 가지 않도록 빨리 돌아오세요.",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "근접 플레이어를 짓밟을 수 있습니다. 근접 플레이어의 생명력을 높게 유지하세요.",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "방어 태세에서 돌진할 수 있어, 태세를 바꾸지 않고 방어 전담을 시작합니다.",
	["Puedes abrir cerraduras: practica con cajas fuertes y cofres, y ofrécele el servicio a tu grupo."] = "자물쇠를 딸 수 있어요. 금고와 상자로 연습하고 파티에 서비스해 주세요.",
	["Puedes cambiar cada tramo."] = "구간마다 바꿀 수 있습니다.",
	["Puedes crear comida y agua para todo el grupo. ¡Y si un día aprendes a hacer salchichas, me avisas!"] = "파티 전체를 위해 음식과 물을 만들 수 있어요. 언젠가 소시지 만드는 법을 배우면 알려 줘요!",
	["Puedes desollar casi cualquier bestia que mates: el cuero sale de todos lados."] = "잡은 짐승은 거의 다 무두질할 수 있어요. 가죽은 어디서나 나와요.",
	["Puedes hacerte amigo de los piratas Velasangre matando goblins de Bahía del Botín... aunque luego los guardias goblin te odiarán."] = "무법항 고블린을 잡으면 붉은해적단과 친해질 수 있어요... 대신 고블린 경비병이 당신을 미워하게 되지만요.",
	["Puedes revivir a tus compañeros fuera de combate: en una mazmorra eres de lo más valioso."] = "전투가 아닐 때 동료를 부활시킬 수 있어요. 던전에서 가장 귀한 사람 중 하나예요.",
	["Puedes tomarla"] = "받을 수 있음",
	["Puedes usarlo"] = "사용 가능",
	["Puedes vender %d cosas por unos %s."] = "%d개를 약 %s에 팔 수 있습니다.",
	["Puedes vender %s (unos %s)."] = "%s 판매 가능(약 %s).",
	["Puedo usar"] = "사용 가능한 것만",
	["Puesto"] = "적용됨",
	["Pulsa %s %s"] = "누르기: %s %s",
	["Pulsa Cocinar: cada clic hace un lote. Tienes que estar junto a un fuego."] = "요리를 누르세요. 클릭마다 한 묶음씩 만듭니다. 불 옆에 있어야 합니다.",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "'안내 시작'을 누르면 가장 가까운 곳부터 경유지를 차례로 안내합니다.",
	["Pulsa una tecla…"] = "키를 누르세요…",
	["Punta de Torio es el campamento de la Hermandad del Torio, y ahí se juntan Alianza y Horda para hacer negocios."] = "토륨 거점은 토륨 대장조합의 야영지로, 얼라이언스와 호드가 거래하러 모여요.",
	["Puntería"] = "사격",
	["Puntería para subir"] = "레벨업용 사격",
	["Punto %d de tu build (nivel %d), hasta %d/%d."] = "내 빌드의 %d번째 포인트(%d레벨), 최대 %d/%d.",
	["Puntos %d a %d de tu build (niveles %d a %d)."] = "내 빌드의 %d~%d번째 포인트(%d~%d레벨).",
	["Puntos de ruta"] = "경유지",
	["Puntos de vuelo"] = "비행 지점",
	["Puntos del legado"] = "유산 점수",
	["Puntos por gastar"] = "남은 포인트 있음",
	["Página Ruta"] = "경로 페이지",
	["Pégalo en %s del Discord de La Jauría."] = "La Jauría Discord의 %s에 붙여 넣으세요.",
	["Pícaro"] = "도적",
	["Que la manada vea a mi personaje en el mapa"] = "무리가 지도에서 내 캐릭터를 보게 하기",
	["Que me vean en el mapa"] = "지도에서 나를 보게 하기",
	["Queda 1"] = "1칸 남음",
	["Queda lejos: unos %s de camino"] = "멀리 있음: 이동 약 %s",
	["Quedan %d"] = "%d칸 남음",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "빈칸이 %d칸 남았고 팔 만한 것이 없습니다. 은행에 보관하세요.",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "빈칸이 %d칸 남았습니다. %s 판매 가능(약 %s).",
	["Quedan %s"] = "%s 남음",
	["Quedó sin pasos: agrega tramos o recalcula."] = "단계가 없습니다. 구간을 추가하거나 다시 계산하세요.",
	["Quema al enemigo un rato."] = "한동안 적을 불태웁니다.",
	["Quien repara tu equipo"] = "장비를 수리해 주는 사람",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "파티에서 Alfa를 쓰는 사람이 받아서 따라갈 수 있습니다.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras ni por canales públicos."] = "Alfa를 쓰며 공유하는 사람은 지도에서 나를 보고 따라올 수 있고, 나도 그렇습니다. 지역, 위치, 레벨, 직업을 움직일 때는 10초마다(가만히 있으면 4분마다) 보내며, 던전 안이나 공개 채널로는 절대 보내지 않습니다.",
	["Quienes van contigo y usan Alfa ven cómo vas en las misiones que comparten."] = "함께하며 Alfa를 쓰는 사람들은 공유한 퀘스트의 내 진행 상황을 볼 수 있습니다.",
	["Quiero"] = "원하는 것",
	["Quiero unirme"] = "가입하고 싶어요",
	["Quieto"] = "서 있기",
	["Quita el corte visible donde termina una capa de sombra y empieza la siguiente."] = "그림자 층이 끝나고 다음 층이 시작되는 곳의 이음매를 없앱니다.",
	["Quita la columna de botones junto al chat (menú, canales y voz). Los comandos como /s, /g o /canal siguen igual."] = "대화창 옆의 버튼 줄(메뉴, 채널, 음성)을 없앱니다. /s, /g, /채널 같은 명령어는 그대로 작동합니다.",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "주 행동 단축바 양옆의 그리핀을 없앱니다. 편집 모드에도 이 기능을 위한 자체 설정이 있습니다.",
