	["Qué está confirmado"] = "확인된 내용",
	["Qué habilidad presionar ahora y cuáles siguen, avisos de reacción y el top de daño de tu grupo."] = "지금 누를 기술과 다음 기술, 반응 알림, 파티의 피해 순위.",
	["Qué hace: %s"] = "효과: %s",
