	["Qué hacer con ella"] = "할 일",
	["Qué hacer con lo que llevas"] = "소지품 처리 방법",
	["Qué hacías, qué esperabas y qué pasó. Si puedes, cómo hacer que vuelva a pasar."] = "무엇을 하고 있었는지, 무엇을 기대했는지, 무슨 일이 일어났는지. 가능하면 다시 일어나게 하는 방법도.",
	["Qué hay que hacer"] = "할 일",
