	["Qué necesitas a tu nivel: equitación, oro y a quién ir."] = "내 레벨에 필요한 것: 타기 숙련, 골드, 찾아갈 곳.",
	["Qué necesitas a tu nivel: la equitación, el oro, a quién ir y tu montura de clase."] = "내 레벨에 필요한 것: 타기 숙련, 골드, 찾아갈 곳, 직업 탈것.",
	["Qué nivel"] = "어느 레벨",
	["Qué pide"] = "요구 사항",
