	["Qué se pinta en tus mapas"] = "지도에 표시할 것",
	["Qué se refleja en el agua: el cielo, el terreno y lo demás."] = "물에 비치는 것: 하늘, 지형, 그 밖의 모든 것.",
	["Qué se ve"] = "표시할 것",
	["Qué son"] = "무엇인가",
	["Qué son, cómo se gana cada uno, en qué se gastan y cuántos tienes."] = "무엇인지, 하나씩 어떻게 얻는지, 어디에 쓰는지, 몇 점 있는지.",
	["Qué talento poner ahora y por qué, tu build en dos clics, tu árbol y tu equipo."] = "지금 찍을 특성과 그 이유, 두 번 클릭으로 끝내는 빌드, 내 트리와 장비.",
	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "어떤 특성을 왜 찍을지, 로테이션 도우미, 파티 피해량.",
	["Qué tan definidas se ven las sombras del mundo y de los personajes."] = "세상과 캐릭터의 그림자가 얼마나 또렷한지.",
	["Qué tan difíciles pueden ser las misiones que Alfa elige (siempre de las que ya puedes tomar)."] = "Alfa가 고르는 퀘스트의 난이도 한도입니다(항상 지금 받을 수 있는 것 중에서).",
	["Qué tan grande se ve Lya."] = "Lya가 보이는 크기.",
