	["Qué tanto se ve el ícono mientras no peleas."] = "전투 중이 아닐 때 아이콘이 보이는 정도.",
	["Qué te gustaría que Alfa hiciera, o hiciera mejor, y para qué te serviría."] = "Alfa가 해 주었으면 하는 일, 또는 더 잘했으면 하는 일과 그게 어떤 도움이 될지.",
