	["Ravenholdt, la mansión de los pícaros, se esconde en las montañas de Alterac. Si no te invitan, ni la buscas."] = "도적의 저택 라벤홀트는 알터랙 산맥에 숨어 있어요. 초대받지 않았다면 찾지도 마세요.",
