	["Ventana principal nueva"] = "새 메인 창",
	["Ventormenta está cruzada por canales; los puentes unen sus barrios."] = "스톰윈드는 수로가 가로지르고, 다리가 구역들을 이어요.",
	["Ventura y Cía."] = "투자개발회사",
	["Ventura y Cía. abrió minas en Mulgore sin pedir permiso, y a los tauren eso no les hace ninguna gracia."] = "투자개발회사가 허락도 없이 멀고어에 광산을 열었고, 타우렌은 전혀 달가워하지 않아요.",
	["Ventura y Cía. tala y mina la Sierra Espolón sin piedad, y los druidas hacen lo que pueden por detenerla."] = "투자개발회사가 돌발톱 산맥을 무자비하게 벌목하고 채굴하고 있어요. 드루이드들은 막으려고 애써요.",
	["Ventura y Cía. trae máquinas enormes para talar los árboles más viejos de la sierra."] = "투자개발회사는 산맥에서 가장 오래된 나무를 베려고 거대한 기계를 가져와요.",
