	["verde"] = "초록색",
	["viernes"] = "금요일",
	["visto %s"] = "마지막 접속: %s",
	["y"] = "및",
	["y %d más"] = "외 %d개",
	["y %d piezas más"] = "외 %d개",
	["y %d recursos más"] = "외 자원 %d개",
	["y 1 pieza más"] = "외 1개",
	["y más"] = "등",
	["ya la sabes"] = "배움",
	["ya la tienes"] = "이미 보유",
	["ya lo ganaste"] = "이미 획득",
	["ya no se consigue"] = "더 이상 얻을 수 없음",
	["¡%d misiones entregadas hoy! Así se caza en manada."] = "오늘 제출한 퀘스트 %d개! 이게 무리의 사냥이에요.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "오늘 퀘스트 %d개! 아무도 못 말려요.",
	["¡%s!"] = "%s!",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s! 며칠 만이에요. 오늘에서 어디까지 했는지 알려 줄게요.",
	["¡Abrumar!"] = "제압!",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "거기 있었네요, %s! 조언이 필요하면 저를 클릭하세요.",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "일어나요, 늑대! 다시 싸우기 전에 생명력과 마나를 회복하세요.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "일어나요, 늑대! 쓰러지는 것도 사냥의 일부예요. 되살아나면 장비를 수리하세요.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "일어나요, 늑대! 영혼을 해방하세요. 시체로 갈지 영혼의 치유사에게 갈지 화살표가 알려 줘요.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "일어나요, 늑대! 너무 많았다면 다음엔 하나씩 끌어요.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "레벨 업, %d레벨! 남은 특성 점수가 있으면 잊지 마세요.",
	["¡Así se ve un aviso!"] = "알림은 이렇게 보입니다!",
	["¡Ataque de la victoria!"] = "연전연승!",
	["¡Bien hecho! %s"] = "잘했어요! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "좋은 아침, %s! 아제로스에 해가 떴어요. 가 볼까요?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "좋은 저녁이에요, %s! 우리 늑대들은 밤에 제일 사냥을 잘해요.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "좋은 오후예요, %s! 퀘스트 하기 딱 좋은 시간이에요.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "안녕하세요, %s! 한 걸음씩 가면 멀리 가요.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "좋은 아침이에요, %s! 기지개 켜고 하품하면 준비 끝이에요.",
	["¡Completaste %s!"] = "%s 완료!",
	["¡Contraataque!"] = "역습!",
	["¡De vuelta con la manada!"] = "무리로 돌아오셨군요!",
	["¡Ejecutar!"] = "마무리 일격!",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "텔사마에서 순대를 팔아요! 텔사마 순대는 거의 소시지예요... 하나 사 줄래요?",
	["¡Es ahora! Hasta las %s"] = "지금 진행 중! %s까지",
	["¡Hola!"] = "안녕하세요!",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "안녕하세요! 저는 알파가 믿는 암컷 늑대 Lya예요. 무리를 지키고 길을 함께 걸어요.",
	["¡Hola, %s!"] = "안녕하세요, %s 님!",
	["¡Hola, %s! Hoy huele a buena cacería."] = "안녕하세요, %s! 오늘은 좋은 사냥 냄새가 나요.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "안녕하세요, %s! 오후가 평화로워 보여요. 오늘은 뭘 사냥할까요?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "안녕하세요, %s! 달밤이네요. 무리에게 딱이에요.",
	["¡Listo! %s precios guardados."] = "완료! 가격 %s개를 저장했습니다.",
	["¡Listo! Alfa ya es tuyo"] = "완료! 이제 나만의 Alfa입니다",
	["¡Lo tienes! %s ×%d"] = "낚았어요! %s ×%d",
	["¡Martillo de cólera!"] = "천벌의 망치!",
	["¡Mordedura de mangosta!"] = "살쾡이의 이빨!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "%d레벨! 잠깐 자랑해도 돼요. 당신이 해낸 거예요.",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "%d레벨! 단단한 걸음, 날카로운 송곳니.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "%d레벨! 노력이 보여요. 계속 이렇게 가요.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "%d레벨! 아우우! 이게 무리가 크는 방식이에요.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "%d레벨, 잘했어요! 상급자에게 새로 배울 게 있는지 보세요.",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "10레벨! 이제 특성이 있어요. 천천히 고르세요. 특성 페이지가 도와줘요.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "20레벨! 이제 진짜 던전도 갈 수 있어요. 파티를 꾸릴까요?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "30레벨! 벌써 절반이에요. 무리가 정말 자랑스러워해요!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "40레벨! 이제 타기를 배울 수 있어요. 첫 탈것이 기다려요!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "50레벨! 정상이 코앞이에요. 다가올 일을 위해 골드를 모으세요.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "60레벨! 해냈어요, 알파! 이제 큰 사냥을 할 차례예요.",
	["¡Plan terminado!"] = "계획 완료!",
	["¡Primera vez! Nuevo en tu diario"] = "처음! 도감에 새로 등록",
	["¡Qué buena racha traes! Sigue así."] = "기세가 대단해요! 계속 이렇게 가요.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "돌아와서 정말 반가워요, %s! 저는 여전히 여기서 등 뒤를 지키고 있어요.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "다시 만나서 반가워요! 이번 버전이 나와 내 무리에게 가져온 것들이에요.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "만나서 반가워요, %s! 무리가 기다리고 있었어요.",
	["¡Repara tu equipo!"] = "장비를 수리하세요!",
	["¡Revancha!"] = "복수!",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "%d레벨이 됐어요! 레벨마다 더 강해져요.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "보고 싶었어요, %s! 경로는 두고 간 그대로예요.",
	["¡Terminaste %s!"] = "완료했습니다: %s!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "이 가이드를 끝냈습니다! 다음 가이드를 골라 무리와 함께 계속 레벨을 올리세요.",
	["¡Terminaste tu guía!"] = "가이드를 끝냈습니다!",
	["¡Tú!"] = "당신!",
	["¡Volviste, %s! Estira las patas y vámonos."] = "돌아왔네요, %s! 다리 쭉 펴고 가요.",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "이제 %d레벨! 무리가 당신을 위해 울부짖어요.",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "퀘스트를 %d개 끝냈어요! 보상 받으러 가요.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "«%s»에는 사연이 있어요. 들려줄까요?",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "«%s» 끝났어요. 결말이 들을 만해요. 들려줄까요?",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "편의 기능의 «카메라 더 멀리 빼기»가 켜져 있어 접속할 때 이 값보다 우선합니다.",
	["«Buscar cerca» en la página Hoy"] = "오늘 페이지의 «근처 찾기»",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "«근처 찾기»는 필요한 곳으로 화살표로 안내하고, «내 계획»은 자동으로 체크되는 나만의 목표를 만듭니다.",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "«Alfa와 같게»는 설정 > 외형의 스타일을 따르고 함께 바뀝니다.",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "«준비하기»는 지금 받을 수 있는 퀘스트만 받고 입구로 안내합니다.",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "«항상»은 마법부여사 친구가 도와줄 때 쓰세요. 마력 추출 표는 추정치입니다.",
	["¿Abandonar %d misiones?"] = "퀘스트 %d개를 포기할까요?",
	["¿Abandonar %d misión?"] = "퀘스트 %d개를 포기할까요?",
	["¿Algo raro?"] = "문제가 있나요?",
	["¿Aplicar estos talentos?"] = "이 특성을 적용할까요?",
	["¿Borrar el diario?"] = "일지를 지울까요?",
	["¿Borrar el historial?"] = "기록을 삭제할까요?",
	["¿Borrar esta ruta?"] = "이 경로를 삭제할까요?",
	["¿Borrar este build?"] = "이 빌드를 삭제할까요?",
	["¿Borrar este plan?"] = "이 계획을 삭제할까요?",
	["¿Borrar lo que descubriste?"] = "내가 찾은 지점을 삭제할까요?",
	["¿Borrar los precios?"] = "가격을 삭제할까요?",
	["¿Borrar todo tu progreso?"] = "진행 상황을 모두 삭제할까요?",
	["¿Borrar todo tu registro de pesca?"] = "낚시 기록을 모두 지울까요?",
	["¿Borrar todos tus marcadores?"] = "마커를 모두 삭제할까요?",
	["¿Cuánto decide Alfa por ti en el camino?"] = "길에서 Alfa가 얼마나 대신 결정할까요?",
	["¿Cómo quieres hacerlo?"] = "어떻게 할까요?",
	["¿Cómo quieres que se vea Alfa?"] = "Alfa를 어떤 모습으로 할까요?",
	["¿Empezar el medidor de cero?"] = "측정기를 처음부터 다시 시작할까요?",
	["¿Empezar una sesión nueva?"] = "새 세션을 시작할까요?",
	["¿En qué idioma quieres Alfa?"] = "Alfa를 어떤 언어로 쓸까요?",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "이 냄새, 여관 빵이에요? 제 코는 절대 틀리지 않아요.",
	["¿La haces con tu manada o la saltas?"] = "무리와 함께 할까요, 건너뛸까요?",
	["¿La vuelves a tomar o la sacas de la ruta?"] = "다시 받을까요, 경로에서 뺄까요?",
	["¿Llevamos tu estilo al resto de la pantalla?"] = "내 스타일을 화면의 나머지 부분에도 입힐까요?",
	["¿Olvidar a este personaje?"] = "이 캐릭터를 잊을까요?",
	["¿Olvidar tu progreso?"] = "진행 상황을 지울까요?",
	["¿Otra vez?"] = "또요?",
	["¿Oíste eso? Nada… solo el viento. Sigamos."] = "방금 들었어요? 아무것도… 그냥 바람이네요. 계속 가요.",
	["¿Paramos a comer? Mi panza ya está aullando."] = "밥 먹고 갈까요? 배가 벌써 울부짖고 있어요.",
	["¿Por dónde sigues?"] = "어디로 갈까요?",
	["¿Quieres cazar con nosotros? Pulsa el botón: Alfa busca a un oficial conectado y te abre un susurro con tu mensaje listo para que lo envíes con Intro."] = "우리와 함께 사냥하시겠어요? 버튼을 누르면 Alfa가 접속 중인 관리자를 찾아, 메시지가 준비된 귓속말을 열어 줍니다. Enter로 보내기만 하면 됩니다.",
	["¿Quieres que la manada te vea en el mapa del juego?"] = "무리가 게임 지도에서 나를 보게 할까요?",
	["¿Qué buscas?"] = "무엇을 찾으세요?",
	["¿Qué es Alfa?"] = "Alfa란?",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Alfa는 상인과 이동에서 무엇을 하나요?",
	["¿Qué hace Alfa con tus misiones?"] = "Alfa는 퀘스트로 무엇을 하나요?",
	["¿Qué hacemos hoy?"] = "오늘은 뭘 할까요?",
	["¿Qué hago con mis objetos?"] = "내 아이템은 어떻게 할까?",
	["¿Qué nos quieres contar?"] = "무엇을 알려 주고 싶나요?",
	["¿Qué quieres hacer hoy?"] = "오늘은 무엇을 할까요?",
	["¿Qué quieres hacer?"] = "무엇을 할까요?",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Alfa는 다른 플레이어에게 대신 어떻게 답하나요?",
	["¿Qué sigue?"] = "다음은?",
	["¿Reiniciar los gráficos?"] = "그래픽을 다시 시작할까요?",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "암컷 늑대가 무리에서 귀가 제일 밝은 거 알아요? 음, 제 말로는 그래요.",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "알고 있었나요? Alfa는 완료한 퀘스트를 짧은 경로 하나로 묶어 줘요.",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "알고 있었나요? Alfa에는 스타일이 세 가지 있어요: Alfa, WoW 클래식, 유리. 저도 고른 스타일을 입어요.",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "알고 있었나요? 아이템을 Alt+클릭하면 백과사전에서 열려요.",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "알고 있었나요? 근처 찾기는 가장 가까운 대장장이, 은행, 비행 조련사로 안내해요.",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "알고 있었나요? 거래는 상인에게 팔지, 경매에 올릴지, 가공할지 알려 줘요.",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "알고 있었나요? /alfa reportar로 toxic3000에게 오류나 아이디어를 전할 수 있어요.",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "알고 있었나요? 낚시 기능으로 키 하나로 던지고 낚아 올려요.",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "알고 있었나요? 저를 오른쪽 클릭하면 한 시간 동안 조용히 시키거나 조언을 줄일 수 있어요.",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "알고 있었나요? 미니맵 버튼으로 Alfa 전체를 숨기고 다시 불러올 수 있어요.",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "알고 있었나요? Alfa 지도는 지형, 내 마커, 근처에 있는 것을 보여 줘요.",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "알고 있었나요? 가방에서 내 가방, 은행, 모든 캐릭터의 물건을 볼 수 있어요.",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "알고 있었나요? La Jauría에서 내 파티와 Alfa를 쓰는 무리를 볼 수 있어요.",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "알고 있었나요? 내 계획에서 나만의 목표 목록을 만들면 화살표가 안내해요.",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "알고 있었나요? 특성에서 지금 찍을 특성과 그 이유를 볼 수 있어요.",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "알고 있었나요? 백과사전은 모든 아이템, NPC, 퀘스트를 어디서 찾는지 알려 줘요.",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "알고 있었나요? 오늘 페이지는 지금 할 일과 캐릭터의 급한 일을 알려 줘요.",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "알고 있었나요? 던전은 내 차례인 던전과 준비하는 법을 알려 줘요.",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "알고 있었나요? 채집은 지도에 광석, 약초, 물고기 떼를 표시해 줘요.",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "제가 제일 좋아하는 음식이 소시지라고 말했던가요? 그 무엇도 못 따라와요.",
	["¿Una carrerita hasta allá? Yo gano."] = "저기까지 달리기 시합할래요? 제가 이길 거예요.",
	["¿Usar tu hechizo nuevo?"] = "새 주문을 쓸까요?",
	["¿Usar «%s»?"] = "«%s»을(를) 쓸까요?",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "판매, 경매, 제작? (escanear: 스캔, precio <아이템>: 가격)",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "판매, 경매, 제작? 아이템마다 골드를 가장 많이 버는 방법을 알려 줍니다.",
	["¿Volver a lo de antes?"] = "이전으로 되돌릴까요?",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "%s 구석구석 다 둘러봤어요? 볼 곳은 늘 남아 있어요.",
	["¿Ya hiciste esta mazmorra?"] = "이 던전을 이미 해 봤나요?",
	["¿qué quieres hacer?"] = "무엇을 할까요?",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "/alfa 또는 미니맵의 늑대로 여세요. 이 설정을 바꾸려면: /alfa bienvenida.",
	["Ámbar"] = "호박색",
	["Ángel de la resurrección"] = "영혼의 치유사",
	["Ángeles de la resurrección"] = "영혼의 치유사",
	["Árboles, rocas, cercas y adornos: más alto, se ven completos desde más lejos."] = "나무, 바위, 울타리, 장식물: 높일수록 더 먼 곳에서도 온전히 보입니다.",
	["Área"] = "광역",
	["Élite"] = "정예",
