	["Íconos de ayuda"] = "도움 아이콘",
	["Ídolo"] = "우상",
	["×%d"] = "×%d",
	["Última posición enviada %s."] = "마지막 위치 전송: %s.",
	["Última: %s ×%d · %d en la sesión"] = "마지막: %s ×%d · 이번 세션 %d",
	["Último envío: %s por %s, respuesta %s"] = "마지막 전송: %s, 경로 %s, 결과 %s",
	["Último escaneo %s · %s objetos con precio."] = "마지막 스캔 %s · 가격이 있는 아이템 %s개.",
	["Únete a un grupo o banda para anunciar el top."] = "순위를 알리려면 파티나 공격대에 들어가세요.",
	["Únete a un grupo para compartir tus marcadores."] = "마커를 공유하려면 파티에 들어가세요.",
