	["última: %s"] = "최근: %s",
	["• GatherLite, de Wuild (MIT): la base de nodos de recolección."] = "• GatherLite, 제작 Wuild (MIT): 채집 지점 데이터베이스.",
	["• Letras Inter, Fira Sans y Open Sans (SIL Open Font License 1.1)."] = "• Inter, Fira Sans, Open Sans 글꼴 (SIL Open Font License 1.1).",
	["• OpenMap, de OpenMap contributors (MIT): la lógica del mapa continuo y las máscaras de territorio."] = "• OpenMap, 제작 OpenMap contributors (MIT): 이어진 지도 로직과 영역 마스크.",
	["• Polestar, de The Polestar authors (GPL-3.0): el motor de guías, navegación y datos (github.com/fitzforge/polestar)."] = "• Polestar, 제작 The Polestar authors (GPL-3.0): 가이드, 길 찾기, 데이터 엔진 (github.com/fitzforge/polestar).",
	["• Shortest Path Forever, de Cillian Berragan (GPL-3.0-or-later): la navegación y los servicios cercanos."] = "• Shortest Path Forever, 제작 Cillian Berragan (GPL-3.0-or-later): 길 찾기와 근처 서비스.",
	["• TerrainWorldMap, de Dramacydal (MIT): la tabla de mosaicos del terreno del mapa."] = "• TerrainWorldMap, 제작 Dramacydal (MIT): 지도 지형 조각 표.",
	["• pfQuest, de shagu (MIT): datos de misiones, PNJ y objetos."] = "• pfQuest, 제작 shagu (MIT): 퀘스트, NPC, 오브젝트 데이터.",
